object Main {
  import java.io._
  import java.util.StringTokenizer

  import scala.collection.mutable
  import scala.util.Sorting
  import math.{abs, max, min}
  import mutable.{ArrayBuffer, ListBuffer}
  import scala.reflect.ClassTag

  val MOD = 1000000007
  val out = new PrintWriter(System.out)
  val sc = new InputReader(System.in)

  def solve(): Unit = {
    val sc = new InputReader(System.in)
    var L = sc.nextInt()
    val X = Integer.highestOneBit(L)
    val N = log2(X) + 1

    case class Edge(a: Int, b: Int, w: Int)
    var es = ArrayBuffer[Edge]()

    rep(N - 1) { k =>
      val i = k + 1
      es += Edge(i, i + 1, 1 << k)
      es += Edge(i, i + 1, 0)
    }
    L -= X

    var cur = X
    while(L > 0) {
      val x = Integer.highestOneBit(L)
      val k = log2(x)
      es += Edge(1 + k, N, cur)
      L -= x
      cur += x
    }

    out.println(s"$N ${es.length}")
    es foreach { e =>
      out.println(s"${e.a} ${e.b} ${e.w}")
    }
  }

  def log2(x: Int): Int = {
    if (x == 1) 0 else Integer.toBinaryString(x - 1).length
  }

  def main(args: Array[String]): Unit = {
    solve()
    out.flush()
  }

  class InputReader(val stream: InputStream) {
    private val reader = new BufferedReader(new InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer = _

    def next(): String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = next().toInt
    def nextLong(): Long = next().toLong
    def nextChar(): Char = next().charAt(0)
  }
  def ni(): Int = sc.nextInt()
  def nl(): Long = sc.nextLong()
  def nc(): Char = sc.nextChar()
  def ns(): String = sc.next()
  def ns(n: Int): Array[Char] = ns().toCharArray
  def na(n: Int): Array[Int] = map(n)(_ => ni())
  def nm(n: Int, m: Int): Array[Array[Char]] = map(n) (_ => ns(m))
  def rep(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = offset
    val N = n + offset
    while(i < N) { f(i); i += 1 }
  }
  def rep_r(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = n - 1 + offset
    while(i >= offset) { f(i); i -= 1 }
  }

  def map[@specialized A: ClassTag](n: Int)(f: Int => A): Array[A] = {
    val res = Array.ofDim[A](n)
    rep(n)(i => res(i) = f(i))
    res
  }

  implicit class ArrayOpts[A](val as: Array[A]) extends AnyVal {
    // todo Orderingだとboxing発生するので自作Orderを用意したい
    def maxByOpt[B: Ordering](f: A => B): Option[A] = {
      if (as.nonEmpty) Some(as.maxBy(f)) else None
    }

    def grpBy[K](f: A => K): mutable.Map[K, ArrayBuffer[A]] = {
      val map = mutable.Map.empty[K, ArrayBuffer[A]]
      rep(as.length)(i => map.getOrElseUpdate(f(as(i)), ArrayBuffer()) += as(i))
      map
    }

    def sumBy[B](f: A => B)(implicit num: Numeric[B]): B = {
      var sum = num.zero
      rep(as.length)(i => sum = num.plus(sum, f(as(i))))
      sum
    }

    def minByEx[B](f: A => B, ixRange: Range = as.indices)(implicit cmp: Ordering[B]): (A, B) = {
      limit(f, ixRange)(cmp.lt)
    }

    def maxByEx[B](f: A => B, ixRange: Range = as.indices)(implicit cmp: Ordering[B]): (A, B) = {
      limit(f, ixRange)(cmp.gt)
    }

    private def limit[B](f: A => B, ixRange: Range)(cmp: (B, B) => Boolean): (A, B) = {
      var limA = as(ixRange.head)
      var limB = f(limA)

      for (i <- ixRange.tail) {
        val a = as(i)
        val b = f(a)
        if (cmp(b, limB)) {
          limA = a
          limB = b
        }
      }
      (limA, limB)
    }
  }

  implicit class IterableOpts[A](val as: Iterable[A]) extends AnyVal {
    def sumBy[B](f: A => B)(implicit num: Numeric[B]): B = {
      as.foldLeft(num.zero)((acc, a) => num.plus(acc, f(a)))
    }
  }
}

object Main {
  import java.util.Scanner

  implicit class RichScanner(sc: Scanner) {
    def readStrings(n: Int): Array[String] = Array.fill(n) { sc.next() }
    def readInts(n: Int): Array[Int] = Array.fill(n) { sc.nextInt() }
    def readLongs(n: Int): Array[Long] = Array.fill(n) { sc.nextLong() }
    def readLineStrings: Array[String] = sc.nextLine().split(' ')
    def readLineInts: Array[Int] = readLineStrings.map(_.toInt)
    def readLineLongs: Array[Long] = readLineStrings.map(_.toLong)
  }

  def main(args: Array[String]): Unit = solve(new Scanner(System.in))

  def solve(sc: Scanner): Unit = {
    val L = sc.nextInt()

    // number of fibres
    val chainLength = (math.log(L) / math.log(2)).toInt

    val fibreLengths = (0 until chainLength).map(i => 1 << i).toArray

    val supplementaryChainLengths = ((chainLength - 1) to 0 by -1)
      .map(i => { (L & (1 << i)) != 0 })
      .map(present => if (present) Some(0) else None)
      .toArray

    // update
    (1 to chainLength).foreach(i => {
      // supplementary path is present
      if (supplementaryChainLengths(i - 1).isDefined) {
        val previousSupplementaryPath = supplementaryChainLengths.slice(0, i - 1).indexWhere(_.isDefined)

        val largestSubpath = if (previousSupplementaryPath != -1) {
          supplementaryChainLengths(previousSupplementaryPath).get + fibreLengths.slice(previousSupplementaryPath + 1, i).sum
        } else {
          fibreLengths.slice(0, i).sum
        }

        supplementaryChainLengths(i - 1) = Some(largestSubpath + 1)
        if (i < chainLength) {
          fibreLengths(i) = largestSubpath + 2
        }
      }
    })

    // print main chain
    (0 until chainLength).foreach(i => {
      println(s"${i + 1} ${i + 2} 0")
      println(s"${i + 1} ${i + 2} ${fibreLengths(i)}")
    })

    // print supplementary chain
    (0 until chainLength).foreach(i => {
      if (supplementaryChainLengths(i).isDefined) {
        println(s"1 ${i + 2} ${supplementaryChainLengths(i).get}")
      }
    })
  }
}

