void Solve(ll) {
  ll l;
  if (not(cin >> l)) return;
  vector<tuple<ll, ll, ll>> edges;
  const ll bits = 19;
  VEVE(b, 0, bits - 1) {
    edges.emplace_back(bits - b, bits - b + 1, 0);
    edges.emplace_back(bits - b, bits - b + 1, 1 << b);
  }
  VEVE(b, 0, bits) if (l >> b & 1) {
      l -= 1 << b;
      edges.emplace_back(1, bits - b + 1, l);
    }
  if (l > 0) {
    edges.emplace_back(1, 2, 0);
    edges.emplace_back(1, 2, 1 << 18);
  }
  cout << (bits + 1) << " " << SIZE(edges) << endl;
  RARA(e, edges) {
    cout << get<0>(e) << " " << get<1>(e) << " " << get<2>(e) << endl;
