    add_edge(i, i+1, (1<<(n-i-2)));
    add_edge(i, i+1, 0);
  }
  for(Int i=0;i<=limit;i++) add_edge(T-1, T, i);

  add(L-1);
  printG();
  check(L);  
  return 0;
}

