vector<iii> E;

void dfs(multiset<int>& s, int v, int n, int cost) {
    if (v == n) {
        s.insert(cost);
        return;
    }
    for (iii e : E) {
        int a, b, w;
        tie(a, b, w) = e;
        if (a == v) {
            dfs(s, b, n, cost + w);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    int L;
    cin >> L;
    --L;
    int n = 1;
    while ((1 << n) <= L+1) ++n;
    //++n;
    for (int v = n-1; v >= 1; --v) E.pb(iii(v, v+1, 0));
    for (int v = n-1; v >= 1; --v) E.pb(iii(v, v+1, 1<<(n-1-v)));
    if ((L & (L+1)))
    for (int i = 0; (1<<i) <= L; ++i) {
        int bit = 1 << i;
        if (!(L & bit)) continue;
        int j = i-1;
        for (; j >= 0 && !((1<<j) & L); --j);
        if (j < 0) {
            E.pb(iii(1, n, L));
            continue;
        }
        int val = L & ~(bit - 1);
        E.pb(iii(1, n-j, val));
    }
    sort(all(E));

    assert(n <= 20);
    assert(E.size() <= 60);

    cout << n << ' ' << E.size() << '\n';
    for (iii e : E)
        cout << get<0>(e) << ' ' << get<1>(e) << ' ' << get<2>(e) << '\n';

    return 0;
    multiset<int> s;
    dfs(s, 1, n, 0);
    //for (int x : s) cout << "path: " << x << '\n';
    cout.flush();
    vector<int> v(s.begin(), s.end());
    assert((int)v.size() == L+1);
    for (int i = 0; i < L; i++) {
        assert(v[i] == i);
    }
}

