int DFS(int k)
{
	if(k==0) return 1;
	int nex=DFS((k-1)/2);
	int now=nex+1;
	if(k%2==0)
	{
		add(nex,now,0);
		add(nex,now,k/2);
		add(1,now,k);
	}
	else
	{
		add(nex,now,0);
		add(nex,now,k/2+1);
	}
	return now;
}
