void solve(istream& cin) {
    ll L;
    while(cin >> L){
        ll d = 1, tmp = L;
        vector<int> u, v, w;
        int N, M;
        int now_n = 1;
        auto set = [&u,&v,&w] (int a, int b, int c){
            u.push_back(a);
            v.push_back(b);
            w.push_back(c);
        };
        while(L >= 2*d){
            set(now_n, now_n+1, 0);
            set(now_n, now_n+1, d);
            d *= 2;
            now_n++;
        }
        d /= 2;
        N = now_n;
        ll k = 1 << (N-2);
        for (int t = N-1; t >= 1; --t) {
            if(L - k >= d){
                set(t, N, L - k);
                L -= k;
            }
            k /= 2;
        }

        if(v.size() >= 60 || N > 20){
            cerr << "damedacore\n";
        }
        else {
            cout << N << ' ' << v.size() << '\n';
            for (int i = 0; i < v.size(); ++i) {
                cout << u[i] << ' ' << v[i] << ' ' << w[i] << '\n';
            }
        }

    }
}

