using namespace std;

bool prime[N + 5] = {0};

void sprime() {
  int i, j;
  prime[0] = 1;
  prime[1] = 1;
  for(i = 2; i < sqrt(N); ++i)
    if(!prime[i])
      for(j = 2; i * j <= N; ++j) prime[i * j] = 1;
}

long long l, n = 20, m = 0, now = 1;
long long ans[60][3] = {0};
long long store[20] = {0};

int solve(int l, int r, int now, int nextn);

int main() {
  long long i;
  sprime();
  cin >> l;
  for(i = 1; i < 20; ++i) {
    ans[m][0] = i;
    ans[m][1] = i + 1;
    ans[m][2] = 0;
    ++m;
    ++store[i];
  }
  if(l <= 42)
    for(i = 1; i < l; ++i) {
      ans[m][0] = 1;
      ans[m][1] = 20;
      ans[m][2] = i;
      ++m;
    }
  else
    solve(1, 20, l, 1);
  cout << n << " " << m << endl;
  for(i = 0; i < m; ++i)
    cout << ans[i][0] << " " << ans[i][1] << " "
         << ans[i][2] << endl;
  return 0;
}

int solve(int l, int r, int now, int nextn) {
  if(now < 3) {
    for(int i = nextn; i < now * nextn; i += nextn) {
      ans[m][0] = l;
      ans[m][1] = l + 1;
      ans[m][2] = i;
      ++m;
    }
  }

  if(!prime[now]) {
    ans[m][0] = l;
    ans[m][1] = r;
    ans[m][2] = now;
    ++m;
    --now;
  }
  for(int i = sqrt(sqrt(now)) + 1; i >= 0; --i) {
    if(now % i == 0) {
      solve((l + r) / 2, r, now / i,
            solve(l, (l + r) / 2, i, nextn));
      break;
    }
  }
  return nextn * now;
}

