using T = tuple<int32, int32, int32>;

vector<T> G;
int64 N=20, M;
int64 idx;

void answer(){
	cout << N << " " << G.size() << endl;
	REP(i, G.size()){
		int32 a, b, c;
		tie(a, b, c) = G[i];
		cout << a+1 << " " << b+1 << " " << c << endl;
	}
}

void init(int64 X){
	REP(i, N-1){
		G.push_back(T(i, i+1, 0));
	}
	int64 a = 0;
	idx = 0;
	while((1<<a)-1 <= X-1){
		a++;
	}
	a--;
	while(1<<idx <= X){
		idx++;
	}
	idx--;

	REP(i, a){
		G.push_back(T(i, i+1, 1<<i));
	}
	if((1 << a)-1 == X){
		answer();
		exit(0);
	}
}

int main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int64 L;
	cin >> L;
	init(L);

	while(idx >= 0){
		if(L >> idx & 1){
			int32 k = idx-1;
			while(k >= 0 && !(L >> k & 1)){k--;}
			if(k >= 0){
				G.push_back(T(k, N-1, L & ~((1<<(k+1))-1)));
				cerr << (L & ~((1 << (k+1))-1)) << endl;
			}
		}
		idx--;
	}

	answer();
}

