	void toposort(int s)
	{
	    int now=0;
	    for (int i=1;i<=n;i++) id[i]=0;
		for (int i=0;i<g.size();i++)
		{
			edge u=g[i];
			if (!u.x&&!u.y) continue;
			add_edge(u.x,u.y);
			++in[u.y];
		}
		std::queue<int> q;
		for (int i=1;i<=p;i++) id[i]=0;
	    for (int i=1;i<=p;i++) if (!in[i]&&!used[i]) id[i]=++now,q.push(i);
	    while (!q.empty())
        {
        	int v=q.front();q.pop();
        	for (int i=0;i<a[v].size();i++)
        	{
				int u=a[v][i];
				if (used[u]) continue;
        		--in[u];
        		if (!in[u]) id[u]=++now,q.push(u);
			}
		}
    }
