{
	IOS;
	cin>>k;
	v.push_back(1);
	int cur=1;
	store[1]=1;
	int idx=2;
	int edges=0;
	for(int i=2;cur*2<=k;i++, cur*=2)
	{
		g[v.back()].push_back({i, 0});
		g[v.back()].push_back({i, cur});
		v.push_back(i);
		store[cur*2]=i;
		idx++;
		edges+=2;
	}
	int weight=0;
	idx--;
	int lastnode=0;
	for(int i=19;i>=0;i--)
	{
