void Add(int u1,int v1,int w1)
{
	m++;
	u[m]=id[u1],v[m]=id[v1],w[m]=w1;
}
void dfs(int x)
{
	if(id[x]) return;
	if(!x) { id[x]=++n; return; }
	if(x&1)
	{
		dfs(x/2);
		if(!id[x]) id[x]=++n;
		Add(x/2,x,x/2+1);
		Add(x/2,x,0);
	}
	else
	{
		dfs(x/2-1);
		if(!id[x]) id[x]=++n;
		Add(x/2-1,x,x/2);
		Add(x/2-1,x,0);
		Add(0,x,x);
	}
}
