using namespace std;

int pow(int n, int k){
    int ans = 1;
    for(int i = 0; i < k; i++){
        ans *= n;
    }
    return ans;
}

int main(){
    int L;
    cin >> L;
    int tmp = 1, cnt = 0;
    while(L >= tmp){
        tmp *= 2;
        cnt++;
    }
    for(int i = 1; i < cnt ; i++){
        cout << i << ' ' << i+1 << ' ' << 0 << endl;
        cout << i << ' ' << i+1 << ' ' << pow(2, i-1) << endl;
    }
    tmp = pow(2, cnt-1);
    if(L%2 == 1){
        cout << 1 << ' ' << cnt << ' ' << tmp << endl;
        tmp+= 1;
        L = (L - 1)/2;
    }
    for(int i = 2; i < cnt; i++){
        if(L%2 == 1){
