LL read(){
    LL x=0,f=1;
    char ch=getchar();
    while (!isdigit(ch)&&ch!='-')
        ch=getchar();
    if (ch=='-')
        f=-1,ch=getchar();
    while (isdigit(ch))
        x=(x<<1)+(x<<3)+ch-48,ch=getchar();
    return x*f;
}
int n,m=0,L;
int A[N],B[N],C[N];
void push(int a,int b,int c){
    m++;
    A[m]=a;
    B[m]=b;
    C[m]=c;
}
int main(){
    L=read()-1;
    n=20;
    int cnt=1;
    while (L>=0){
        if (L==0){
            if (cnt<n)
                push(cnt,n,0);
            break;
        }
        if (L==1){
            push(cnt,n,0);
            push(cnt,n,1);
            break;
        }
        if (L%2==0)
            push(cnt,n,L);
        L=(L+1)/2;
        push(cnt,cnt+1,0);
        push(cnt,cnt+1,L);
        L--;
        cnt++;
    }
    printf("%d %d\n",n,m);
    for (int i=1;i<=m;i++)
        printf("%d %d %d\n",A[i],B[i],C[i]);
