	void relabel()
	{
		std::vector<edge> tmp;
		toposort(1);
		for (int i=0;i<g.size();i++) tmp.push_back(edge{id[g[i].x],id[g[i].y],g[i].v,g[i].w});
		g.clear();
		for (int i=0;i<tmp.size();i++) g.push_back(tmp[i]);
		q=g.size();
		int del=0;
		for (int i=1;i<=p;i++) if (used[i]) ++del;
		p=p-del;
	}
	void combine(int x,int k)
	{
		if (!g[k].x) return;
		printf("combine %d %d\n",x,k);
//		if (g[k].y!=x) puts("no");
		used[x]=1;
		for (int i=0;i<g.size();i++)
		{
			if (g[i].x==x) add(g[k].x,g[i].y,g[k].v+g[i].v,g[i].w);
		    g[i].x=g[i].y=g[i].v=g[i].w=0;
		}
		g[k].x=g[k].y=g[k].v=g[k].w=0;
		x=0;    
	}
	int merge()
	{
		for (int i=1;i<=p;i++) pp[i]=in[i]=0;
		for (int i=0;i<g.size();i++)
		{
			int xx=g[i].x,yy=g[i].y;
			++in[yy];pp[yy]=i;
		}
		for (int i=1;i<=p;i++) printf("%d\n",in[i]);
		for (int i=1;i<=p;i++) if (in[i]==1) combine(i,pp[i]);
		for (int i=1;i<=p;i++) pp[i]=in[i]=0;
	}
