        cout << 2 << " " << 2 << '\n';
        cout << 1 << " " << 2 << " " << 0 << '\n';
        cout << 1 << " " << 2 << " " << 1 << '\n';
        cout << 1 << " " << 2 << " " << 2 << '\n';
        return 0;
