    int n = 3, k = 7;
    while (k <= l) {
        n++;
        k *= 2;
        k++;
    }
    vector<vector<int>> ans;
    k = 0;
    for (int i = 0; i < n - 1; i++) {
        ans.push_back({i + 1, i + 2, 1 << (n - i - 2)});
        ans.push_back({i + 1, i + 2, 0});
        k += 1 << (n - i - 2);
    }
    debug(k);
    while (k < l) {
        k++;
        int d = l - k;
        if (d == 0) {
            ans.push_back({1, n, l});
            break;
        }
        if (d == 1) {
            ans.push_back({1, n, l});
            ans.push_back({1, n, l - 1});
            break;
