int pow(int n)
{
    if (n == 0) return 1;
    if (n%2 == 0) {
        int tmp = pow(n/2);
        return tmp * tmp;
    } else {
        return K * pow(n-1);
    }
}

int main(int argc, const char * argv[]) {
    int L;
    cin >> L;
    int N = 0;
    while (1) {
        if (L < pow(N++)) break;
    }
    cout << N << endl;
    int M = K * (N-2);
    for (int n = 1; n < N; ++n) {
        M += (L/pow(n-1) - L/pow(n)*K);
    }
    cout << M << endl;
    for (int i = 0; i < L%K; ++i) {
        cout << "1 " << N << " " << i << endl;
    }
    for (int n = 2; n < N; ++n) {
        for (int k = 0; k < K; ++k) {
            cout << n-1 << " " << n << " " << L/pow(n-2) - L/pow(n-1)*K + pow(n-2)*k << endl;
        }
        for (int i = 0; i < L/pow(n-1)-L/pow(n)*K; ++ i) {
            cout << n << " " << N << " " << i*pow(n-1) << endl;
        }
    }

    return 0;
}

