        node_num[0][1] = 3;
        in[3] = 1;
    } else {
        edges.insert(Edge(1, 2, 1));
        node_num[0][1] = 2;
    }

    for(int i = 1; i < d-1; i++) {
        if((l & (1 << i)) && !(l & ((1 << i) - 1))) {
            ++node;
            node_num[i][0] = node;
            edges.insert(Edge(node_num[i-1][0], node_num[i][0], 0));
            in[node] = 1;
            ++node;
            node_num[i][1] = node;
            edges.insert(Edge(node_num[i-1][0], node_num[i][1], 1 << i));
            in[node] = 1;
            continue;
