            if(!(l & (1 << i))) {
                ++node;
            }
            node_num[i][1] = node;
            edges.insert(Edge(node_num[i-1][0], node_num[i][1], 1 << i));
            in[node] = 1;
        // }

        // if(in[node_num[i-1][1]]) {
        if(node_num[i][1] == 0 || node_num[i][0] == node_num[i][1]) {
            ++node;
            node_num[i][1] = node;
        }
        if(l & (1 << i)) {
            edges.insert(Edge(node_num[i-1][1], node_num[i][0], 0));
            in[node_num[i][0]] = 1;
        } else {
            edges.insert(Edge(node_num[i-1][1], node_num[i][1], 0));
            in[node_num[i][1]] = 1;
        }

        edges.insert(Edge(node_num[i-1][1], node_num[i][1], 1 << i));
        in[node_num[i][1]] = 1;
        // }
    }

    ++node;
    edges.insert(Edge(node_num[d-2][0], node, 0));
    edges.insert(Edge(node_num[d-2][0], node, 1 << (d-1)));
    edges.insert(Edge(node_num[d-2][1], node, 0));

    cout << node << " " << edges.size() << endl;
    for(Edge e: edges) {
        cout << e.from << " " << e.to << " " << e.cost << endl;
    }

    return 0;
}

