    L--;

    int curr = 1;
    int N = getDig(L);

    while(L)
    {
        X.push_back({{curr, curr+1}, 0});

        if(L % 2 == 0)
            X.push_back({{curr, N}, L});

        X.push_back({{curr, curr+1}, (L+1)/2});
        L = (L-1)/2, curr++;
    }

    cout << N << " " << X.size() << "\n";

    for(auto x : X)
        cout << x.first.first << " " << x.first.second << " " << x.second << "\n";

