struct edge {
    int from, to, cost;
    edge(int f, int t, int c) : from(f), to(t), cost(c) {}
};

int main() {
    int l; cin >> l;
    int n = 1;
    while((1 << (n - 1)) <= l) n += 1;
    vector<edge> es;
    es.emplace_back(1, 3, 1 << (n - 3));
    es.emplace_back(1, 3, 0);
    for(int i = 3; i <= n - 1; ++i) {
        es.emplace_back(i, i + 1, 1 << (n - i - 1));
        es.emplace_back(i, i + 1, 0);
    }
    if(l ^ (l & -l)) { // l != 2^i
        es.emplace_back(1, 2, 1 << (n - 2));
        int cur = l - 1;
        for(int i = 3; i <= n - 1; ++i) {
            if((l - (1 << (n - 2))) & (1 << (n - i))) {
                const int t = (1 << (n - i)) - 1;
                es.emplace_back(2, i, cur - (1 << (n - 2)) - t);
                cur = (1 << (n - 2)) + es.back().cost - 1;
            }
        }
        if(es.back().cost != 0) {
            es.emplace_back(2, n, 0);
        }
    }

    cout << n << " " << es.size() << endl;
    for(const auto& e : es) {
        cout << e.from << " " << e.to << " " << e.cost << endl;
    }
    assert(n <= 20 && es.size() <= 60u);
}

