ll pw(ll x,ll a){
	ll ans = 1;
	while(a){
		while(a%2==0){
			a /= 2;
			x = (x*x);
		}
		ans = (ans*x);
		--a;
	}
	return ans;
}

int main(){
	int l,i,n=0;
	vector<int> a,b,c;
	cin >> l;
	while(pw(2,n)-1<=l){
		n++;
	}

	for(i=1;i<n;i++){
		a.push_back(i);
		b.push_back(i+1);
		c.push_back(pw(2,i-1));
	}

	for(i=1;i<n;i++){
		a.push_back(i);
		b.push_back(i+1);
		c.push_back(0);
	}

	ll x = pw(2,n-1);
	while(l-x>0){
		int k = 0;
		while(x+pw(2,k)-1<l){
			k++;
		}

		a.push_back(k);
		b.push_back(n);
		c.push_back(x);
		x += pw(2,k);
	}

