#define int long long

int bitCount(int num) {
	int res = 0;
	while(num > 0){
		num >>= 1;
		++res;
	}
	return res;
}

void check(vector<vector<pii> > &G, int node, int goal, int cost) {
	if (node == goal) {
		cout << cost << endl;
	}
	for (auto &to : G[node]) {
		check(G, to.first, goal, cost + to.second);
	}
}

void check(int N, int M, vector<tuple<int, int, int> >& res) {
	vector<vector<pii> > G(N+1);
	REP(i, M) {
		int from, to, cost;
		tie(from, to, cost) = res[i];
		G[from].emplace_back(to, cost);
	}
	check(G, 1, N, 0);
}

void solve() {
	int L; cin >> L;
	--L;
	int bit_width = bitCount(L);
	vector<vector<pii> > G(20);
	if (L != (1LL << (bit_width )) - 1LL) {
		bit_width--;
	}

	FOR(i, 1, bit_width+1) {
		G[i].emplace_back(0, i-1);
		G[i].emplace_back((1 << (i-1)), i-1);
	}
	int startNode = bit_width;

	int start = (1LL << bit_width) - 1;
	int rest = L - start;

	RREP(i, bit_width+1) {
		int cnt = (1LL << (i));
		if (rest >= cnt) {
			G[startNode].emplace_back(start+1, i);
			rest -= cnt;
			start += cnt;
		}
	}

	vector<int> enc(startNode+1);
	REP(i, enc.size()) {
		enc[i] = enc.size() - i;
	}


	vector<tuple<int, int, int> > res;
	RREP(i, G.size()) {
		for (auto &a : G[i]) {
			res.emplace_back(enc[i], enc[a.second], a.first);
		}
	}

	cout << enc.size() << " " << res.size() << endl;
	for (auto &r : res) {
		int a, b, c;
		tie(a, b, c) = r;
		cout << a << " " << b << " " << c << endl;
	}
}

