    int n = 0; while((1 << (n+1)) <= L) n++;
    std::queue<std::tuple<int, int, int>> Q;
    for(int x = 0; x + 1 <= n; ++x) Q.emplace(x, x+1, 0), Q.emplace(x, x+1, 1 << x);
