    for(int d = 0; d <= n; ++d) if((U >> d) & 1){ // 101
        Q.emplace(d, n, N + (1 << d));
    }

    printf("%d %lu\n", n+1, Q.size());
    while(not Q.empty()){
        int x, y, c; std::tie(x, y, c) = Q.front(); Q.pop();
        printf("%d %d %d\n", x + 1, y + 1, c);
    }
    return 0;
}

