ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
template<class T> T mod_inv(T a, T m) { T x, y; extgcd(a, m, x, y); return (m + x % m) % m; }

vector < vector<Pii>> solve(int l) {
	l--;

	int mbit = 1, cnt = 0;
	while (mbit <= l + 1) mbit *= 2, cnt++;
	mbit /= 2;

	vector<vector<Pii>> vp(cnt);
	{
		int c = mbit / 2;
		FOR(i, cnt - 1) {
			vp[i].emplace_back(i + 1, 0);
			vp[i].emplace_back(i + 1, c);
			c /= 2;
		}
	}

	int ll = l - mbit + 1;
	{
		int c = mbit / 2;
		FOR(i, cnt - 1) {
			int rem = c;
			if (ll >= rem) {
				ll -= rem;
				vp[0].emplace_back(i + 1, mbit + ll);
			}
			c /= 2;
		}
	}
	return vp;
}
void verify(vector < vector<Pii>>& vp, int l) {
	vector<set<int>> vs(sz(vp));
	vs[0].insert(0);

	FOR(i, sz(vp)) {
		for (auto p : vs[i]) {
			for (auto& x : vp[i]) {
				bool ok = vs[x.first].insert(p + x.second).second;
				if (!ok) {
					cout << "?";
				}
			}
		}
	}

	if (sz(vs.back()) != l) {
		cout << "?";
	}
}

void test() {
	for (int i = 2; i < 100; i++) {
		auto a = solve(i);
		verify(a, i);
	}
}

