const int N=1e6+5;
int L;
int cnt;
int id[N];
int a[N],b[N],c[N],z;
void add(int u,int v,int w){
    z++;
    a[z]=id[u];
    b[z]=id[v];
    c[z]=w;
}
void Build(int x){
    if(id[x]){
        return ;
    }
    if(x==0){
        id[x]=++cnt;
        z=1;a[1]=1,b[1]=2,c[1]=0;
        id[x]=++cnt;
        return ;
    }
    if(x&1){
        Build(x/2);
        if(!id[x])
            id[x]=++cnt;
        add(x/2,x,x/2+1);
        add(x/2,x,0);
    }
    else{
        Build(x/2-1);
        if(!id[x])
            id[x]=++cnt;
        add(x/2-1,x,x/2);
        add(x/2-1,x,0);
        add(0,x,x);
    }
}
