        a.push_back(deg);
        l -= 1 << deg;
        --deg;
//        watch(l);
    }
    deg = tmp;
    n = deg + 1;
    vector<pair<int, pii>> ans;
    for (int i = deg - 1, j = 1; i >= 0; --i, ++j) {
        ans.pb(mp(0, mp(j, j + 1)));
        ans.pb(mp(1 << i, mp(j, j + 1)));
    }
    if (a.size()) {
        ll sum = 0;
        a.pb(0);
        for (int i = 1; i < SZ(a); ++i){
            ll x = a[i - 1];
            ll y = a[i];
            sum += 1 << x;
            --y;
            int k = deg - y + 1;
            if (y < 0) k = n;
            ans.pb(mp(sum, mp(1, k)));
        }
    }
    cout << n << " " << ans.size() << "\n";
    for (auto x : ans) {
        cout << x.second.first << " "<< x.second.second << " " << x.first << "\n";
    }
}

