int f (int n) {
    int ret = 1;
    while ((n >>= 1) != 0) ret++;
    return ret; 
}
int popcount (int n) {
    int ret = n % 2;
    while ((n >>= 1) != 0) ret += n % 2;
    return ret;
}

int main (void)
{
