ll check_bitsize(ll x) {
	ll ret = 0;
	while (x > 0) {
		ret += 1;
		x /= 2;
	}
	return ret;
}

int main() {
	cin >> L;
	ll bitsize = check_bitsize(L);
	bitset<22> bs(L);
	N = bitsize;
	if (bs.count() == 1) {
		M = (N - 1) * 2;
		cout << N << " " << M << endl;;
		repi(i, 0, N - 1) {
			cout << N - i - 1 << " " << N - i << " " << 0 << endl;
			cout << N - i - 1 << " " << N - i << " " << pow_mod(2, i) << endl;
		}
	}
	else {
		M = (N - 1) * 2 + bs.count() - 1;
		cout << N << " " << M << endl;
		ll t = pow_mod(2, bitsize - 1);
		repi(i, 0, N - 1) {
			cout << N - i - 1 << " " << N - i << " " << 0 << endl;
			cout << N - i - 1 << " " << N - i << " " << pow_mod(2, i) << endl;
