vector<vector<P> > G(20);
Int n = 20;
const Int S = 0;
const Int T = 19;
const Int limit = 0;

void add_edge(int from,int to,int cost){G[from].push_back(P(to, cost));}

void add(Int L,Int sum = 0){
  if(L < 0) return;
  if( L <= limit ){
    for(int i=0;i<=L;i++) add_edge(S, T, sum + i);
    return;
  }

  vector<Int> num;
  {
    int x = limit+1, tmp = L - limit;
    while(tmp >= 0){
      num.push_back(x);
      tmp -= x;
      x *= 2;
    }
    if(tmp != 0) num.pop_back();
    while(T - (int)num.size() <= 0) num.pop_back();
  }
  int s = accumulate(num.begin(), num.end(), 0LL);
  add_edge(S, T - num.size(), sum);
  add(L - s - limit - 1, sum + s + limit + 1);
}

void check(Int L){
  vector<Int> S;
  function<void(Int,Int)> dfs = [&](Int pos,Int sum){
    if(pos == n-1) S.push_back(sum);
    for(auto e:G[pos]){
      Int to, cost; tie(to, cost) = e;
      dfs(to, sum + cost);
    }
  };
  Int M = 0;
  for(Int i=0;i<n;i++) M += G[i].size();
  assert(M <= 60);

  dfs(0, 0);
  assert((int)S.size() == L);
  sort(S.begin(), S.end());
  S.erase(unique(S.begin(), S.end()), S.end());
  assert((Int)S.size() == L);
}

void printG(){
  Int M = 0;
  for(Int i=0;i<n;i++) M += G[i].size();
  cout<<n<<" "<<M<<endl;
  for(Int i=0;i<n;i++){
    for(auto p:G[i]){
      Int to, cost; tie(to, cost) = p;
      cout<<i+1<<" "<<to+1<<" "<<cost<<endl;
    }
  }
}

void solve(int L){
  for(int i = 0 ;i<n;i++) G[i].clear();

  for(Int i=1;i<T;i++){
    add_edge(i, i+1, (1<<(n-i-2)));
    add_edge(i, i+1, 0);
  }
  add(L-1);
  printG();
  check(L);  
}

