const int MAXN=105;
int l;
int n,m;
struct edge
{
	int v,c;
	edge(){};
	edge(int vv,int cc)
	{
		v=vv,c=cc;
	}
};
vector<edge>w[MAXN];
int dfs(int now)
{
	if(now==0)
		return 1;
	int last=0;
	if((now&1)==0)
	{
		last=dfs(now/2-1);
		w[last].push_back(edge(last+1,0));
		m++;
		w[last].push_back(edge(last+1,now/2));
		m++;
		w[1].push_back(edge(last+1,now));
		m++;
	}
	else
	{
		last=dfs(now/2);
		w[last].push_back(edge(last+1,0));
		m++;
		w[last].push_back(edge(last+1,now/2+1));
		m++;
	}
	return last+1;
}
int main()
{
	scanf("%d",&l);
	l--;
	m=0;
	n=dfs(l);
	printf("%d %d\n",n,m);
	for(int i=1;i<=n;i++)
	{
		for(int j=0;j<int(w[i].size());j++)
		{
			printf("%d %d %d\n",i,w[i][j].v,w[i][j].c);
		}
	}
}

