  Edge(){}
  Edge(int _u, int _v, int _w):u{_u}, v{_v}, w{_w}{}
};

vector<Edge> adj;
vector<Edge> solve(int n, int e, int& l, int& r, int base){
//  cout << n << endl;
  vector<Edge> res;
  if(n <= base){
    l = e - 1, r = e;
    for(int i = 0;i < n;i++)
      res.push_back(Edge(l, r, i));
    return res;
  }
  if(n % base == 0){
    res = solve(n / base, e, l, r, base);
    l--;
    for(int i = 0;i < base;i++){
      res.push_back(Edge(l, l + 1, i * n / base));
    }
  }else{
    res = solve(n / base * base, r, l, r, base);
    for(int i = n / base * base;i < n;i++)
      res.push_back(Edge(l, r, i));
  }

  return res;

