void doubling(int a) {
	if (a == 2) return;
	if (a % 2) {
		tmp.push_back(--a);
		if (a != 2) {
			tmp.push_back(a / 2);
			F[a / 2] = 1;
			a /= 2;
			doubling(a);
		}
	}
	else {
		tmp.push_back(a / 2);
		F[a / 2] = 1;
		a /= 2;
		doubling(a);
	}
}


void kakeru() {
