struct Edge {
  size_t src, dst;
  int cost;
  Edge(size_t s, size_t d, int c): src(s), dst(d), cost(c) {}
};

int main() {
  size_t L;
  scanf("%zu", &L);

  size_t N=64-__builtin_clzll((unsigned long long)L);
  std::vector<Edge> es;

  size_t M=L-(1<<(N-1));

  for (size_t i=1; i+1<=N; ++i) {
    es.emplace_back(i, i+1, 0);
    es.emplace_back(i, i+1, 1<<(N-i-1));
  }

  int cost=1<<(N-1);
  for (size_t j=N-1, d=2; (j-- && M); ++d) {
    if (M >> j & 1) {
      es.emplace_back(1, d, cost);
      M ^= 1 << j;
      cost += 1 << j;
    }
  }

  printf("%zu %zu\n", N, es.size());
  for (const auto &e: es)
    printf("%zu %zu %d\n", e.src, e.dst, e.cost);
}

