    cin >> x;

    for (int i = 0; i < n - 1; i++) {
    	v.push_back({i, i + 1, 0});
    }

    vector<int> anime;

    while (x > 0) {
    	for (int i = 0; ; i++) {
    		if ((x >> i) & 1) {
    			anime.push_back(i);
    			x ^= (1 << i);
    			break;
    		}
