void solve(int n) {
	// build a fibonacci graph
	vector<pair<int, int>> ans;
	for (int i = 2; i <= 19; i++) {
		ans.emplace_back(i-1, i);
		if (i > 2) ans.emplace_back(i-2, i);
	}

	// connect certain nodes to sink
	for (int i = 19; i > 0; i--) {
		if (n >= fib[i]) {
			n -= fib[i];
			ans.emplace_back(i, 20);
		}
	}

