struct edge { int u, v, w; };

int main() {
    int L;
    scanf("%d", &L);
    function<pair<int, vector<edge>>(int)> solve = [&](int x) {
        if (!x) return make_pair(1, vector<edge>());
        if (x & 1) {
            auto p = solve(x - 1);
            p.second.push_back((edge){1, p.first, x - 1});
            return p;
        } else {
            auto p = solve(x >> 1); p.first++;
            for (auto &q : p.second) q.u++, q.v++, q.w <<= 1;
            p.second.push_back((edge){1, 2, 0});
            p.second.push_back((edge){1, 2, 1});
            return p;
        }
    };
    auto p = solve(L);
    printf("%d %d\n", p.first, p.second.size());
    for (auto q : p.second) printf("%d %d %d\n", q.u, q.v, q.w);
    return 0;
}

