namespace adaptor = boost::adaptors;
typedef std::vector<std::map<int, std::set<int>>> edge_t;

void run2(int L, int S, int shift, edge_t& edge)
{
	auto s = lib::intlog2(L);
	auto a = 1 << s;
	edge[S][s].emplace(shift);
	if (a != L)
	{
		run2(L - a, S, a + shift, edge);
	}
}

std::pair<int, edge_t> run(int L)
{
	auto S = lib::intlog2(L);
	edge_t edge(S + 1);
	for (int i : boost::irange(0, S))
	{
		edge[i + 1][i].emplace(0);
		edge[i + 1][i].emplace(1 << i);
	}
	auto A = 1 << S;
	if (L != A)
	{
		run2(L - A, S, A, edge);
	}
	return std::make_pair(S + 1, edge);
}

void Main()
{
	int L;
	std::cin >> L;
	auto p = run(L);
	DEFINE_STRUCT2(S, edge, p);
	std::vector<std::tuple<int, int, int>> vec;
	for (int i : boost::irange(0, S))
	{
		for (auto const& q : edge[i])
		{
			DEFINE_STRUCT2(j, es, q);
			for (auto const& v : es)
			{
				if (i != j)
				{
					vec.emplace_back(S - i, S - j, v);
				}
			}
		}
	}
	out::write_line(S, vec.size());
	out::write_range(vec);
}

