    using pll = pair<ll, ll>;
    vector<vector<pll>> G(N);

    rep(i, r) {
        G[i].push_back(MP(i + 1, 0));
        G[i].push_back(MP(i + 1, 1 << i));
        M += 2;
    }
    L -= (1 << r);
    ll cost = 1 << r;
    for(int i = r - 1; i >= 0; i--) {
        if(L >= (1 << i)) {
            L -= (1 << i);
            G[i].push_back(MP(N - 1, cost));
            cost += (1 << i);
            M++;
        }
    }
    cout << N << " " << M << endl;
    rep(i, N - 1) {
        for(pll p : G[i]) {
            cout << i + 1 << " " << p.first + 1 << " " << p.second << endl;
