    ans[m + 1][2] = now;
    m += 2;
    bf = now;
    now *= 2;
  }
  if(now == l)
    nowl = 0;
  else
    nowl = l - now;
  nown = n - 1;
  while(nowl) {
    if(nowl >= bf) {
      ans[m][0] = nown;
      ans[m][1] = n;
      if(nown == 1)
        ans[m][2] = l - 1;
      else
        ans[m][2] = now;
      now += mypow(2, nown - 1);
      ++m;
      nowl -= bf;
    }
    bf /= 2;
    --nown;
  }
  cout << n << " " << m << endl;
  for(i = 0; i < m; ++i)
    cout << ans[i][0] << " " << ans[i][1] << " "
         << ans[i][2] << endl;
  return 0;
}

