void build(int n, int L)
{
	if(n==1) return;
	if(L==1)
	{
		edge.push_back(make_pair(0,make_pair(n-1,n)));
		build(n-1,L);
	}
	else if(L%2==0)
	{
		edge.push_back(make_pair(0,make_pair(n-1,n)));
		edge.push_back(make_pair(L/2,make_pair(n-1,n)));
		build(n-1,L/2);
	}
	else if(L%2==1)
	{
		edge.push_back(make_pair(0,make_pair(n-1,n)));
		edge.push_back(make_pair(L/2,make_pair(n-1,n)));
		edge.push_back(make_pair(L-1,make_pair(1,n)));
		build(n-1,L/2);
	}

}
