#define LOGA2(arr, N, M, sep) { cerr << #arr << " =\n"; for (int i = 0; i < N; ++i) { for (int j = 0; j < M; ++j) cerr << (arr)[i][j] << " "; cerr << endl; } cerr << (sep); }

ostream& operator<<(ostream& os, const ii& p)
{
    os << "(" << p.first << ", " << p.second << ")";
    return os;
}

ostream& operator<<(ostream& os, const iii& p)
{
    os << "(" << p.first << ", " << p.second << ")";
    return os;
}

const int MAX { 2000010 };
const ll oo { 1LL << 62 };
const int MOD { 1000000007 };

int number_of_vertices(int L)
{
    auto ans = 0;

    for (auto i = 0; i <= 20; ++i)
        if (L & (1 << i))
            ans = i + 1;

    return ans + 1;
}

void solve(int L)
{
    auto N = number_of_vertices(L - 1);
    vector<iii> es;

    auto base = 1;
//LOG(N, '\n');
    REP(u, 2, N - 1)
    {
        es.push_back(iii(ii(u - 1, u), 0));
        es.push_back(iii(ii(u - 1, u), base));
        base <<= 1;
    }

    es.push_back(iii(ii(N - 1, N), 0));

    int v = N, vbase = base, w = 0;

    while (v > 1)
    {
        w |= vbase;

        auto u = v - 1;
        auto base = vbase >> 1;

        while (base)
        {
            if ((L - 1) & (1 << (u - 2)))
                break;

            --u;
            base >>= 1;
        }

//LOG(v, ' '); LOG(u, ' '); LOG(w, '\n');
        es.push_back(iii(ii(max(u - 1, 1), N), w));
        v = u;
        vbase = base;
    } 

    cout << N << " " << es.size() << endl;

    for (const auto& e : es)
        cout << e.first.first << " " << e.first.second << " " << e.second << endl;
}

int main()
{
    ios::sync_with_stdio(false);

    int L;
    cin >> L;

    solve(L);

    return 0;
}

