struct Edge {
    int from,to,cost;
    Edge(int f, int t, int c): from(f), to(t), cost(c) {};

    bool operator<(const Edge& e) const {
        if(from != e.from) {
            return from < e.from;
        }
        if(to != e.to) {
            return to < e.to;
        }
        return cost < e.cost;
    }
};

int main() {
