    cin >> l;

    if(l == 2) {
        cout << "2 2\n1 2 0\n1 2 1\n";
        return 0;
    }

    // 2べき部分と残りの部分に分ける
    int node = 0;
    while((1 << node) <= l) node++;

    int edge_cnt = 1 << (node-1);
    for(int i = 1; i <= node-1; i++) {
        edges.push_back(Edge(i, i+1, 0));
        edges.push_back(Edge(i, i+1, 1 << (i-1)));
    }

    for(int i = node-2; i>= 0; i--) {
        if(l - edge_cnt >= (1 << i)) {
            edges.push_back(Edge(i+1, node, edge_cnt));
            edge_cnt += (1 << i);
        }
    }

    cout << node << " " << edges.size() << endl;
    for(Edge e: edges) {
        cout << e.from << " " << e.to << " " << e.cost << endl;
