int bitlen(int n) {
  int cnt = 0;
  while (n > 0) {
    ++cnt;
    n /= 2;
  }
  return cnt;
}

int main() {
  int l;
  cin >> l;

  int n = bitlen(l);
  vector<tuple<int, int, int>> edges;
  for (int i = n - 2, j = 0; i >= 0; --i, ++j) {
    edges.emplace_back(i, i + 1, 0);
    edges.emplace_back(i, i + 1, 1 << j);
  }
  for (int i = 0; i < n - 1; ++i) {
    if (l & (1 << i)) {
      edges.emplace_back(0, n - i - 1, (l >> (i + 1)) << (i + 1));
    }
  }

  cout << n << ' ' << edges.size() << '\n';
  for (auto& edge: edges) {
    int from, to, len;
    tie(from, to, len) = edge;
