                v[i].second *= 2;
            }
            v.push_back(make_pair(make_pair(curr - 1, curr), 0));
            v.push_back(make_pair(make_pair(curr - 1, curr), 1));
            v.push_back(make_pair(make_pair(0, curr), val));
