typedef pair<ll, ll> pll;


ll L;
ll maxpw;
vector< pair<pll ,ll> > ans;
ll dp[40];
ll gt(ll x, ll i)
{
        ll yo = (1LL << i) - 1;
        return (x^yo);
}
int main()
{
        cin >> L;
        L--;
        memset(dp, -1,sizeof dp);
        for(ll i=0;i<=20;i++) {
                if(L&(1LL << i)) {
                        maxpw = i;
                }
        }
        ll totN = maxpw + 1;
        ll pw = 1LL;
        ll pp=0;
        dp[pp] = totN;
        ll lstnode = totN;
        for(ll i=totN-1; i>=1;i--) {

                if(pp >= maxpw) {
                        break;
                }
                ans.pb(make_pair(make_pair(i, lstnode), 0));
                ans.pb(make_pair(make_pair(i, lstnode), pw));
                pw *= 2LL;
                pp++;
                dp[pp] = i;
                lstnode = i;
        }
        //ans.pb(make_pair(make_pair(lstnode-1, lstnode) , 0));
        for(ll i=maxpw-1;i>=1;i--) {
                if(L&(1LL << i)) {
                        ans.pb(make_pair(make_pair(lstnode, dp[i]), gt(L, i)));
                }
        }
        if(L%2 == 1) {
                ans.pb(make_pair(make_pair(lstnode, dp[0]), L-1));
        }
        ans.pb(make_pair(make_pair(lstnode, dp[0]), L));
        sort(ans.begin(), ans.end());
        ll sz = unique(ans.begin(), ans.end()) - ans.begin();
        ans.resize(sz);
        cout << totN << " " << ans.size() << endl;
        //return 0;
        //for(pair<pll, ll> &i : ans) cout << i.first.first << " " << i.first.second << " " << i.second << endl;
        for(ll i=0;i<ans.size();i++) {
            cout << ans[i].first.first << " " << ans[i].first.second << " " << ans[i].second << "\n";
        }
        return 0;
}

