void solve()
{
    int L;
    scanf("%d", &L);
    int curr = 0;
    int val = 1;
    int i;

    vector<int> a;
    while (L) {
        a.push_back(L % 2);
        L /= 2;
    }

    a.pop_back();
    vector<pair<pair<int, int>, int> > v;
    while (!a.empty()) {
        int tmp = a.back();
        a.pop_back();
        curr++;
        val *= 2;
        if (tmp == 0) {
            int siz = v.size();
            for (i = 0; i < siz; i++) {
                v[i].second *= 2;
            }
            v.push_back(make_pair(make_pair(curr - 1, curr), 0));
            v.push_back(make_pair(make_pair(curr - 1, curr), 1));
        }
        else {
            int siz = v.size();
            for (i = 0; i < siz; i++) {
                v[i].second *= 2;
            }
            v.push_back(make_pair(make_pair(curr - 1, curr), 0));
            v.push_back(make_pair(make_pair(curr - 1, curr), 1));
            v.push_back(make_pair(make_pair(0, curr), val));
        }
    }

    int m = (int)v.size();
    int n = curr+1;
    printf("%d %d\n", n, m);
    for (i = 0; i < m; i++) {
        printf("%d %d %d\n", v[i].first.first + 1, v[i].first.second + 1, v[i].second);
    }

    return;
}


