            string tmp = to_string(node) + " " + to_string(node+1) + " " + to_string(fact[i]);
            ans.push_back(tmp);
            node++;
        }
        L -= fact[loop] - 1;
    }
    for(int i = 1; i < node; ++i) {
        string tmp = to_string(i) + " " + to_string(node) + " 0";
        ans.push_back(tmp);
    }
    printf("%lld %lld\n", node, (node-1)*2);
    REP(i, ans.size()) {
        printf("%s\n", ans[i].c_str());
    }

    return 0;
}

