vector<pair<PII, int>> go2(int L)
{
	if (L == 1)
		return{ MP(MP(1,2),0) };

	if (L % 2)
	{
		auto list = go2(L - L % 2);
		int last = list.back().first.second;
		list.push_back(MP(MP(1, last + 1), L - 1));
		list.push_back(MP(MP(last, last + 1), 0));

		return list;
	}

	auto list = go2(L / 2);
	int last = list.back().first.second;
	list.push_back(MP(MP(last, last + 1), 0));
	list.push_back(MP(MP(last, last + 1), L / 2));

	return list;
}

vector<pair<PII, int>> go3(int L)
{
	if (L == 1)
		return{ MP(MP(1,2),0) };
	if (L == 2)
		return{ MP(MP(1,2),0),MP(MP(1,2),1) };

	if (L % 3)
	{
		auto list = go3(L - L % 3);
		int last = list.back().first.second;
		list.push_back(MP(MP(1, last + 1), L - 1));
		if (L % 3 > 1)
			list.push_back(MP(MP(1, last + 1), L - 2));
		list.push_back(MP(MP(last, last + 1), 0));

		return list;
	}

	auto list = go3(L / 3);
	int last = list.back().first.second;
	list.push_back(MP(MP(last, last + 1), 0));
	list.push_back(MP(MP(last, last + 1), L / 3));
	list.push_back(MP(MP(last, last + 1), 2 * L / 3));

	return list;
}

vector<pair<PII, int>> go4(int L)
{
	if (L == 1)
		return{ MP(MP(1,2),0) };
	if (L == 2)
		return{ MP(MP(1,2),0),MP(MP(1,2),1) };
	if (L == 3)
		return{ MP(MP(1,2),0),MP(MP(1,2),1),MP(MP(1,2),2) };

	if (L % 4)
	{
		auto list = go4(L - L % 4);
		int last = list.back().first.second;
		list.push_back(MP(MP(1, last + 1), L - 1));
		if (L % 4 > 1)
			list.push_back(MP(MP(1, last + 1), L - 2));
		if (L % 4 > 2)
			list.push_back(MP(MP(1, last + 1), L - 3));
		list.push_back(MP(MP(last, last + 1), 0));

		return list;
	}

	auto list = go4(L / 4);
	int last = list.back().first.second;
	list.push_back(MP(MP(last, last + 1), 0));
	list.push_back(MP(MP(last, last + 1), L / 4));
	list.push_back(MP(MP(last, last + 1), 2 * L / 4));
	list.push_back(MP(MP(last, last + 1), 3 * L / 4));

	return list;
}

vector<pair<PII, int>> go5(int L)
{
	if (L == 1)
		return{ MP(MP(1,2),0) };
	if (L == 2)
		return{ MP(MP(1,2),0),MP(MP(1,2),1) };
	if (L == 3)
		return{ MP(MP(1,2),0),MP(MP(1,2),1),MP(MP(1,2),2) };
	if (L == 4)
		return{ MP(MP(1,2),0),MP(MP(1,2),1),MP(MP(1,2),2),MP(MP(1,2),3) };

	if (L % 5)
	{
		auto list = go5(L - L % 5);
		int last = list.back().first.second;
		list.push_back(MP(MP(1, last + 1), L - 1));
		if (L % 5 > 1)
			list.push_back(MP(MP(1, last + 1), L - 2));
		if (L % 5 > 2)
			list.push_back(MP(MP(1, last + 1), L - 3));
		if (L % 5 > 3)
			list.push_back(MP(MP(1, last + 1), L - 4));
		list.push_back(MP(MP(last, last + 1), 0));

		return list;
	}

	auto list = go5(L / 5);
	int last = list.back().first.second;
	list.push_back(MP(MP(last, last + 1), 0));
	list.push_back(MP(MP(last, last + 1), L / 5));
	list.push_back(MP(MP(last, last + 1), 2 * L / 5));
	list.push_back(MP(MP(last, last + 1), 3 * L / 5));
	list.push_back(MP(MP(last, last + 1), 4 * L / 5));

	return list;
}

vector<pair<PII, int>> go(int L)
{
	auto res = go2(L);
	if (res.back().first.second < 21 && res.size() < 61)
		return res;

	res = go3(L);
	if (res.back().first.second < 21 && res.size() < 61)
		return res;

	res = go4(L);
	if (res.back().first.second < 21 && res.size() < 61)
		return res;

	return go5(L);
}

