          tuple<int,int,int> buf2={i,i+1,rem};
          memo[buf]+=1;
          memo[buf2]+=1;
          n=i+1;
          break;
      }
      else{
          tuple<int,int,int> buf={i,i+1,bit};
          tuple<int,int,int> buf2={i,i+1,0};
          memo[buf]+=1;
          memo[buf2]+=1;
      }
  }
  if(rem==0){
      goto FINE;
  }

  for(int i=n-2;i>=0;--i){
      int sum=node[i].edge[0].second-1;
      if(rem>sum){
          node[i].edge.push_back({n,rem-sum-1});
          tuple<int,int,int> buf={i,n,rem-sum-1};
          memo[buf]+=1;
          ++m;
          rem-=sum;
          if(rem==1){
              break;
          }
      }
      while(i==0&&rem>0){
          if(memo.find({i,n,rem-1})!=memo.end()){
              rem-=1;
              continue;
          }
          node[i].edge.push_back({n,rem-1});
          rem-=1;
          ++m;
      }
  }
  FINE:
  cout<<n<<" "<<m<<endl;
  rep(i,n){
      for(const auto& val:node[i].edge){
          printf("%lld %lld %lld\n",i+1,val.first+1,val.second);
      }
  }
  return 0;
}

