};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int L;
    cin >> L;
    vector<int> v;
    while (L > 0) {
        v.push_back(L % 2);
        L /= 2;
    }
    vector<data> ans;
    int N = v.size();
    for (int from = 1, to = 2, weight = 1; to <= N; from++, to++, weight *= 2) {
        ans.push_back({from, to, 0});
        ans.push_back({from, to, weight});
    }
    int ever = 1 << (N - 1);

    for (int i = (int) v.size() - 2; i >= 0; --i) {
        if (v[i] == 0) continue;
        ans.push_back({i + 1, N, ever});
        ever += 1 << i;
    }
    cout << N << " " << ans.size() << endl;
    for (auto a : ans) {
        cout << a.d1 << " " << a.d2 << " " << a.d3 << endl;
    }

    return 0;
}

