const int r = 4;

int main()
{
  int L;
  cin >> L;
  L--;
  vector<int> p;
  while(L)
  {
    p.push_back(L%r);
    L /= r;
  }
  reverse(p.begin(), p.end());
  //for(auto x : p) cout << x; cout << endl;
  int n = p.size();

  vector<vector<int>> edge(0, vector<int>(3));
  rep(i,n)
  {
    int v = i*2+1;
    int base = 1;
    rep(j,n-i-1) base *= r;

    if(n == 1)
    {
      rep(j,p[i]+1) edge.push_back({v, v+1, j});
      break;
    }

    if(i == 0)
    {
      rep(j,p[i]) edge.push_back({v, v+1, j*base});
      edge.push_back({v, v+2, p[i]*base});
    }
    else if(i == n-1)
    {
      edge.push_back({v-1, v, 0});
      rep(j,r)
      {
        if(j <= p[i]) edge.push_back({v, v+1, j});
        else edge.push_back({v-1, v+1, j});
      }
    }
    else
    {
      if(p[i] > 0) edge.push_back({v-1, v, 0});
      rep(j,r)
      {
        if(j < p[i]) edge.push_back({v, v+1, j*base});
