	int n, hb = 0;
	for (n = 0; (1 << n) <= l; n++);
	for (int i = 1, k = 1 << (n - 1), kk; i < n; k = kk, i++) {
		kk = k >> 1;
		edge.push_back(MP(MP(i, i + 1), kk));
		edge.push_back(MP(MP(i, i + 1), 0));
