			if (i > 1) {
				edge.push_back(MP(MP(1, i), hb));
			}
			hb += k;
		}
	}
	if (hb < l) {
		edge.push_back(MP(MP(1, n), l - 1));
	}
	printf("%d %d\n", n, (int)edge.size());
	for (int i = 0; i < edge.size(); i++) {
		printf("%d %d %d\n", edge[i].first.first,
			edge[i].first.second, edge[i].second);
	}
	return 0;
}

