template <class T>
void printArray(const vector<T>& a) {
  int n = a.size();
  for (int i = 0; i < n; i++) {
    cout << a[i] << " \n"[i == n - 1];
  }
}

void pr(ll u, ll v, ll w) { e.push_back({u, v, w}); }

struct Edge {
  ll dst, wgt;
  Edge(ll dst, ll wgt) : dst(dst), wgt(wgt){};
};

vector<bool> seen;
vector<ll> paths;
vector<vector<Edge>> g;
ll sum = 0;
ll goal = 0;
ll l;

void dfs(ll cv) {
  if (cv == goal) {
    paths.push_back(sum);
    return;
  }

  seen[cv] = true;
  for (Edge e : g[cv]) {
    ll nv = e.dst, w = e.wgt;
    if (seen[nv]) {
      continue;
    }
    sum += w;
    dfs(nv);
    sum -= w;
  }
  seen[cv] = false;
}

bool check() {
  ll n = 20;
  ll m = SZ(e);
  g = vector<vector<Edge>>(n);
  seen = vector<bool>(n, false);
  paths.clear();
  goal = 0;
  REP(i, m) {
    ll u = e[i][0], v = e[i][1], w = e[i][2];
    u--, v--;
    g[u].push_back(Edge(v, w));
    goal = max(goal, max(u, v));
  }
  dfs(0);

  if (SZ(paths) != l) {
    return false;
  }
  sort(ALL(paths));
  REP(i, l - 1) {
    if (paths[i] + 1 != paths[i + 1]) {
      return false;
    }
  }
  return true;
}

void solve() {
  e.clear();
  ll k = -1, c = 1;
  while (c <= l) {
    c *= 2;
    k++;
  }

  FOR(i, 1, k + 1) {
    pr(i, i + 1, 0);
    pr(i, i + 1, 1LL << (i - 1));
  }

  ll l2 = l;
  IFOR(i, 1, k + 1) {
    if (l2 - (1LL << (i - 1)) >= (1LL << k)) {
      pr(i, k + 1, l2 - (1LL << (i - 1)));
      l2 -= 1LL << (i - 1);
    }
  }

  // debug
  // cout << (check() ? "OK" : "NG") << "\n";

  cout << k + 1 << " " << SZ(e) << "\n";
  REP(i, SZ(e)) { printArray(e[i]); }
}

int main() {
  cin >> l;
  solve();
}

