int main() {
    int n;
    int ver = 0, edg = 0;
    std::cin >> n;
    std::vector<int> pow(21);
    pow[0] = 1;
    for (int i = 1; i < 21; i++) pow[i] = pow[i - 1] * 2;
    int d = 1, cnt = std::bitset<20>(n).count();
    while (n >> (d + 1) > 0) d++;
    std::cout << d + 1 << " " << 2 * d + cnt - 1 << "\n";
    std::vector<std::deque<int>> g(d + 1), c(d + 1);
    for (int i = 0; i < d; i++) {
        int cost = pow[d - 1 - i];
        g[i].push_back(i + 1);
        c[i].push_back(0);
        g[i].push_back(i + 1);
        c[i].push_back(cost);
    }
    int cc = 1 << d;
    n -= cc;

    while (n) {
        while (n >> (d - 1) == 0) d--;
        g[0].push_back(g.size() - d);
        c[0].push_back(cc);
        cc += pow[d - 1];
        n -= pow[d - 1];
    }

    for (int i = 0; i < g.size(); i++) {
        while (!g[i].empty()) {
            std::cout << i + 1 << " " << g[i].front() + 1 << " " << c[i].front() << "\n";
            g[i].pop_front();
            c[i].pop_front();
        }
    }
    std::cout << std::flush;

    return 0;
}

