int construct(int l, vector<eg> &es) {
  if(l == 1) {
    return 1;
  }
  if(l % 2 == 0) {
    int sz = construct(l / 2, es);
    es.push_back({sz, sz + 1, 0});
    es.push_back({sz, sz + 1, l / 2});
    return sz + 1;
  }
  int sz = construct(l - 1, es);
  es.push_back({sz, sz + 1, 1});
  es.push_back({1, sz + 1, 0});
  return sz + 1;
}

