vector<pair<PII, int>> go(int L, int k)
{
	if (L < k)
	{
		vector<pair<PII, int>> res;
		REP(i, L)
			res.push_back(MP(MP(1, 2), i));

		return res;
	}

	int md = L%k;
	if (md)
	{
		auto list = go(L - md, k);
		int last = list.back().first.second;

		REP(i, md)
			list.push_back(MP(MP(1, last), L - i - 1));

		return list;
	}

	auto list = go(L / k, k);
	int last = list.back().first.second;
	list.push_back(MP(MP(last, last + 1), 0));
	REP(i, k - 1)
		list.push_back(MP(MP(last, last + 1), (i + 1)*L / k));

	return list;
}

vector<pair<PII, int>> go(int L)
{
	FORQ(k, 2, 65)
	{
		auto res = go(L, k);
		if (res.back().first.second < 21 && res.size() < 61)
			return res;
	}

	FOR(sub, 1, 60)FORQ(k, 2, 65)
	{
		auto res = go(L - sub, k);
		int last = res.back().first.second;
		if (last < 20 && res.size() < 60 - sub)
		{
			res.push_back(MP(MP(last, last + 1), 0));
			REP(i, sub)
				res.push_back(MP(MP(last, last + 1), L - i - 1));
			return res;
		}
	}

	return{};
}

