void construct(int l, vector<vtx> &vs, vector<eg> &es) {
  if(l == 1) {
    vs.push_back({1});
    return;
  }
  if(l % 2 == 0) {
    construct(l / 2, vs, es);
    vtx &last = vs.back();
    vs.push_back({last.id + 1});
    es.push_back({last.id, last.id + 1, 0});
    es.push_back({last.id, last.id + 1, l / 2});
    return;
  }
  construct(l - 1, vs, es);
  vtx &last = vs.back();
  vs.push_back({last.id + 1});
  es.push_back({last.id, last.id + 1, 1});
  es.push_back({1, last.id + 1, 0});
}

