struct Edge {
	int a, b, w;
	Edge () {};
	Edge (int a, int b, int w) : a(a), b(b), w(w) {};
};

int n;

vector<Edge> ans;

void solve() {
	n = 20;

	vi vb;
	int x = L;
	while (x) {
		vb.pb((x & 1));
		x >>= 1;
	}

	fi(2, 19) {
		ans.pb(Edge(i, i + 1, 0));
		ans.pb(Edge(i, i + 1, (1 << (n - i) )));
	}

	int sum = 0;
	fdi(sz(vb) - 1, 0) {
		if (!vb[i]) continue;
		if (i == 0) {
			ans.pb(Edge(1, n, sum));
		} else {
			int k = n - (i - 1);
			ans.pb(Edge(1, k, sum));
			ans.pb(Edge(1, k, sum + 1));
		}
		sum += (1 << i);
	}

	printf("%d %d\n", n, sz(ans));
	for (auto z : ans) {
		printf("%d %d %d\n", z.a, z.b, z.w);
	}
}

