vector<iii> E;

void dfs(multiset<int>& s, int v, int n, int cost) {
    if (v == n) {
        s.insert(cost);
        return;
    }
    for (iii e : E) {
        int a, b, w;
        tie(a, b, w) = e;
        if (a == v) {
            dfs(s, b, n, cost + w);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    int L;
    cin >> L;
    --L;
    int n = 1;
    while ((1 << n) <= L) ++n;
    ++n;
    for (int v = n-1; v >= 1; --v) E.pb(iii(v, v+1, 0));
    for (int v = n-1; v >= 2; --v) E.pb(iii(v, v+1, 1<<(n-1-v)));
    for (int i = 0; (1<<i) <= L; ++i) {
        int bit = 1 << i;
        if (!(L & bit)) continue;
        int j = 0;
        for (; j < i && !(1<<j & L); ++j);
        if (j == i) {
            E.pb(iii(1, n, L));
            continue;
        }
        int val = L & ~(bit - 1);
        E.pb(iii(1, n-j, val));
    }
    sort(all(E));

    /*
    multiset<int> s;
    dfs(s, 1, n, 0);
    for (int x : s) cout << "path: " << x << '\n';
    */
    cout << n << ' ' << E.size() << '\n';
    for (iii e : E)
        cout << get<0>(e) << ' ' << get<1>(e) << ' ' << get<2>(e) << '\n';
}

