    public: 
    vector<edge<T>> edges;
    vector<vector<int>> adj;
    int n;
    graph(){};
    graph(int _n){
        n = _n;
        adj.resize(n);
    }
};

template<typename T>
class undigraph : public graph<T>{
    public:
        using graph<T>::edges;
        using graph<T>::adj;
        using graph<T>::n;
        undigraph() : graph<T>(){};
        undigraph(int _n) : graph<T>(_n){};

        int add_edge(int src, int dest, T cost = 1){
            int id = edges.size();
            edges.push_back({src, dest, cost});
            adj[src].push_back(id);
            adj[dest].push_back(id);
            return id;
        }
};
struct AcAutomaton{
    int l;
    undigraph<int> g;
	void read_in(){
		cin >> l;
        g = undigraph<int>(20);
	}
	void solve(){
		int lpow = 0;
        REP(i, 32){
            if(l&(1 << i)) ckmax(lpow, i);
        }
        REP(i, lpow){
            g.add_edge(i, i+1, (1<<i));
            g.add_edge(i, i+1, 0);
        }
        //for(auto e : g.edges) cout << e.src << " " << e.dest << " " << e.cost << endl;
        int sum = (1 << lpow);
        REPD(i, lpow-1){
            if(l&(1 << i)){
                g.add_edge(i, lpow, sum);
                sum += (1 << i);
            }
        }
        cout << ++lpow << " " << g.edges.size() << endl;
        for(auto e : g.edges) cout << e.src+1 << " " << e.dest+1 << " " << e.cost << endl;
	}
};

int main(){
 	ios_base::sync_with_stdio(false);
 	cin.tie(NULL); cout.tie(NULL);
	int tcase = 1;
	while(tcase--){
		AcAutomaton solver;
		solver.read_in();
		solver.solve();
	}
    return 0;
}

