int main(){
	cin.tie(0)->sync_with_stdio(0);
	int L;
	cin >> L;
	int n, m = 0;
	vector<vector<pair<int, int>>> adj;
	function<void(int)> solve = [&](int x){
		if(x <= 1){
			adj.emplace_back();
			return;
		}
		solve(x / 2);
		int c = int(adj.size());
		adj.emplace_back();
		adj[c - 1].emplace_back(c, 0);
		adj[c - 1].emplace_back(c, x / 2);
		m += 2;
		if(x & 1){
			adj[0].emplace_back(c, x - 1);
			++ m;
		}
	};
	solve(L);
	n = int(adj.size());
	cout << n << " " << m << "\n";
	for(int u = 0; u < n; ++ u){
		for(int i = 0; i < int(adj[u].size()); ++ i){
			int v, w;
			tie(v, w) = adj[u][i];
			cout << u + 1 << " " << v + 1 << " " << w << "\n";
		}
	}
	return 0;
}

