// mod. m での a の逆元 a^{-1} を計算する
ll modinv(long long a, long long m) {
  long long b = m, u = 1, v = 0;
  while (b) {
    long long t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  u %= m;
  if (u < 0) u += m;
  return u;
}



map<ll, ll> prime_factors(ll n) {
  map<ll, ll> res;
  if (n == 1) { // n=1 の素因数分解は n^1
    res[n] = 1;
    return res;
  }
  for (ll i = 2, _n = n; i * i <= _n; ++i) {
    while (n % i == 0) {
      ++res[i]; // 素数i^{res[i]}
      n /= i;
    }
  }
  if (n != 1) res[n] = 1;
  return res;
}



