void add(int L,int sum = 0){
  vector<Int> num;
  Int flag = true;
  int cnt = 0;
  int s = 0;
  {
    Int tmp = L;
    Int x = 1;
    while(tmp){
      flag = false;
      if(tmp == x) flag = true;
      num.push_back(min(tmp, x));
      tmp -= min(tmp, x);
      s += num.back();
      cnt++;
      x *= 2;
    }     
  }
  if(flag == false)  s -= num.back();
  if(flag == true) cnt++;
  G[S].push_back(P(n-cnt, sum));
  if(flag == false) add(num.back(), sum + s);
}

