	void adjust()
	{
		std::vector<edge> tmp;
		for (int i=0;i<g.size();i++) if (g[i].x&&g[i].y) tmp.push_back(g[i]);
		g.clear();
		for (int i=0;i<tmp.size();i++) g.push_back(tmp[i]);
		q=g.size();
	}
