        que1.push(push1);
        que2.push(push2);
        que3.push(push3);
    };

    bool first_make = true;
    int last;
    auto make_path = [&](int N, bool div2) {//N未満
        int cnt = 0;
        while (N % 3 == 0) {
            N /= 3;
            cnt++;
        }
        if (first_make) {

            last = cnt + 1;
            int from = 1;
            int to = 2;
            if (div2) {
                last++;
                to++;
            }
            ll edge = (ll) pow(3, cnt - 1);

