std::vector<std::tuple<int, int, int>> edges;

int main()
{
    int m = 1000000;
    scanf("%d", &m);
    int n = 0;
    std::vector<int> ways { 1 };
    while (ways.back() * 3 <= m) {
        edges.emplace_back(n, n + 1, 0);
        edges.emplace_back(n, n + 1, ways.back());
        edges.emplace_back(n, n + 1, ways.back() * 2);
        n ++;
        ways.push_back(ways.back() * 3);
    }
    int cur = 0;
    for (int i = n; i >= 0; -- i) {
        if (cur + ways[i] <= m) {
            edges.emplace_back(i, n + 1, cur);
            cur += ways[i];
        }
        if (cur + ways[i] <= m) {
            edges.emplace_back(i, n + 1, cur);
            cur += ways[i];
        }
    }
    std::vector<int> dp(n + 2, 0);
    dp[0] = 1;
    for (int i = 1; i < n + 2; ++ i) {
        for (auto&& e : edges) {
            if (std::get<1>(e) == i) {
                dp[i] += dp[std::get<0>(e)];
            }
        }
    }
    // printf("ways = %d\n", dp[n + 1]);
    assert(dp[n + 1] == m);
    printf("%d %d\n", n + 2, static_cast<int>(edges.size()));
    for (auto&& e : edges) {
        printf("%d %d %d\n", std::get<0>(e) + 1, std::get<1>(e) + 1, std::get<2>(e));
    }
}

