int main() {
  int L;
  while (cin >> L) {
    const int N = 20;
    vec<E, 2> G(N);
    int p = 0, geta = 0;
    for (int i = 0; i < 30; i++) {
      if ((L >> i) & 1) {
        int add = geta;
        while (p < i) {
          G[p].push_back(E(p + 1, add + 0));
          G[p].push_back(E(p + 1, add + (1 << p)));
          add = 0;
          ++p;
        }
        if (p != N - 1) {
          G[p].push_back(E(N - 1, 0));
        }
        geta = 1 << i;
      }
    }
    int M = 0;
    for (int i = 0; i < N; i++) M += G[i].size();
