			res.push_back(MP(MP(1, 2), i));

		return res;
	}

	int md = L%k;
	if (md)
	{
		auto list = go(L - md, k);
		int last = list.back().first.second;

		REP(i, md)
			list.push_back(MP(MP(1, last), L - i - 1));

		return list;
	}

	auto list = go(L / k, k);
	int last = list.back().first.second;
	list.push_back(MP(MP(last, last + 1), 0));
	REP(i, k - 1)
		list.push_back(MP(MP(last, last + 1), (i + 1)*L / k));

	return list;
}

vector<pair<PII, int>> go(int L)
{
	FORQ(k, 2, 65)
	{
		auto res = go(L, k);
		if (res.back().first.second < 21 && res.size() < 61)
			return res;
	}

	return{};
}

int main()
{
	int L;
	scanf("%d", &L);

	auto list = go(L);

	printf("%d %d\n", list.back().first.second, list.size());
	for (const auto& p : list)
		printf("%d %d %d\n", p.first.first, p.first.second, p.second);

	return 0;
}

