template <int N>
class Pow {
  private:
    vector<ll> table;
  public:
    Pow(int size) : table(size + 1){
        table[0] = 1;
        for (int i = 1; i <= size; ++i){
            table[i] = table[i - 1] * N;
        }
    }
    ll operator () (int i){return table[i];}
};

int main()
{
