    vector<tuple<int, int, int>> edges; edges.reserve(60);
    REP(i, N - 1){
        edges.emplace_back(i + 1, i + 2, 0);
        edges.emplace_back(i + 1, i + 2, pow2(i));
    }
    int used = pow2(N - 1);
    RREP(i, N - 1){
        if (L < used + pow2(i)) continue;
        edges.emplace_back(i + 1, N, used);
        used += pow2(i);
    }
