int bpm(int x, unsigned int y) {
  if (x == 0) return 0;
  if (y == 0) return 1;
  int ans   = 1;
  int digit = (int)((log((double)y) / log((double)2) / 1 + 1));
  x %= MOD;
  for (int i = 0; i < digit; i++) {
    if (((y >> i) & 1u) == 1) ans = ans * x % MOD;
    x = x * x % MOD;
  }
  return ans;
}
template <class T>
void cumulative_sum(T &container) {
  for (int i = 0; i < container.size() - 1; i++) container[i + 1] += container[i];
}

class DAllYourPathsAreDifferentLengths {
public:
  static void solve(std::istream &cin, std::ostream &cout) {
    int L;
    cin >> L;
    L--;
    int N = 20;
    map<int, vector<pair<int, int>>> edge;
    rep(i, N - 1) edge[0].emplace_back(i + 1, i + 2);
    int k = 0;
    rep(i, 19) {
      if (bpm(2, i + 1) - 1 > L) {
        k = i - 1;
        break;
      } else if (i == 18) {
        k = i - 1;
      }
    }
    rep(i, k + 1) {
      edge[bpm(2, i)].emplace_back(N - (i + 1), N - i);
    }
    int now = bpm(2, k + 1) - 1;
    while (now != L) {
      FOR(i, -1, 19) {
        if (bpm(2, i + 1) - 1 <= (L - (now + 1)) and (L - (now + 1)) < bpm(2, i + 2) - 1) {
          k = i;
          break;
        }
      }
      edge[now + 1].emplace_back(1, N - (k + 1));
      now = now + 1 + bpm(2, k + 1) - 1;
    }
    int M = 0;
    for (auto &i : edge) {
      M += i.second.size();
    }
    cout << N << " " << M << endl;
    for (auto &i : edge) {
      rep(j, i.second.size()) {
        cout << i.second[j].first << " " << i.second[j].second << " " << i.first << endl;
      }
    }
  }
};


signed main() {
  DAllYourPathsAreDifferentLengths solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

