	lli l;
	cin>>l;

	lli size=0;
	lli two = 1;
	lli tmp = l;
	while(tmp>0){
		size++;
		two*=2;
		tmp/=2;
	}

	lli now = 1;
	lli length = 1;
	lli sum = 0;

	set<lli> s;

	while(sum+length <= l){
		v.push_back({now,{now+1,length}});
		v.push_back({now,{now+1,0}});
		s.insert(now);
		s.insert(now+1);
		sum+=length;
		length *= 2;
		now++;
	}

	lli left = l-sum;
	lli base = now;
	now++;

	set<lli> goal;
	bool first = true;
	while(base>=1){
		s.insert(base);
