				v.push_back({base,{now,0}});
				first=false;
			}
			left -= (left%length);
			s.insert(now);
			goal.insert(now);
			now++;
		}
		base--;
		length/=2;
	}

	lli last = s.size()+1;
	for(auto e:goal){
		s.insert(e);
		s.insert(last);
		v.push_back({e,{last,0}});
