	int a, b, c;
};
pair<int, vector<Edge>> solve(int l) {
	if (l == 1) return {1, {}};
	int n;
	vector<Edge> g;
	tie(n, g) = solve(l / 2);
	for (auto &e : g) {
		++e.a;
		++e.b;
		e.c *= 2;
	}
	g.push_back({1, 2, 0});
	g.push_back({1, 2, 1});
	if (l & 1) g.push_back({1, n + 1, l - 1});
	return {n + 1, g};
}
