void solve() {
    ll L;
    cin >> L;

    ll Ltmp = L;
    unordered_map<ll, ll> factor;
    for (ll i = 2; i * i <= L; i++) {
        while (L % i == 0) {
            ++factor[i];
            L /= i;
        }
    }
    if (L > 1) ++factor[L];

    ll N = 1;
    for (const auto& [_, n] : factor) {
        N += n;
    }

    vector<Tup> edges;
    ll base = 1;
    ll u = 0, v = 1;
    for (const auto& [val, n] : factor) {
        for (ll i = 0; i < n; i++) {
            for (ll j = 0; j < val; j++) {
                edges.emplace_back(u, v, j * base);
            }
            base *= val;
            ++u, ++v;
        }
    }

    cout << N << " " << edges.size() << "\n";
    for (const auto& [a, b, c] : edges) {
        cout << a + 1 << " " << b + 1 << " " << c << "\n";
    }
}

