class graph {
public:
    class path {
    public:
        int len,from,to;
        path(int len_,int from_,int to_) {
            len = len_;from = from_;to = to_;
        }
    };
    int nodes;
    vector<path> paths;
};

graph makeGraph(int maxDist) {
    if(maxDist == 0) {
        graph t;
        t.nodes = 1;
        return t;
    }
    if(maxDist == 1) {
        graph t;
        t.nodes = 2;
        t.paths.push_back(graph::path(0,0,1));
        t.paths.push_back(graph::path(1,0,1));
        return t;
    }
    if(maxDist == 2) {
        graph t;
        t.nodes = 2;
        t.paths.push_back(graph::path(0,0,1));
        t.paths.push_back(graph::path(1,0,1));
        t.paths.push_back(graph::path(2,0,1));
        return t;
    }
    int cdst = (maxDist-1) / 2;
    auto g = makeGraph(cdst);
    g.paths.push_back(graph::path(0,g.nodes-1,g.nodes));
    g.paths.push_back(graph::path(cdst+1,g.nodes-1,g.nodes));
    if(maxDist % 2 == 0)
        g.paths.push_back(graph::path(maxDist,0,g.nodes));
    g.nodes++;
    return g;
}

