V<tuple<ll, ll, ll>> edge;

void solve() {
    edge.clear();

    ll L;
    cin >> L;
    --L;
    FOR(i, 1, 13) {
        edge.pb(mt(i, i + 1, 0));
    }

    ll buf = 0;

    FOR(i, 1, 14) {
        ll base = mypow(3, i - 1);
        if (L < base * 2 - 1) {
            L -= base - 1;
            buf += base;
            break;
        }
        edge.pb(mt(i, i + 1, base));

        if (L < base * 3 - 1) {
            L -= base * 2 - 1;
            buf += base * 2;
            break;
        }
        edge.pb(mt(i, i + 1, base * 2));
    }

    // [buf, buf + L)を作る
    while (L > 0) {
        FOR(i, 1, 14) {
            if (L >= mypow(3, i)) continue;

            ll base = mypow(3, i - 1);
            if (L < base * 2) {
                edge.pb(mt(i, 14, buf));
                buf += base;
                L -= base;
            } else {
                edge.pb(mt(i, 14, buf));
                edge.pb(mt(i, 14, buf + base));
                buf += base * 2;
                L -= base * 2;
            }
            break;
        }
    }

    cout << 14 << " " << SIZE(edge) << endl;
    for (auto t : edge) {
        ll from, to, cost;
        tie(from, to, cost) = t;
        cout << from << " " << to << " " << cost << endl;
    }

    return;
}

