//2進数の気持ちになあると解ける
int main(){

    int L; cin >> L;
    int n = 1;
    int m = 0;

    //ステップ1
    int p = 1;
    while(p <= L){
        n++;
        L -= p;
        p *= 2;
    }

    vector<vector<pair<int, int> > > g(n);
    for(int i = 0; i < n - 1; i++){
        g[i].push_back({i + 1, (int)pow(2, i)});
        g[i].push_back({i + 1, 0});
    }

    //ステップ2
    const int w = (int)pow(2, n - 1) - 1;
    int from = 0;
    int to = n - 1;
    int cost = 1;
    while(L > 0){
        if(L % 2){
            g[from].push_back({to, cost + w});
            cost *= 2;
        }

        L /= 2;
        from++;
    }

    //出力
    cout << n << " " << m << endl;
    for(int i = 0; i < n; i++){
        for(auto to : g[i])
        cout << i + 1 << " " << to.first + 1 << " " << to.second << endl;
    }

    return 0;
}

