long long nibeki(long long a){
    long long t = 1;
    int cnt = 0;
    while(a >= t){
        t = 2*t;
        cnt++;
    }
    return cnt+1;
}
long long nibekii(int a){
    long long k = 1;
    rep(i,a){
        k*=2;
    }
    return k;
}
int main(){
    long long l;
    cin >> l;
    int n = nibeki(l);
    cout << n << endl;
    int m = 2*n-3;
    vector<vector<int>> br;
    vector<long long> len;
    vector<int> tem;
    int temn = n;
    int mm = 0;
    while(l != 1){
        if(l>nibekii(temn-2)){
            l-=nibeki(n-2);
            tem = {temn-1,n};
            br.push_back(tem);
            len.push_back(l);
            mm++;
        }
        temn--;
    }
    cout << n << " " << m+mm << endl;
    cout << 1 << " " << n <<" " << 0 << endl;
    rep(i,n-2){
        cout << i+1 << " "<< i+2 << " "<< 0 << endl;
