#define PII pair<int, int>
#define MP make_pair

using namespace std;

int main() {
	int l;
	scanf("%d", &l);
	vector<pair<PII, int>> edge;
	int n;
	for (n = 0; (1 << n) <= l; n++);
	for (int i = n - 1; i > 0; i--) {
		int k = 1 << (n - i - 1);
		edge.push_back(MP(MP(i, i + 1), k));
		edge.push_back(MP(MP(i, i + 1), 0));
	}
	int kb = 1 << (n - 1), k = 2;
	int pb = 1 << (n - 1), p = 1;
	for (l -= kb; k <= n; k++) {
		kb >>= 1;
		// cout << kb << " " << l << endl;
		if (kb & l) {
			edge.push_back(MP(MP(p, k), pb));
			p = k, pb = kb, l -= kb;
		}
	}
	printf("%d %d\n", n, (int)edge.size());
	for (int i = 0; i < edge.size(); i++) {
		printf("%d %d %d\n", edge[i].first.first,
			edge[i].first.second, edge[i].second);
	}
	return 0;
}

