void add(note*ext,const int&l,const int&r,int&m){
	note x;
	for(int i=l; ++i<=r; e[++m]=node(x.u,x.v,0)){
		x=ext[i];
		for(int j=x.w*x.k; j-=x.w; e[++m]=node(x.u,x.v,j));
	}
}
void swp(int x,int y,int m){
	for(int i=0; ++i<=m; e[i].u==x?(e[i].u=y):(e[i].u==y&&(e[i].u=x)),e[i].v==x?(e[i].v=y):(e[i].v==y&&(e[i].v=x)));
}
void topu(int m){
	bool flag=0;
	int u,v;
	for(int i=0; ++i<=m; )
		if(e[i].u>e[i].v){
			flag=1,u=e[i].u,v=e[i].v;
			break;
		}
	while(flag){
		flag=0,swp(u,v,m);
		for(int i=0; ++i<=m; )
			if(e[i].u>e[i].v){
				flag=1,u=e[i].u,v=e[i].v;
				break;
			}
	}
}
