void solve(int x) {
	if (x <= 4) {
		printf("2 %d\n", x);
		forn(i, x) {
			printf("1 2 %d\n", i);
		}
		return;
	}
	int n = 0;
	int t = x;
	int bitcnt = 0;
	while(t) {
		if (t & 1) bitcnt++;
		t >>= 1;
		n++;
	}
	// printf("\n%d %d %d\n", x, n, bitcnt);
	if (bitcnt == 1) {
		printf("%d %d\n", n - 1, n * 2 - 2);
	} else {
		int m = n * 2 - 2 + bitcnt;
		if (x & 2) {
			m += 1;
		}
		printf("%d %d\n", n, m);	
	}
	printf("1 2 1\n");
	printf("1 2 3\n");
	forn(i, n - 2) {
		printf("%d %d %d\n", i + 1, i + 2, 0);
		printf("%d %d %d\n", i + 1, i + 2, (2 << i));
	}
	t = x;
	int p = 1;
	int s = 0;
	while(t && bitcnt != 1) {
		if (t & 1) {
			if (p == 1) {
				printf("1 %d 0\n", n);
				s++;
			}
			else if (p == 2) {
				printf("1 %d %d\n", n, s);
				printf("1 %d %d\n", n, s + 1);
				s += 2;
			}
			else {
				printf("%d %d %d\n", p - 1, n, s);
				s += 1 << (p-1);
			}
		}
		t >>= 1;
		p++;
	}
}

