int main() {
    int l; cin >> l;
    int n = 1;
    while((1 << (n - 1)) <= l) n += 1;
    vector<edge> es;
    es.emplace_back(1, 3, 1 << (n - 3));
    es.emplace_back(1, 3, 0);
    for(int i = 3; i <= n - 1; ++i) {
        es.emplace_back(i, i + 1, 1 << (n - i - 1));
        es.emplace_back(i, i + 1, 0);
    }
    if(l ^ (l & -l)) { // l != 2^i
        es.emplace_back(2, n - 1, 1 << (n - 2));
