struct Node{
    int a, b, c;
    Node(int _a=0, int _b=0, int _c=0):a(_a), b(_b), c(_c) {}
};

vector<Node> vc;
int main() {
    int L;

    while (~scanf("%d", &L)) {
        vc.clear();
        int tmp = L;
        int cnt1 = 0; int cnt2 = 0;
        while(tmp) {
            if(tmp & 1) cnt2 ++;
            tmp /= 2;
            cnt1 ++;
        }


        int ans = 1<<(cnt1 - 1);
        int ans2 = cnt1;
        if(cnt2 > 1) {
            ans *= 2;
            ans2 ++;
        //    printf("hhhh\n");
        }

        for(int i = 1; i < cnt1; ++i) {
            vc.push_back(Node(i, i + 1, 0));
            vc.push_back(Node(i, i + 1, 1<<(i-1)));
        }

        tmp = L;
        if(cnt2 > 1) {
            for(int i = cnt1 - 1; i >= 0; --i) {
                if( (tmp >> i) & 1 ) {
                    tmp -= 1 << i;
                    vc.push_back(Node(i+1, ans2, tmp));
                }
            }
        }

        printf("%d %d\n", ans2, (int)vc.size());
        for(int i = 0; i < (int)vc.size(); ++i) {
            printf("%d %d %d\n", vc[i].a, vc[i].b, vc[i].c);
        }
    }
    return 0;
}

