    M = 0;
    rep(i, 1, 21) {
      G[i].clear();
    }
    int idx = 2;
    int tmp = 0;
    rep(i, 0, SIZE(num)) {
      add_edge(G, 1, idx, tmp);
      int n = num[i];
      solve(G, idx, n, i);

      tmp += n*powM(param,i);
    }

    rep(i, 1, 21) {
      M += SIZE(G[i]);
    }

    if (M <= 60) {
      break;
    } else {
      param--;
    }
