bool check(vector<tuple<int,int,int>> G, int l){
  int n = 20;
  vector<vector<int>> dp(n, vector<int>(l+1, 0));
  dp[0][0] = 1;
  for(int i=0; i<n; i++){
    vector<tuple<int,int,int>> E;
    for(auto e : G){
      if( get<0>(e) == i ) E.push_back(e);
    }

    for(int d=0; d<l; d++){
      if( dp[i][d] == 0 ) continue;
      for(auto e : E){
        int nx = get<1>(e);
        int dd = d + get<2>(e);
        assert( nx > i );
        assert( dd < l );

        dp[nx][dd] += dp[i][d];
      }
    }
  }

  for(int d=0; d<l; d++){
    if( dp[n-1][d] != 1 ){
      eprintln(d, dp[n-1][d]);
      assert(dp[n-1][d] == 1);
    }
  }
  return true;
}

