long long _pow(long long base,long long k)
{
    long long ans=1;
    while(k>0)
    {
        if(k&1)
        {
            ans*=base;
            ans%=P;
        }
        base*=base;
        base%=P;
        k>>=1;
    }
    return ans;
}
