using P = pair<int, int>;
VV<P> g(20);
int m = 0;
void adde(int a, int b, int c) {
    if (a == 20 || b == 20) return;
    m++;
    g[a].push_back({b, c});
}

// make [0, f, 2f, ..., lf)
void solve(int p, int f, int l) {
    if (l % 2 == 1 && p != 19) {
        adde(p, 19, f * (l - 1));
        l--;
    }
    if (l == 0) return;
    adde(p, p+1, 0);
    adde(p, p+1, f);
    solve(p + 1, 2 * f, l / 2);
}

