void addedge(int s, int t, int l){
	u[M] = s; v[M] = t; w[M] = l;
	++M;
}

int l2(int x){
	int l = 0,r = 25,m;
	while(r - l > 1){
		m = (l+r)/2;
		if(x < (1<<m)){
			r = m;
		}else{
			l = m;
		}
	}
	return l;
}



int main(void){
	int L,p,t,i,l;
	cin >> L;
	p = l2(L); N = p+1;
	for(i=0; i<p; ++i){
		addedge(i+1,i+2,0);
		addedge(i+1,i+2,(1<<i));
	}
	l = (1<<p);
	while(l < L){
		t = l2(L-l);
		addedge(t+1,N,l);
		l += (1<<t);
	}
	cout << N << " " << M << endl;
	for(i=0; i<M; ++i){
		cout << u[i] << " " << v[i] << " " << w[i] << endl;
	}
