using namespace std;

const int K = 20;
struct Edge {
    int u, v,w;
};
vector<Edge> edges;

void solve(int n, int id) {
    if (id == K) {
        assert(n==1);
        return;
    }
    if (n%2)   edges.push_back({id, K, --n});
    if (n==0)   return;
    edges.push_back({id, id+1, n/2});
    edges.push_back({id, id+1, 0});
    solve(n/2, id+1);
}

int main()
{
    int n;
    cin>>n;
    solve(n, 1);
    cout<<K<<" "<<edges.size()<<endl;
    for (Edge e: edges)
        cout<<e.u<<" "<<e.v<<" "<<e.w<<endl;
}

