template< typename T >
struct edge {
  int src, to;
  T cost;

  edge(int to, T cost) : src(-1), to(to), cost(cost) {}

  edge(int src, int to, T cost) : src(src), to(to), cost(cost) {}

  edge &operator=(const int &x) {
    to = x;
    return *this;
  }

  operator int() const { return to; }
};

template< typename T >
using Edges = vector< edge< T > >;
template< typename T >
using WeightedGraph = vector< Edges< T > >;
using UnWeightedGraph = vector< vector< int > >;
template< typename T >
using Matrix = vector< vector< T > >;

int main() {
  int L;
  cin >> L;

  int sz = 0;
  while((1 << (sz + 1)) <= L) sz++;


  Edges< int > edges;
  int used = 0;
  for(int i = sz - 1; i >= 0; i--) {
    edges.emplace_back(used, used + 1, 1 << i);
    edges.emplace_back(used, used + 1, 0);
    ++used;
  }
  int add = 1 << sz;

  used = 0;
  for(int i = sz - 1; i >= 0; i--) {
    if(L - add >= (1 << i)) {
      edges.emplace_back(0, used + 1, add);
      add += 1 << i;
    }
    ++used;
  }

  cout << used + 1 << " " << edges.size() << endl;
  for(auto &p : edges) cout << p.src + 1 << " " << p.to + 1 << " " << p.cost << endl;

