void init(int64 X){
	REP(i, N-1){
		G.push_back(T(i, i+1, 0));
	}
	int64 a = 0;
	idx = 0;
	while((1<<a)-1 <= X){
		a++;
	}
	a--;
	while(1<<idx <= X){
		idx++;
	}
	idx--;
	cerr << idx << endl;

	REP(i, a){
		G.push_back(T(i, i+1, 1<<i));
	}
	if((1 << a)-1 == X){
		answer();
		exit(0);
	}
}

