vector<Edge> solve(int n, int e, int& l, int& r){
//  cout << n << endl;
  vector<Edge> res;
  if(n == 1){
    l = e - 1, r = e;
    res.push_back(Edge(l, e, 0));
    return res;
  }else if(n == 2){
    l = e - 1, r = e;
    res.push_back(Edge(l, e, 0));
    res.push_back(Edge(l, e, 1));
    return res;
  }




  if(n & 1){
    res = solve(n - 1, e, l, r);
    res.push_back(Edge(l, r, n - 1));
