    template<typename T>
    map<ll, ll> Factor::factorMap(T n) {
        map<ll, ll> res;
        ll buf = n;
        for (ll i = 2; i*i<=n; i++) {
            while (buf % i == 0) {
                res[i]++;
                buf /= i;
            }
        }
        if(buf > 1) res[buf]++;
        return res;
    }

    template<typename T>
    void Factor::factorMapAdd(T n, map<T, T> *mp) {
        ll buf = n;
        for (ll i = 2; i*i<=n; i++) {
            while (buf % i == 0) {
                (*mp)[i]++;
                buf /= i;
            }
        }
        if(buf > 1) (*mp)[buf]++;
    }

