int main()
{
    int N = 0, M = 0, L = read<int>();
    for (; L + 1 > (1 << N); N++) {}
    SHOW(N);
    CostGraph<int> G(N);
    for (int i = 0; i < N - 1; i++) { G.addEdge(i, i + 1, 0), G.addEdge(i, i + 1, 1 << i), M += 2; }
    L -= (1 << (N - 1));
    for (int i = N - 2, offset = (1 << (N - 1)); i >= 0; i--) {
        if (L >= (1 << i)) { M++, G.addEdge(i, N - 1, offset), L -= (1 << i), offset += (1 << i); }
    }
    std::cout << N << " " << M << std::endl;
    for (int i = 0; i < N; i++) {
        for (const auto& e : G[i]) {
            std::cout << i + 1 << " " << e.to + 1 << " " << e.cost << std::endl;
        }
