int mlb(int x) {
	if (x & 0xffff0000)
		x &= 0xffff0000;

	if (x & 0xff00ff00)
		x &= 0xff00ff00;

	if (x & 0xf0f0f0f0)
		x &= 0xf0f0f0f0;

	if (x & 0xcccccccc)
		x &= 0xcccccccc;

	if (x & 0xaaaaaaaa)
		x &= 0xaaaaaaaa;
	return x;
}
int popc(int x) {
	x = (x & 0x55555555) + ((x >> 1) & 0x55555555);
	x = (x & 0x33333333) + ((x >> 2) & 0x33333333);
	x = (x & 0x0f0f0f0f) + ((x >> 4) & 0x0f0f0f0f);
	x = (x & 0x00ff00ff) + ((x >> 8) & 0x00ff00ff);
	x = (x & 0x0000ffff) + ((x >> 16) & 0x0000ffff);
	return x;
}
