struct Edge{
  int u, v, w;
  Edge(){}
  Edge(int _u, int _v, int _w):u{_u}, v{_v}, w{_w}{}
};

vector<Edge> adj;
vector<Edge> solve(int n, int e, int& l, int& r){
//  cout << n << endl;
  vector<Edge> res;
  if(n == 1){
    l = e - 1, r = e;
    res.push_back(Edge(l, e, 0));
    return res;
  }else if(n == 2){
    l = e - 1, r = e;
    res.push_back(Edge(l, e, 0));
    res.push_back(Edge(l, e, 1));
    return res;
  }
  if(n % 3 == 0){
    res = solve(n / 3, e, l, r);
    l--;
    res.push_back(Edge(l, l + 1, 0));
    res.push_back(Edge(l, l + 1, n / 3));
    res.push_back(Edge(l, l + 1, 2 * n / 3));
  }else if(n % 3 == 1){
    res = solve(n - 1, e, l, r);
    res.push_back(Edge(l, r, n - 1));
  }else{
    res = solve(n - 2, e, l, r);
    res.push_back(Edge(l, r, n - 1));
    res.push_back(Edge(l, r, n - 2));
  }

  return res;

  if(n & 1){
    res = solve(n - 1, e, l, r);
    res.push_back(Edge(l, r, n));
  }else{
    int nl, nr;
    res = solve(n / 2, e, l, r);
    l--;
    res.push_back(Edge(l, l + 1, 0));
    res.push_back(Edge(l, l + 1, n / 2));
  }
  return res;
}

