        shi <<= 1;
        c++;
      }
      G.push_back({c,N,add});
      add += shi;
    }
  }
  assert(G.size() <= 60);
  cout << N << " " << G.size() << endl;
  for(auto e : G){
    cout << e.i << " " << e.j << " " << e.l << endl;
  }
}

