int build(int next, int l) {
    if (l == 2) {
        add(next, next + 1, 0);
        add(next, next + 1, 1);
        return next + 1;
    }
    if (l == 3) {
        add(next, next + 1, 0);
        add(next, next + 1, 1);
        add(next, next + 1, 2);
        return next + 1;
    }
    if (l % 2 == 1) {
        add(next, -1, l - 1);
        l--;
    }
    add(next, next + 1, 0);
    add(next, next + 1, l / 2);
    return build(next + 1, l / 2);
}

int L;

