void solve(std::istream &in, std::ostream &out) {
  int L;
  in >> L;
  int r = 0;
  while ((1 << (r + 1)) <= L) ++r;
  out << r + 1 << ' ' << (2 * r) + (__builtin_popcount(L)) - 1 << '\n';
  for (int i = 1; i <= r; ++i) {
    out << i << ' ' << i + 1 << ' ' << 0 << '\n';
    out << i << ' ' << i + 1 << ' ' << (1 << (i - 1)) << '\n';
  }
  int ff = (1 << 20) - 1;
  for (int i = 0; i <= 19; ++i) {
    ff -= 1 << i;
    if ((L & ff) == 0) break;
    if (L >> i & 1) {
      out << i + 1 << ' ' << r + 1 << ' ' << (L & ff) << '\n';
    }
  }
}

