class Edge {
public:
	int u, v, w;
	Edge(int _u, int _v, int _w) : u(_u), v(_v), w(_w) {};
};

int main() {
	int L;
	cin >> L;
	vector<Edge> v;
	int N = 1;
	while ((1 << N) <= L) N++;
	for (int i = 1; i < N; i++) {
		v.push_back(Edge(i, i + 1, 0));
		v.push_back(Edge(i, i + 1, 1 << N - i - 1));
	}
	int range = (1 << N - 1) - 1;
	while (range < L - 1) {
		int gap = L - 1 - range;
		int n = N - 2;
		while (n > 0 && (1 << n) > gap) n--;
		if (n != 0) {
			v.push_back(Edge(1, N - n, range + 1));	
			range += (1 << n);
		} else {
			v.push_back(Edge(1, N, L - 1));
			range = L - 1;
		}		
	}
	int M = v.size();
	cout << N << " " << M << "\n";
	for (int i = 0; i < M; i++) cout << v[i].u << " " << v[i].v << " " << v[i].w << "\n";

	return 0;
}

