void solve() {
    Int N = RD();

    Int k = log2_floor(N);

    vector<tuple<Int,Int,Int>> ans;
    REP(i, k) {
        ans.emplace_back(i, i+1, 0);
        ans.emplace_back(i, i+1, BIT_I(i));
    }

    // 作りたい区間
    Int l = pow2_floor(N);
    Int r = N;
    for(Int i = k-1; i >= 0; --i) {
        ASSERT(l <= r);
        if(l == r) break;

        // 現在位置までで作れる区間(ll=0)
        Int rr = BIT_I(i);
        if(l + rr <= r) {
            ans.emplace_back(i, k, l);
            l += rr;
        }
    }

    // 1-based
    for(auto& e : ans) {
        ++get<0>(e);
        ++get<1>(e);
    }

    PRINTLN(k+1, SIZE(ans));
    ALL(for_each, ans, LIFT(PRINTLN));
}

signed main() {
    Int t = 1; //RD();
    LOOP(t) {
        solve();
    }

    EXIT();
}

