using namespace std;

const int N = 1e6 + 123;
const ll mod = 1e9 + 7;
const ll inf = 1e18;
const int M = 210;


ll L, pw[40], mx[N], vis[N], ans;
vector <pll> g[M];


void rec(ll u, ll x) {
	ll tmp = mx[x];
	for (int i = 0; i <= tmp; i++) {
		g[u + i].pb({u + i + 1, pw[i]});
		g[u + i].pb({u + i + 1, 0});
	}
	int last = u + tmp + 1;
//	if (last == 20)
//		return;
	x -= pw[tmp + 1] - 1;
	if (x == 0)
		return;
	g[last].pb({100, 0});
	if (x == 1) {
		g[last].pb({100, 1});
		return;
	}
	g[1].pb({last + 1, pw[tmp + 1]});
	rec(last + 1, x - 1);
}


int main() {
	ios_base::sync_with_stdio(NULL); cin.tie(NULL); cout.tie(NULL);
//	freopen("input.txt", "r", stdin);
	cin >> L;
	L--;
	if (L == 0) {
		cout << "2 1\n" << "1 2 0";
		return 0; 
	}
	ll t = 1;
	for (ll i = 0; i <= 33; i++) {
		pw[i] = t;
		t *= 2;
	}
	mx[1] = 0;
	for (ll i = 2; i <= 1000000; i++) {
		if (pw[mx[i - 1] + 2] <= i + 1)
			mx[i] = mx[i - 1] + 1;
		else
			mx[i] = mx[i - 1];
	}
	rec(1, L);
	ll edg = 0;
	for (int i = 1; i <= 100; i++) {
		for (pll to : g[i]) {
			vis[i] = 1;
			edg++;
			vis[to.f] = 1;
		}
	}
	for (int i = 99; i >= 1; i--)
		if (vis[i]) {
			if (g[i].size() == 0)
				ans = i;
			else
				ans = i + 1;
			break;
		}
	cout << ans << " " << edg << "\n";
	for (int i = 1; i <= 100; i++)
		for (pll to : g[i])
			cout << i << " " << min(ans, to.f) << " " << to.se << "\n";
	return 0;
}

