#include<cstdio>
int digit0b(int x){
    int ans=0;
    while(x>0){
        ans++;
        x/=2;
    }
    return ans;
}
int numofbits(int x){
    int ans=0;
    while(x>0){
        if(x%2==1)ans++;
        x/=2;
    }
    return ans;
}
int lowestbit(int x){
    return x&-x;
}
int main(){
    int l;
    scanf("%d",&l);
    int n=digit0b(l+1),m=2*(n-1)+numofbits(l+1)-1;
    printf("%d %d\n",n,m);
    for(int i=0;i<=n-2;i++){
        printf("%d %d %d\n",i+1,i+2,1<<i);
        printf("%d %d %d\n",i+1,i+2,0);
    }
    int k=numofbits(l+1)-1;
    for(int i=l+1;i>(1<<(n-1));i-=lowestbit(i)){
        printf("%d %d %d",digit0b(lowestbit(i)),n,i-lowestbit(i));
        if(k!=1){
            printf("\n");
            k--;
        }
    }
    return 0;
}

