#include <bits/stdc++.h>
using namespace std;

struct edge {
    int from, to, cost;
    edge(int f, int t, int c) : from(f), to(t), cost(c) {}
};

int main() {
    int l; cin >> l;
    int n = 1;
    while((1 << n) <= l) n += 1;
    vector<edge> es;
    for(int i = 1; i <= n - 1; ++i) {
        es.emplace_back(i, i + 1, 1 << (n - i - 1));
        es.emplace_back(i, i + 1, 0);
    }
    if(l ^ (l & -l)) { // l != 2^i
        const int base_cost = 1 << (n - 1);
        int cur = l - 1;
        for(int i = 2; i <= n - 1; ++i) {
            if((l - (1 << (n - 1))) & (1 << (n - i))) {
                const int t = (1 << (n - i)) - 1;
                es.emplace_back(1, i, base_cost + cur - (1 << (n - 1)) - t);
                cur = (1 << (n - 1)) + es.back().cost - 1 - base_cost;
            }
        }
        if(es.back().cost != base_cost) {
            es.emplace_back(1, n, base_cost);
        }
    }

    cout << n << " " << es.size() << endl;
    for(const auto& e : es) {
        cout << e.from << " " << e.to << " " << e.cost << endl;
    }
    assert(n <= 20 && es.size() <= 60u);
}

