      mx=i;
      break;
    }
  }
  vector<vector<int>> ANS;
  for(int i=0;i<mx;i++){
    ANS.push_back({i+1,i+2,0});
    ANS.push_back({i+1,i+2,dpw(i)});
  }
  int a=0;
  for(int i=mx;i>=0;i--){
    if(V[i]){
      ANS.push_back({i+1,mx+2,a});
      a+=dpw(i);
    }
