int log2(int x){
    for(int i=0;i<=21;i++){
        if((1<<i)>x){
            return i-1;
        }
    }
}

int main(){
    int L;
    cin >> L;

    int lg2;
    for(int i=0;i<=21;i++){
        if((1<<i)>L){
            lg2=i;
            break;
        }
    }

    int N=lg2;
    int M=2*(N-1);
    string s="";
    for(int i=1;i<N;i++){
        s=s+to_string(i)+" "+to_string(i+1)+" "+to_string(1<<(N-i-1))+"\n";
        s=s+to_string(i)+" "+to_string(i+1)+" "+to_string(0)+"\n";
    }
    int ok=(1<<(N-1))-1;
    int next=1<<(N-1);

    while(ok+1<L){
        int rest=L-1-ok;
        s+="1 "+to_string(N-log2(rest))+" "+to_string(next)+"\n";
        M++;
        ok+=1<<(log2(rest));
        next=ok+1;
    }
    cout << N << " " << M <<endl;
    cout << s << endl;

    return 0;
}

