    }

    base >>= 1;

    for (ll i = n - 1; i >= 0; i--) {
        ll t = L - base;
        if (t > base) {
            edges.emplace_back(i, n, t);
            L = t;
        }
        base >>= 1;
    }

    cout << n + 1 << " " << edges.size() << "\n";
    for (const auto& [a, b, c] : edges) {
        cout << a + 1 << " " << b + 1 << " " << c << "\n";
    }
}

