int l, last;
vector<pair<int, int> > adj[50];

void solve(int now, int l)
{
	if(l==0)
	{
		last=now;
		return;
	}
	if(l%2==1)
	{
		adj[now].push_back({now+1, (l+1)/2});
		adj[now].push_back({now+1, 0});
		solve(now+1, l/2);
	}
	else
	{
		adj[now].push_back({now+1, (l/2)+1});
		adj[now].push_back({now+1, 0});
		solve(now+1, (l/2-1));
		sp.push_back({now, l/2});
	}
}

