struct edge
{
	int v,c;
	edge(){};
	edge(int vv,int cc)
	{
		v=vv,c=cc;
	}
};
vector<edge>w[MAXN];
int dfs(int now)
{
	if(now==0)
		return 1;
	int last=dfs(now/2);
	w[last].push_back(edge(last+1,0));
	m++;
	if(now!=1)
	{
		w[last].push_back(edge(last+1,now/2));
		m++;
	}
	if(now&1)
	{
		w[last].push_back(edge(last+1,now));
		m++;
	}
	return last+1;
}
