    }();

    vector<vector<Edge>> ans(ma);

    rep(i, ma) {
        ans[i].push_back(Edge{i + 1, 0ll});
        ans[i].push_back(Edge{i + 1, 1ll << i});
    }

    ll f = 0;
    f += (1 << ma);

    ll nokori = l - (1 << ma);

    for (int i = 30; i >= 0; i--) {
        if ((nokori >> i) & 1) {

            ans[i].push_back({ma, f});
            f += (1 << i);

        }
    }
    return ans;

}

