            u.push_back(a);
            v.push_back(b);
            w.push_back(c);
        };
        while(L > 3*d){
            set(now_n, now_n+1, 0);
            set(now_n, now_n+1, d);
            set(now_n, now_n+1, d * 2);
            d *= 3;
            now_n--;
        }
