struct edge{int u,v,w;};
vector<edge> x;
void build(int v,int r,int step,int lim)
{
	int cnt=r/step+1;
	if(cnt<=lim)
	{
		for(int i=0;i<=r;i+=step)x.push_back({1,v,i});
		return;
	}
	if(cnt&1)x.push_back({1,v,r}),r-=step,lim--;
	x.push_back({v-1,v,0});
	x.push_back({v-1,v,1});
	build(v-1,r,step<<1,lim-2);
}
