const ll LLINF = (1LL<<60);
const int INF = (1LL<<30);
const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 100010
#define MAX_FACT 30

ll L;
ll fact[MAX_FACT];
ll to_cost[MAX_FACT] = {};  // ノード i に行くエッジの最大コスト(0 じゃないほう)

// [lb, ub) の範囲で val 以下の要素で最大のもののインデックスを返す
// なければ -1 を返す
ll bin_search4(ll lb, ll ub, ll val) {
    lb--; ub--;
    while(ub - lb > 1) {
        ll mid = (lb + ub) / 2;
        if(fact[mid] >= val) {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    // この時点で lb + 1 = ub
    if(fact[ub] <= val) { return ub; }
    if(lb < 0) { return -1; }
    if(fact[lb] > val) { return -1; }
    return lb;
}

// num 以下の表現できる最大の 2 べきの値を返す
ll get_max(ll num) {
    ll index = bin_search4(0, MAX_FACT, num);
    if(index < 0) { return -1; }
    return fact[index];
}
// num 以下の表現できる最大の 2 べきの指数を返す
ll get_index(ll num) { return bin_search4(0, MAX_FACT, num); }


struct Edge { int from, to, cost; };

signed main()
{
    cin >> L;

    // fact の作成
    fact[0] = 1;
    for(int i = 1; i < MAX_FACT; ++i) { fact[i] = fact[i-1] * 2; }

    // ノード数の決定とグラフのベースを作成
    vector<Edge> ans;
    ll nodes = 1;   // ノード数
    ll loop_val = get_max(L/2);
    while(loop_val > 0) {
        ans.push_back({nodes, nodes+1, loop_val});
        ans.push_back({nodes, nodes+1, 0});
        to_cost[nodes+1] = loop_val;
        nodes++;
        loop_val /= 2;
    }

    // 残りの辺を適切に生やす
    ll remain = L - get_max(L);
    ll cur_cost = get_max(L);   // 増やすエッジのコスト
    while(remain > 0) {
        ll node_to = nodes - get_index(remain); // エッジの指し先
        ans.push_back({1, node_to, cur_cost});
        cur_cost += to_cost[node_to];
        remain -= get_max(remain);
    }

    // 答えの表示
    printf("%lld %zu\n", nodes, ans.size());
    for(auto& e : ans) { printf("%lld %lld %lld\n", e.from, e.to, e.cost); }

    return 0;
}

