    int num=13;
    vector<int> pow3(21,1);
    for(int i=0; i<num; i++){
        pow3[i+1]=pow3[i]*3;
    }

    int n=log3(L+1);
    vector<vector<int> > path(0);
    for(int i=1; i<num; i++){
