            path.push_back({i+1, i+2, j*base});
        }
        base*=3;
    }

    L-=base;
    while(base!=goal){
        n=log3(L+1);
        path.push_back({n+1,num,base});
        base+=pow3[n];
        L-=pow3[n];
    }

    cout << num << ' ' << (int)path.size() << endl;
    for(auto &p:path){
        cout_vec(p);
    }
