int mlb(int x) {
	if (x & 0xffff0000)
		x &= 0xffff0000;
	if (x & 0xff00ff00)
		x &= 0xff00ff00;
	if (x & 0xf0f0f0f0)
		x &= 0xf0f0f0f0;
