#define int long long

const int N=25;

int k;
vector<int> v;
vector<pair<int, int> > g[N];
int store[N];

int32_t main()
{
	IOS;
	cin>>k;
	v.push_back(1);
	int cur=1;
	store[1]=1;
	int idx=2;
	int edges=0;
	for(int i=2;cur*2<=k;i++, cur*=2)
	{
		g[v.back()].push_back({i, 0});
		g[v.back()].push_back({i, cur});
		v.push_back(i);
		store[cur*2]=i;
		idx++;
		edges+=2;
	}
	int weight=0;
	for(int i=19;i>=0;i--)
	{
		if(k&(1<<i))
		{
			g[store[1<<i]].push_back({idx, weight});
			weight+=1<<i;
			edges++;
		}
	}
	cout<<idx<<" "<<edges<<endl;
	for(int i=1;i<=idx;i++)
	{
		for(auto &it:g[i])
			cout<<i<<" "<<it.first<<" "<<it.second<<endl;
	}
	return 0;
}

