int main ()
{
	cin >> L;

	for (int i = 2; i < 20; i++)
	{
		edges.emplace_back(i, i+1, 0);
		edges.emplace_back(i, i+1, 1<<(19-i));
	}

	int idx = 20;
	int pow = 0;
	int S = 0;

	while (L > 0)
	{
		if (L%2 == 1)
		{
			edges.emplace_back(1, idx, S);
			S += 1 << pow;
		}
		L >>= 1;
		pow++;
		idx--;
	}

	cout << 20 << " " << edges.size() << endl;
	for (const Edge& e : edges)
	{
		cout << e.x << " " << e.y << " " << e.z << endl;
	}

