void solve(ll L) {
  vector<tuple<int,int,int>> res;
  for (int i = 2; i < 20; ++i) {
    res.emplace_back(i, i + 1, 0);
    res.emplace_back(i, i + 1, 1 << (19 - i));
  }

  bool flag = false;
  for (int i = 0; i < 20 || flag; ++i) {
    flag = false;
    if (((L >> i) & 1) == 0) continue;
    if (i == 19) { --i; flag = true; }
    int value = L - (1 << i);
    res.emplace_back(1, 20 - i, value);
    L = value;
    if (flag) --i;
  }

  cout << 20 << " " << res.size() << endl;
  for (auto t: res) {
    int a, b, c;
    tie(a, b, c) = t;
    cout << a << " " << b << " " << c << endl;
  }
}

int main() {
	ll L;
	scanf("%lld", &L);
	solve(L);
	return 0;
}
