int pow(int x, int b){
  int res = 1;
  for(int i=0; i < x; i++){
    res *= b;
  }
  return res;
}

int main(){
  int L;
  scanf("%d", &L);
  int X = L;
  int numV = (int)floor(log2(X + 1)) + 1;
  //printf("numv: %d\n", numV);

  for(int i=0; i < numV - 1; i++){
    addEdge(i+1, i, 0);
    addEdge(i+1, i, pow(i, 2));
  }

  int home = numV - 1;
  int sum = pow(numV - 1, 2);
  int last = sum;
  while(sum < X){
    int y = (int)floor(log2(X - sum + 1));
    addEdge(home, y, sum);
    last = pow(y, 2);
    sum += last;
  }

  // swap the names of vertices
  printf("%d %d\n", numV, numE);
  for(int i=0; i < numE; i++){
    printf("%d %d %d\n", numV - u[i], numV - v[i], w[i]);
  }
