int main() {
    p_init();
    int L; cin >> L;
    int N; // 頂点の数
    int M; // 辺の数
    vector<edge> res;
    int v1=1;
    while(p[v1]-1 < L) v1++;
    N = v1 + 1;
    FOR(i,1,v1) {
        res.push_back((edge){i,i+1,0});
        res.push_back((edge){i,i+1,p[i-1]});
    }
    int a = L-1;
    while(a>=0) {
        for(int i=v1; i>=1; --i) {
            if(p[i-1]-1 <= a) {
                res.push_back((edge){i,N,a-p[i-1]+1});
                a -= p[i-1];
            }
        }
    }
    M = res.size();
    cout << N << " " << M << endl;
    for(auto e:res) {
        cout << e.from << " " << e.to << " " << e.cost << endl;
    }
