int bitLength(int x) {
	if (x == 0) return 0;
	return 1 + bitLength(x >> 1);
}

int main() {
	int L; scanf("%d", &L);
	int bitCount = bitLength(L);
	// we will have bitCount vertices
	vector<pair<int, int>> edges;
	vector<int> eWeight;
	for (int dst = 1; dst < bitCount; ++dst) {
		edges.emplace_back(dst - 1, dst);
		eWeight.emplace_back((1<<(dst-1)));
		edges.emplace_back(dst - 1, dst);
		eWeight.emplace_back(0);
	}
	int cMax = (1 << (bitCount - 1)) - 1;
	for (int src = bitCount - 2; src >= 0; --src) {
		if (L & (1 << src)) {
			// add an edge
			edges.emplace_back(src, bitCount - 1);
			eWeight.emplace_back(cMax + 1);
			cMax = cMax + (1 << src);
		}
	}
	// printf("BC %d\n", bitCount);
	printf("%d %lu\n", bitCount, edges.size());
	for (int i = 0; i < edges.size(); ++i) {
		printf("%d %d %d\n", edges[i].first + 1, edges[i].second + 1, eWeight[i]);
	}
	return 0;
}

