void solve()
{
    LL L;
    cin >> L;

    vector<edge> G;

    int s = 1;
    while ((1LL << s) <= L)
    {
        G.push_back(edge{s, s + 1, 0});
        G.push_back(edge{s, s + 1, 1LL << (s - 1)});
        s++;
    }

    LL p2 = (1LL << (s - 1));
    LL N = s;

    for (int t = N - 1; t > 0; t--)
    {
        if (p2 + (1LL << (t - 1)) <= L)
        {
            L -= (1LL << (t - 1));
            G.push_back(edge{t, N, L});
        }
    }
    cout << N << " " << G.size() << endl;
    for (auto e : G)
    {
        cout << e.s << " " << e.t << " " << e.l << endl;
    }
}

