using Tup = tuple<ll, ll, ll>;

void solve() {
    ll L;
    cin >> L;

    ll Ltmp = L;
    ll n = 0;
    while (Ltmp > 0) {
        Ltmp /= 2;
        ++n;
    }
    --n;

    vector<Tup> edges;
    ll base = 1;
    for (ll i = 0; i < n; i++) {
        edges.emplace_back(i, i + 1, 0);
        edges.emplace_back(i, i + 1, base);
        base <<= 1;
    }

    base >>= 1;
    ll h = base * 2 - 1;

    for (ll i = n - 1; i >= 0; i--) {
        ll t = L - base;
        if (t > h) {
            edges.emplace_back(i, n, t);
            L = t;
        }
        base >>= 1;
    }

    cout << n + 1 << " " << edges.size() << "\n";
    for (const auto& [a, b, c] : edges) {
        cout << a + 1 << " " << b + 1 << " " << c << "\n";
    }
}

