void dobl(vector<tuple<int,int,int>> &g, int &n, int l){
  for(int i=0;i<g.size();i++){ 
    int &t = get<2>(g[i]);
    get<2>(g[i]) = 2 * t;
  }
  n++;
  g.push_back(make_tuple(n-1,n,1));
  g.push_back(make_tuple(n-1,n,0));
}
void incl(vector<tuple<int,int,int>> &g, int &n, int l){
	g.push_back(make_tuple(1,n,l));
}

