    res.push_back(Edge{1,20,l});
    while(fr>=3 && l){
        int frr=fr;
        if(l/5==0){
            frr=1;
        }
        else{
            if(l*th<=1e6) res.push_back(Edge{1,fr,l/5*th*5});
