};

int main() {
  ll L;
  cin >> L;

  vector<ll> bits;
  while (L > 0) {
    bits.push_back(L % 2);
    L /= 2;
  }
  reverse(bits.begin(), bits.end());

  vector<edge> E;
  REP(i, 0, bits.size() - 1) {
    E.push_back((edge) { (ll) bits.size() - i - 2, (ll) bits.size() - i - 1, 0 });
    E.push_back((edge) { (ll) bits.size() - i - 2, (ll) bits.size() - i - 1, 1LL << i });
  }
  ll s = 1LL << (bits.size() - 1);
  REP(i, 1, bits.size()) {
    if (bits[i] == 1) {
      E.push_back((edge) { 0, i, s });
      s += 1LL << ((ll) bits.size() - i - 1);
    }
  }

  cout << bits.size() << " " << E.size() << endl;
  REP(i, 0, E.size()) cout << E[i].u + 1 << " " << E[i].v + 1 << " " << E[i].d << endl;
