int get_gen(int p){
  return 20 - p;
}
void add_edge(vector<Edge>& adj, int u, int v, int w){
  adj.push_back(Edge(u, v, w));
}
int add_to(vector<Edge>& adj, int base, int len){
  int p = 1;
  for(int i = 1;i < len;i++){
    for(int x = 0;x < base;x++){
      add_edge(adj, 20 - i, 20 - i + 1, x * p);
    }
    p *= base;
  }
  return 20 - (len - 1);
}
vector<Edge> solve(int l, int base){
  int len = 0;
  int arr[100] = {0};
  int p = 1;
  int lst = -1;
  while(l){
    arr[len++] = l % base;
    l /= base;
    p *= base;
    if(lst == -1 && arr[len - 1] != 0)lst = len - 1;
  }
//  cout << lst << endl;
//  p /= base;
  vector<Edge> adj;
  int used = add_to(adj, base, len);
  int cur = 1;
  for(int i = len - 1;i >= 0;i--){
    p /= base;
    if(!arr[i])continue;
    if(i != lst && (cur + 1 >= used))
      throw 1;
    add_edge(adj, cur, (i == lst ? 20 : cur + 1), arr[i] * p);
    for(int x = 0;x < arr[i];x++){
      add_edge(adj, cur, get_gen(i), x * p);
    }
    cur++;
  }
  return adj;
}
