void solve() {
    int l;
    cin >> l;
    int p = 0;
    while (l >= pow(2, p+1)) ++p;
    int lastn = p + 1;
    int minv = pow(2,p);
    int e = 0;
    VI a,d;
    RREP(i,0,p) if (l - minv >= pow(2,i)) {
        //cout << i + 1 << " " << lastn << " " << minv + 1 << endl;
        a.push_back(i+1);
        d.push_back(minv);
        ++e;
        minv += pow(2,i);
    }
    cout << lastn << " " << (lastn - 1) * 2 + e << endl;
    REP(i,0,p) {
        cout << i + 1 << " " << i + 2 << " " << 0 << endl;
        cout << i + 1 << " " << i + 2 << " " << (LL)pow(2,i) << endl;
    }
    REP(i,0,e) cout << a[i] << " " << lastn << " " << d[i] << endl;
}

