bool cek_bit(int id, int mask){
	return (1<<id) & mask;
}

int cnt_bit(int x){
	int ret = 0;
	while(x > 0){
		ret++;
		x/=2;
	}
	return ret;
}

vector<piipi> li;

int main(){
	scanf("%d",&n);
	n--;
	int pan = cnt_bit(n);
	printf("%d ",pan+1);
	for(int i=1;i<pan;i++){
		li.push_back(make_pair(make_pair(i+1,i+2),(1<<(pan-i-1))));
		li.push_back(make_pair(make_pair(i+1,i+2),0));
	}
	li.push_back(make_pair(make_pair(1,2),0));
