	int lol = 1;
	for(int i=0;i<pan;i++){
		if(!cek_bit(i,n)) lol = 0;
	}
	for(int i=pan-1;i>=0;i--){
		if(cek_bit(i,n)){
			if(cur != 0)li.push_back(make_pair(make_pair(1,idx),cur));
