    vector<int> id(n);
    for (int i = 0, cur; i < 18; ++i, ++cur) {
      if (cur ^ i) {
        edge.emplace_back(i, i + 1, 0);
        edge.emplace_back(i, i + 1, 1 << cur);
        id[cur + 1] = i + 1;
      }
      else {
        if (i && !( (l >> i) & 1) ) {
          edge.emplace_back(i - 1, i, 1 << cur);
          edge.emplace_back(i - 1, i, (1 << cur) + (1 << (cur - 1) ) );
