          ++cur;
        }
        edge.emplace_back(i, i + 1, 0);
        edge.emplace_back(i, i + 1, 1 << cur);
        id[cur + 1] = i + 1;
      }
    }

    for (int i = 19; ~i; --i) if ( (l >> i) & 1) {
      l ^= 1 << i;
      edge.emplace_back(id[i], n - 1, l);
    }
  }
