  vector<III> E;
  int n=0,l=L;
  while(l>0) l/=2,++n;
  --n;
//  dump(n);
  REP(i,n) {
    E.emplace_back(i,i+1,0);
    E.emplace_back(i,i+1,1<<i);
  }
  int w=1<<n;
  for(int i=n-1; i>=0; --i) {
    if((L>>i)&1) {
      E.emplace_back(i,n,w);
