void Build(int x,int L)
{
	if(L<0)
		return;
	if(L==0)
		{
			if(x<n)
				add(x,n,0);
			return;
		}
	if(L==1)
		{
			add(x,n,0);
			add(x,n,1);	
			return;
		}
	if(L&1==0)
		add(x,n,L);
	L=(L+1)/2;
	int y=x+1;
	add(x,y,0);
	add(x,y,L);
	--L;
	Build(y,L); 
}
