int DFS(int u) {
    if (dp[u] != -1) return dp[u];
    if (u == n) return 1;

    int &res = dp[u] = 0;
    fto(i, 0, sz(g[u])-1) {
        int v = g[u][i].first;
        res += DFS(v);
    }
    return dp[u];
}

void Check() {
    fto(u, 1, n) g[u].clear();
    for(Edge e: edge) {
        g[e.u].pb({e.v, e.w});
    }

    fto(u, 1, n) dp[u] = -1;
    if (DFS(1) != L) {
        printf("%d\n", L);
        return;
    }
}

void Solve() {
    n = 20;
    edge.clear();

    fto(i, 1, n-2) {
        edge.pb({i, i+1, 0});
        edge.pb({i, i+1, 1<<(i-1)});
    }

    int cur = 0;
    if (L >= (1<<(n-1))) {
        edge.pb({n-1, n, 0});
        edge.pb({n-1, n, 1<<(n-2)});
        cur += 1<<(n-1);
    }

    fdto(i, n-2, 0) {
        if ((L>>i)&1) {
            edge.pb({i+1, n, cur});
            cur += 1<<i;
        }
    }

    m = sz(edge);
    printf("%d %d\n", n, m);
    for(Edge e: edge) printf("%d %d %d\n", e.u, e.v, e.w);
}

