    while(L > 0){
        if(L % 2){
            g[from].push_back({to, cost + w});
            cost *= 2;
            m++;
        }

        L /= 2;
        from++;
    }

    //出力
    cout << n << " " << m << endl;
    for(int i = 0; i < n; i++){
        for(auto to : g[i])
        cout << i + 1 << " " << to.first + 1 << " " << to.second << endl;
