vector<int> f(int n) {
    if (n == 0) return vector<int>(0);
    vector<int> v1(1);
    int b = 1;
    int e = 0;
    while (b * 2 <= n) {
        b *= 2;
        e++;
    }
    v1[0] = e;
    vector<int> v2 = f(n - b);
    for (int v: v2) v1.push_back(v);
    return v1;
}

