	}

	IREP(i, n)
	{
		if (L - pow(2, i) >= pow(2, n))
		{
			e.push_back(Edge(i + 1, n + 1, L - pow(2, i)));
			L -= pow(2, i);
		}
	}

	cout << n + 1 << " " << e.size() << endl;
	REP(i, e.size())
	{
		cout << e[i].f << " " << e[i].t << " " << e[i].c << endl;
	}
