int get_pow2_idx(int L)
{
  if (L == 1)
  {
    return 0;
  }
  int idx = 0;
  int p = 1;
  while (p <= L)
  {
    idx++;
    p *= 2;
  }
  return idx - 1;
}
void init()
{
  pow2[0] = 1;
  for (int i = 1; i < MAX_N + 5; i++)
  {
    pow2[i] = 2 * pow2[i - 1];
  }
}

