  int base = 0;
  for (int i = MAX_N - 1; i >= 1; i--)
  {
    if (tmp_L - p < 0)
    {
      break;
    }
    tmp_L -= p;
    edges[i - 1].push_back(mp(i, p));
    base += p;
    p *= 2;
  }
  while (tmp_L > 0)
  {
    int sum = 0;
    int idx = -1;
