	ll tmp = mx[x];
	for (int i = 0; i <= tmp; i++) {
		g[u + i].pb({u + i + 1, pw[i]});
		g[u + i].pb({u + i + 1, 0});
	}
	int last = u + tmp + 1;
	ans = last;
