int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);
    cout << fixed << setprecision(15);

    int L;
    cin >> L;

    int SIZE = -1;
    for (int i = 19; i > 0; i--) {
        if ((L >> i)&1) {
            SIZE = i + 1;
            break;
        }
    }
    assert(SIZE != -1);
    assert(SIZE <= 20);

    // reverse the labels at the end
    vector<vector<array<int, 2>>> g(SIZE);

    // build the default edges
    for (int i = 0; i + 1 < SIZE; i++) {
        g[i+1].push_back({ i, 0 });
        g[i+1].push_back({ i, 1 << i });
    }

    // add extra edges to the root
    int pref = 0;
    for (int i = 19; i >= 0; i--) {
        if ((L >> i)&1) {
            if (i < SIZE - 1) {
                g[SIZE - 1].push_back({ i, pref });
            }
            pref += 1 << i;
        }
    }

    int ec = 0;
    for (auto &v : g) ec += v.size();
    assert(ec <= 60);

    cout << SIZE << " " << ec << "\n";
    for (int i = 0; i < SIZE; i++) {
        for (auto e : g[i]) {
            cout << SIZE - i << " " << SIZE - e[0] << " " << e[1] << "\n";
        }
    }

    return 0;
}

