int main(){
  i64 L;
  cin >> L;

  L--;

  int N = 20;
  vector<edge> G;

  i64 now = 1;
  int cnt = 1;
  while(now * 2 - 1 <= L){
    G.push_back({cnt,cnt + 1,0LL});
    G.push_back({cnt,cnt + 1,now});
    now <<= 1;
    cnt++;
  }

  G.push_back({cnt,N,0});

  if(L - now > 0){
    i64 add = now;
