	void trans(int x,int base)
	{
		n=0;
		while (x)
		{
			f[++n]=x%base;
			x=x/base;
		}
		w[1]=1;for (int i=2;i<=n;i++) w[i]=w[i-1]*base;
//		printf("f:");for (int i=1;i<=n;i++) printf("%d ",f[i]);puts("");
//		printf("w:");for (int i=1;i<=n;i++) printf("%d ",w[i]);puts("");
		for (int i=1;i<=n/2;i++) std::swap(f[i],f[n-i+1]),std::swap(w[i],w[n-i+1]);
	}
	void solve(int l,int base)
    {
	    trans(l,base);
	    int s=0;
		p=0,q=0;
		for (int i=1;i<=n;i++)
		{
			if (i==1)
			{
			    for (int j=0;j<f[1];j++) add(1,3,w[1]*j,w[1]),++q;
			    add(1,2,w[1]*f[1],w[1]),++q;
			}
			else if (i==n)
			{
				for (int j=0;j<base;j++) add(n+1,n+2,w[n]*j,w[n]),++q;
				for (int j=0;j<=f[n];j++) add(2,n+2,s+w[n]*j,w[n]),++q;
			}
			else
			{
				for (int j=0;j<base;j++) add(i+1,i+2,w[i]*j,w[i]),++q;
				for (int j=0;j<f[i];j++) add(2,i+2,s+w[i]*j,w[i]),++q;
			}
			if (i!=1) s=s+w[i]*f[i];
//			printf("s:%d\n",s);
		}
		p=n+2;
	}
