int getN(int L){
    int ret = 0;
    for(int i=0;i<=20;i++) if(L & (1<<i)) ret = i;
    return ret + 1;
}

int main(){
    int L; cin >> L;
    // require [0,L)
    int n = getN(L);

    using P = tuple<int,int,int>;
    vector<P> ans;
    // complete [0,2^(n-1))
    for(int i=1;i<n;i++) ans.push_back(P(i,i+1,0));
    for(int i=1;i<n;i++) ans.push_back(P(i,i+1,(1<<(i-1))));

    int r = (1 << (n-1));

    // node 1 -> node t = [0,2^(t-1))
    for(int i=n-1;i>=1;i--){
        int cost = r;
        // [ll,rr)
        int ll = r;
        int rr = ll + (1 << (i-1));
        if(rr > L) continue;
        else{
            ans.push_back(P(i,n,cost));
            r = rr;
        }
    }

    cout << n << " " << ans.size() << endl;
    for(const auto& p : ans){
        int a,b,c;
        tie(a,b,c) = p;
        cout << a << " " << b << " " << c << endl;
    }
}

