void Output() {
  int M = 0;
  queue<int> que;
  rep(v, N) {
    if (res[v] == 0) {
      que.push(v);
    }
  }

  int idx = 0;
  while (!que.empty()) {
    int v = que.front(); que.pop();
    ord[v] = idx++;
    for (auto &p : es[v]) {
      int u = p.X;
      res[u]--;
      if (res[u] == 0) {
        que.push(u);
      }
    }
    M += es[v].size();
  }
  assert(idx == N);

  cout << N << " " << M << endl;
  rep(v, N) {
    for (auto &p : es[v]) {
      int u = p.X;
      cout << ord[v]+1 << " " << ord[u]+1 << " " << p.Y << endl;
    }
  }
}

