int l;
int N;
vector<vector<int>> edges;

int pow2[20];

void init() {
    pow2[0] = 1;
    for (int i = 1; i <= 20; i++) pow2[i] = pow2[i - 1] * 2;
}

int main() {
    init();
    cin >> l;
    int t = 1, r = 0;
    while (t <= l) {
        t *= 2;
        r++;
    }
    N = r;
    for (int i = 1; i < N; i++) {
        edges.push_back({i, i + 1, 0});
        edges.push_back({i, i + 1, pow2[i - 1]});
    }
    int rest = l + 1 - pow2[N - 1];
    t = 1, r = 0;
    while (t < rest) {
        t *= 2;
        r++;
    }
    r++;
    edges.push_back({r, N, l - pow2[r - 1]});
    cout << N << " " << edges.size() << endl;
    for (int i = 0; i < edges.size(); i++) {
        cout << edges[i][0] << " " << edges[i][1] << " " << edges[i][2] << endl;
    }
}

