using namespace std;

typedef pair <int, int> ii;
typedef pair <ii, int> iii;

const int Maxn = 20;

int L;
vector <iii> E;

void Add(int a, int b, int c)
{
    a = Maxn - a;
    b = Maxn - b;
    E.push_back(iii(ii(a, b), c));
}

int main()
{
    scanf("%d", &L); L--;
    Add(1, 0, 0);
    Add(1, 0, 1);
    Add(1, 0, 2);
    Add(1, 0, 3);
    for (int i = 2; i < 19; i++) {
        Add(i, i - 1, 0);
        Add(i, i - 1, 1 << i);
    }
    int cur = 0;
    for (int i = 19; i > 1; i--)
        if (L & 1 << i) {
            Add(19, i - 1, cur);
            cur |= 1 << i;
        }
    if (L & 1 << 1) {
        Add(19, 0, cur);
        Add(19, 0, cur + 1);
        cur |= 1 << 1;
    }
    if (L & 1 << 0) {
        Add(19, 0, cur);
        cur |= 1 << 0;
    }
    Add(19, 0, cur);
    printf("%d %d\n", Maxn, int(E.size()));
    for (int i = 0; i < E.size(); i++)
        printf("%d %d %d\n", E[i].first.first, E[i].first.second, E[i].second);
    return 0;
}

