using namespace std;

int n, m;
stringstream ss;

void solve(int l) {
  if (l == 1) {
    n = 2;
    m = 1;
    ss << "1 2 0" << endl;
  } else if ((l % 2) == 0) {
    solve(l/2);
    ss << n << ' ' << n+1 << ' ' << 0 << endl;
    ss << n << ' ' << n+1 << ' ' << l/2 << endl;
    ++n;
    m += 2;
  } else {
    solve(l-1);
    ss << "1 " << n << ' ' << l-1 << endl;
    ++m;
  }
}

int main() {
  int l;
  cin>>l;
  solve(l);
  cout << n << ' ' << m << endl;
  cout << ss.str();
  return 0;
}

