int keta(int x) {
    int ret = 0;
    while(x) {
        ret++;
        x >>= 1;
    }
    return ret;
}
int bitpopcount(ll n) {
    int res = 0;
    while (n) {
        if (n & 1) res++;
        n >>= 1;
    }
    return res;
}
