    n++;
  vector<vector<int>> res;
  for (int i = 1; i < n; i++)
  {
    res.push_back({i, i + 1, 1 << (i - 1)});
    res.push_back({i, i + 1, 0});
  }
  int now = (1 << (n - 1)) - 1;
  for (int i = n - 1; i >= 0; i--)
  {
    if (now == l - 1)
      break;
    int gain = 1 << (i - 1);
    if (now + gain <= l - 1)
    {
      res.push_back({i, n, now + 1});
      now += gain;
    }
  }
  cout << n << " " << res.size() << endl;
  for (auto &&i : res)
  {
    cout << i[0] << " " << i[1] << " " << i[2] << endl;
  }
}
