struct edge
{
	int u, v, w;

	edge() { }
	edge(int _u, int _v, int _w): u(_u), v(_v), w(_w) { }
};

inline void solve()
{
	const int MAXN = 20;

	int N = 0;
	static vector<edge> E;
	static int prefix[MAXN + 5];
	E.clear(), prefix[1] = 0;

	for(N = 2; N <= 20 && prefix[N - 1] + (1 << (N - 2)) <= L; ++N)
	{
		prefix[N] = prefix[N - 1] + (1 << (N - 2));
		E.emplace_back(N - 1, N, 1 << (N - 2));
		E.emplace_back(N - 1, N, 0);
	}
	--N;

	int cnt = L - (1 << (N - 1)), cur = prefix[N];
	for(int i = N; i; --i)
		while(cnt >= (1 << (i - 1)) && cur + prefix[i] < L)
		{
			cnt -= 1 << (i - 1);
			E.emplace_back(i, N, cur + 1), cur += prefix[i];
		}

	printf("%d %d\n", N, SZ(E));
	for(auto it : E) printf("%d %d %d\n", it.u, it.v, it.w);
}

int main()
{
	input();
	solve();

	return 0;
}

