    int n = 1;
    int done = 1;
    while(true) {
        if (2 * done > L) {
            break;
        }
        n++;
        done *= 2;
    }

    int q = done / 2;
    for (int i = 1; i < n; i++) {
        edges.push_back({i*MUL+i+1, q});
        edges.push_back({i*MUL+i+1, 0});
        q /= 2;
    }
    int rest = L - done;

    while(rest > 0) {
        int add = 1;
        int to = n;
        while(true) {
            if (2 * add > rest) {
                break;
            }
            add *= 2;
            to--;
        }
        edges.push_back({1*MUL+to, done});
        rest -= add;
        done += add;
    }

    cout << n << " " << edges.size() << endl;
    for (auto e : edges) {
        cout << e.first / MUL << " " << e.first % MUL << " " << e.second << endl;
    }

