struct graph
{
	struct edge
	{
		int x,y,v;
	};
	edge g[1005];
	int p,q,n,cnt,f[1005],w[1005];
	void add(int x,int y,int v)
	{
		++cnt;
		g[cnt]=edge{x,y,v};
	}
	int check()
	{
		return p<=20&&q<=60;
	}
	void print()
	{
//		puts("-------");
		printf("%d %d\n",p,q);
		for (int i=1;i<=q;i++) printf("%d %d %d\n",g[i].x,g[i].y,g[i].v);
//		puts("-------");
	}
	void trans(int x,int base)
	{
		n=0;
		while (x)
		{
			f[++n]=x%base;
			x=x/base;
		}
		w[1]=1;for (int i=2;i<=n;i++) w[i]=w[i-1]*base;
//		printf("f:");for (int i=1;i<=n;i++) printf("%d ",f[i]);puts("");
//		printf("w:");for (int i=1;i<=n;i++) printf("%d ",w[i]);puts("");
		for (int i=1;i<=n/2;i++) std::swap(f[i],f[n-i+1]),std::swap(w[i],w[n-i+1]);
	}
	void solve(int l,int x)
    {
	    trans(l,x);
		p=1,q=0;
		int k=0;
		for (k=n;k>=1;k--)
		{
			if (f[k]!=x-1||k==0) break;
			for (int j=0;j<x;j++) add(p,p+1,w[k]*j),++q;
			p=p+1;
		}
		if (k==0) return;
		if (k==1)
		{
			for (int j=0;j<=f[1];j++) add(p,p+1,j*w[1]),++q;
			p=p+1;
			return;
		}
		for (int i=1;i<=k;i++)
		{
			if (i==1)
			{
			    for (int j=0;j<f[i];j++) add(p,p+1,w[i]*j),++q;
			    add(p,p+2,w[i]*f[i]),++q;
			    p=p+2;
			}
			else if (i==k)
			{
				for (int j=0;j<x;j++) add(p-1,p+1,w[i]*j),++q;
				for (int j=0;j<=f[i];j++) add(p,p+1,w[i]*j),++q;
				p=p+1;
			}
			else
			{
				for (int j=0;j<x;j++) add(p-1,p+1,w[i]*j),++q;
				for (int j=0;j<f[i];j++) add(p,p+1,w[i]*j),++q;
				add(p,p+2,w[i]*f[i]);++q;
				p=p+2;
			}
		}
	}
};
