  {
    Int tmp = L;
    Int x = 1;
    while(tmp){
      flag = false;
      if(tmp == x) flag = true;
      num.push_back(min(tmp, x));
      tmp -= num.back();
      s += num.back();
      cnt++;
      x *= 2;
    }     
  }
  if(flag == false)  s -= num.back();
