    {
        int total = (1 << n - i) - 1;
        if(total + val <= l - 1)
        {
            if(i != 1)
            edge.push_back({1, i, val});
            val += total + 1;
        }
    }
    cout << n << ' ' << edge.size() << '\n';
    for(auto i: edge) cout << i[0] << ' ' << i[1] << ' ' << i[2] << '\n';
}

