int main()
{
	scanf("%d",&l);
	int m=0,n=20;
	for(;m<19;)
	{
		m++;
		from[m]=m;
		to[m]=m+1;
		w[m]=0;
	}
	int i=1,cur=1;
	while(i*3<=l)
	{
		m++;
		from[m]=cur;
		to[m]=cur+1;
		w[m]=i;
		m++;
		from[m]=cur;
		to[m]=cur+1;
		w[m]=2*i;
		i=i*3;
		cur++;
	}
	int res=l-i,wgt=i,now=1;
	cur=1;
	while(res)
	{
		int x=res%3;
		if(x==1)
		{
			m++;
			from[m]=cur;
			to[m]=20;
			w[m]=wgt;
			wgt+=now;
			res--;
		}
		else if(x==2)
		{
			m++;
			from[m]=cur;
			to[m]=20;
			w[m]=wgt;
			m++;
			from[m]=cur;
			to[m]=20;
			w[m]=wgt+now;
			wgt+=2*now;
			res-=2;
		}
		res/=3;
		cur++;
		now*=3;
	}
	printf("%d %d\n",n,m);
	for(int i=1;i<=m;i++)
	{
		printf("%d %d %d\n",from[i],to[i],w[i]);
	}
