		edg.pb(make_pair(P(i+1,i+2),0));
		edg.pb(make_pair(P(i+1,i+2),_pow(2,(cnt-1-i))));
	}
	ll sum=0;
	for(ll i=cnt; i>=0; i--) {
		if(bi[i]&&i!=cnt) {
			m++;
			edg.pb(make_pair(P(1,n-i),sum));
		}
		if(bi[i]) sum+=_pow(2,i);
	}
	cout<<n<<" "<<m<<endl;
	REP(i,m) {
		cout<<edg[i].first.first<<" "<<edg[i].first.second<<" "<<edg[i].second<<endl;
	}
	return 0;
}

