int main() {
	int L;
	scanf("%d", &L);
	L--;

	vector <int> d;
	for (; L; L /= 4)
		d.push_back(L % 4);

	reverse(d.begin(), d.end());

	if (d.size() == 1) {
		printf("2 %d\n", d[0] + 1);
		for (int i = 0; i <= d[0]; i++)
			printf("1 2 %d\n", i);
		return 0;
	}

	int sz = d.size(), pot = 1;
	for (int i = 1; i < sz; i++)
		pot *= 4;

	for (int i = 0; i < sz - 1; i++) {
		if (i)
			for (int j = 0; j < 4; j++)
				add(2 * i, 2 * i + 2, pot * j);
		for (int j = 0; j < d[i]; j++)
			add(2 * i + 1, 2 * i + 2, pot * j);
		add(2 * i + 1, 2 * i + 3, pot * d[i]);
		pot /= 4;
	}

	for (int i = 0; i < 4; i++)
		add(2 * sz - 2, 2 * sz, pot * i);

	for (int i = 0; i <= d[sz - 1]; i++)
		add(2 * sz - 1, 2 * sz, pot * i);

	printf("%d %d\n", 2 * sz, ans.size());
	for (auto it : ans)
		printf("%d %d %d\n", it.u, it.v, it.w);

	return 0;
}

