string toBinary(int n)
{
    if (n <= 1) return to_string(n);
    return toBinary(n / 2) + to_string(n % 2);
}

int main()
{
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int L;
    cin >> L;

    L--;

    int x = 0;
    while (L >= (1 << x)) { x++; }

    int n = x + 1,
        m = (x - 1) * 2 + 1;
    for (char d : toBinary(L))
    {
        if (d == '1')
        {
            m++;
        }
    }

    if (L == 1)
    {
        cout << 2 << " " << 2 << endl;
        cout << 1 << " " << 2 << " " << 0 << endl;
        cout << 1 << " " << 2 << " " << 1 << endl;
        return 0;
    }

    cout << n - 1 << " " << m << endl;

    // 構築
    for (int u = 2; u + 1 <= n; u++)
    {
        cout << u - 1 << " " << u << " " << "0" << endl;
        cout << u - 1 << " " << u << " " << (1 << (n - (u + 1))) << endl;
    }
    // cout << 1 << " " << 2 << " " << 0 << endl;

    string bin = toBinary(L);
    reverse(bin.begin(), bin.end());

    int sum = 0;
    for (int i = bin.size() - 1; i >= 0; i--)
    {
        sum *= 2;
        if (bin[i] == '0') continue;

        // 最初じゃないときは張る
        if (i != bin.size() - 1)
        {
            cout << 1 << " " << (1 + (bin.size() - 1) - i) << " " << sum << endl;
        }
        sum += 1;
    }

    if (bin.back() == '1')
    {
        cout << 1 << " " << n - 1 << " " << sum << endl;
    }

    return 0;
}

