int pow(int n)
{
    if (n == 0) return 1;
    if (n%2 == 0) {
        int tmp = pow(n/2);
        return tmp * tmp;
    } else {
        return K * pow(n-1);
    }
}

int main(int argc, const char * argv[]) {
    int L;
    cin >> L;
