int powM(int x, int n){
  if(n == 0){
    return 1;
  }
  if(n % 2 == 0){
    return powM(mod(x * x), n / 2);
  }
  return mod(powM(x, n-1) * x);
}

void divide(vector<int>& num, int L)
{
  while (L > 0) {
    num.push_back(L % param);
    L /= param;
  }
}

void add_edge(vector< vector<edge> >& G, int u, int v, int c)
{
  G[u].push_back((edge){ v, c });
}

void solve(vector< vector<edge> >& G, int& idx, int n, int p)
{
  rep(i, 0, p) {
