ll calc_pos(ll level)
{
    ll pos = -1LL;
    assert(level > 0LL);

    while (level) {
        level >>= 1LL;
        pos++;
    }

    debug_printf("pos=%lld\n", pos);
    return pos;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll level; llin(level);

    ll n = calc_pos(level) + 1LL;

    V<t3> linklist;
    rep (i, n-1) {
        linklist.pb(t3(i, i+1, 0LL));
        linklist.pb(t3(i, i+1, (ll)pow(2LL, i)));
    }
    debug_printf("---- linklist\n");
    debug_print(linklist);

    level -= (ll)pow(2LL, n-1LL);
    ll length = (ll)pow(2LL, n-1LL);

    while (level) {
        ll pos = calc_pos(level);
        linklist.pb(t3(pos, n-1LL, length));
        length += (ll)pow(2LL, pos);
        level &= ~(ll)pow(2LL, calc_pos(level));
    }

    debug_printf("---- ans\n");
    printf("%lld %zu\n", n, linklist.size());
    for (auto link : linklist) {
        ll a = get<0>(link);
        ll b = get<1>(link);
        ll c = get<2>(link);
        printf("%lld %lld %lld\n", a, b, c);
    }
}

