vector<ll> factors(ll n) {
  vector<ll> res;
  for (ll i = 2; i * i <= n; ++i) {
    while (n % i == 0) {
      n /= i;
      res.pb(i);
    }
  }
  if (n > 1 || res.size() == 0) res.pb(n);
  return res;
}

