    if(L==0) return i<n&&ae(i,n,0);
    if(L==1) return ae(i,n,0),ae(i,n,1);
    if(L&1) return ae(i,i+1,0),ae(i,i+1,L+1>>1),solve(L>>1,i+1);
    else return ae(i,i+1,0),ae(i,i+1,L>>1),ae(i,n,L),solve(L-1>>1,i+1);
}
