const int N = 1e6 + 10;

int L, n, m, cnt;
int x[N], y[N], len[N], ext[N];

void dfs(int now, int L) {
	n = now;
	if (L == 1) return;
	if (L % 2 == 0) {
		x[++m] = now;
		y[m] = now + 1;
		len[m] = L / 2;
		x[++m] = now;
		y[m] = now + 1;
		len[m] = 0;
		dfs(now + 1, L - len[m - 1]);
	}
	else {
		x[++m] = now;
		y[m] = 0;
		len[m] = L - 1;
		L--;
		x[++m] = now;
		y[m] = now + 1;
		len[m] = L / 2;
		x[++m] = now;
		y[m] = now + 1;
		len[m] = 0;
		dfs(now + 1, L - len[m - 1]);
	}
}

int main() {
	cin >> L;
	dfs(1, L);
	cout << n << ' ' << m << endl;
	for (int i = 1; i <= m; ++i) {
		if (y[i] == 0) y[i] = n;
		cout << x[i] << ' ' << y[i] << ' ' << len[i] << endl;
	}
	return 0;
}

