struct edge {
    int from;
    int to;
    int cost;
    edge(int _from, int _to, int _cost) : from(_from), to(_to), cost(_cost){};
};

vector<edge> ans;

// [add, add + L)のバイパスを作る
void bypass(int L, int add) {
    // cout << L << ":" << add << endl;

    if (L <= 0) return;
    for (int i = 0; i < 20; ++i) {
        if (i < 18 && L >= (1 << i)) continue;
        // [add, add + 2^(i - 1))まで作れた
        ans.push_back(edge(i + 1, 20, add));
        bypass(L - (1 << (i - 1)), add + (1 << (i - 1)));
        return;
    }
    return;
}

int main() {
    int L;
    cin >> L;

    // 0の辺を全部張る
    for (int i = 1; i < 20; ++i) {
        ans.push_back(edge(i, i + 1, 0));
    }

    // 大まかにグラフを作る
    for (int i = 1; i <= 20; ++i) {
        if (i < 20 && L >= (1 << i)) {
            // [0, 2^i)まで作った
            ans.push_back(edge(i, i + 1, 1 << (i - 1)));
        } else {
            // [2^(i-1), L)を作る
            bypass(L - (1 << (i - 1)), 1 << (i - 1));
            break;
        }
    }

    cout << 20 << " " << ans.size() << endl;
    for (auto e : ans) {
        cout << e.from << " " << e.to << " " << e.cost << endl;
    }
    return 0;
}

