signed main() {
  int L;
  cin >> L;

  int n = 1, N = 1;
  while (n < L) {
    n *= 2;
    N++;
  }

  struct edge {
    int to, cost;
  };

  vector<vector<edge>> G(N + 1);

  int m = 2 * (N - 1);
  for (int i = 1; i < N; i++) {
    G[i].push_back({i + 1, 0LL});
    G[i].push_back({i + 1, bit(i - 1)});
  }

  for (int i = N - 1; i >= 1; i--) {
    if (L - bit(i - 1) >= bit(N - 1)) {
      G[i].push_back({N, L - bit(i - 1)});
      L -= bit(i - 1);
      m++;
    }
  }

  cout << N << " " << m << endl;
  for (int i = 1; i <= N; i++) {
    for (auto x : G[i]) {
      cout << i << " " << x.to << " " << x.cost << endl;
    }
  }

  return 0;
}

