};
note ext[max_e+1],ext2[max_e+1];
void add(note*ext,const int&l,const int&r,int&m){
	note x;
	for(int i=l; ++i<=r; ){
		x=ext[i];
		for(int j=x.w*x.k+x.tg; (j-=x.w)>=x.tg; e[++m]=node(x.u,x.v,j));
	}
}
