    read(L);
    int sum = 0;
    for (int i = 1, mult = 1; sum + mult <= L - 1; sum += mult, mult *= 2, i++) edges.pb({{i, i + 1}, mult});
    int curSz = sz(edges), cur = 1 << curSz, remCnt = L - cur;
