void pr(ll u, ll v, ll w) { e.push_back({u, v, w}); }

int main() {
  ll l;
  cin >> l;
  ll k = -1, c = 1;
  while (c <= l) {
    c *= 2;
    k++;
  }

  FOR(i, 1, k + 1) {
    pr(i, i + 1, 0);
    pr(i, i + 1, 1LL << (i - 1));
  }

  IFOR(i, 1, k + 1) {
    if (l - (1LL << (i - 1)) >= (1LL << k)) {
      pr(i, k + 1, l - (1LL << (i - 1)));
      l -= 1LL << (i - 1);
    }
  }

  cout << k + 1 << " " << SZ(e) << "\n";
  REP(i, SZ(e)) { printArray(e[i]); }
}

