	void adjust()
	{
		std::vector<edge> tmp;
		for (int i=0;i<g.size();i++) if (g[i].x&&g[i].y) tmp.push_back(g[i]);
		g.clear();
		for (int i=0;i<tmp.size();i++) g.push_back(tmp[i]);
		q=g.size();
	}
	int cmp(std::pair<int,int> p,std::pair<int,int> q)
	{
		int x1=p.first,y1=p.second,x2=q.first,y2=q.second;
		return val[cnt[x1][y1]]>val[cnt[x2][y2]];
	}
	void relabel()
	{
		std::vector<edge> tmp;
		toposort(1);
		for (int i=0;i<g.size();i++) tmp.push_back(edge{id[g[i].x],id[g[i].y],g[i].v,g[i].w});
		g.clear();
		for (int i=0;i<tmp.size();i++) g.push_back(tmp[i]);
	}
	void remake(int base)
	{
		std::priority_queue< std::pair<int,std::pair<int,int> > > pq;
		int start=1,end=p;
		for (int i=0;i<g.size();i++)
		{
			int xx=g[i].x,yy=g[i].y;
			++cnt[xx][yy];
			ww[xx][yy]=g[i].w;
			if (cnt[xx][yy]==1) h[xx][yy]=i;
		}
//		puts("cnt");
//		for (int i=1;i<=p;i++)
//		{
//			for (int j=1;j<=p;j++)
//			    printf("%d ",cnt[i][j]);
//			puts("");
//		}
		for (int i=1;i<=p;i++)
		    for (int j=1;j<=p;j++)
		        if (cansplit(cnt[i][j])) pq.push(std::make_pair(val[cnt[i][j]],std::make_pair(i,j)));
//		pre.push_back(std::make_pair(i,j));

//	    puts("qwq");
//		for (int i=0;i<pre.size();i++) printf("%d %d\n",pre[i].first,pre[i].second);puts("");
//        if (!pre.size()) return;
//		std::sort(pre.begin(),pre.end());
        int flag=0;
//        puts("qaq");
        int now=q;
		while (!pq.empty())
		{
			std::pair<int,int> v=pq.top().second;pq.pop();
		    if (p<limp)
			{
				int x1=v.first,y1=v.second;
				std::pair<int,int> r=split(x1,y1,cnt[x1][y1],ww[x1][y1]);
				h[x1][p]=now;h[p][y1]=now+r.first;now=now+cnt[x1][y1]-val[cnt[x1][y1]];
				if (cansplit(r.first)) pq.push(std::make_pair(val[r.first],std::make_pair(x1,p)));
				if (cansplit(r.second)) pq.push(std::make_pair(val[r.second],std::make_pair(p,y1)));
				flag=1;
			}
	    }
//	    puts("qwq");
	    if (!flag) return;
		adjust();
//		printf("%d %d\n",end,p);
		relabel();
	}
