	{
		c[i].solve(l-1,i);
		if (c[i].check())
		{
//			printf("base:%d\n",i);
			c[i].print();
			return 0;
		}
	    else
		{
			c[i].remake(i);
			if (c[i].check())
			{
//				printf("base:%d\n",i);
				c[i].print();
				return 0;
			}
//			return 0;
		}	
    }
	return 0;
}

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

int main() {
	int L;
	int N = 0;
	vector<int> bit;
	vector<pair<pair<int,int>, int>> g;

	cin >> L;

	while (L) {
		bit.push_back(L & 1);
		L >>= 1;
	}

	reverse(bit.begin(), bit.end());

	for (int i = 0; i < bit.size(); i++) {
		N *= 2;

		if (i) {
			for (int j = 0; j < g.size(); j++) {
				g[j].second *= 2;
			}
			g.push_back(make_pair(make_pair(i, i + 1), 1));
			g.push_back(make_pair(make_pair(i, i + 1), 0));
		}

		if (bit[i]) {
			g.push_back(make_pair(make_pair(0, i + 1), N));
			N++;
		}
	}

	for (int i = 0; i < g.size(); i++) {
		cout << g[i].first.first + 1 << " " << g[i].first.second + 1<< " " << g[i].second << endl;
	}

	return 0;
}

