ll L;
std::vector<std::pair<P, ll>> ps;

int main()
{
  std::cin >> L;

  ll t = L;
  ll b = 0;

  while( t > 0 )
  {
    t >>= 1;
    ++b;
  }

  rep( i, b )
  {
    if( i || L == (1<<b)-1 )
      ps.emplace_back( P( i+1, i+2 ), 1<<(b-i-1) );

    ps.emplace_back( P( i+1, i+2 ), 0 );
  }

  if( L != (1<<b)-1 ) repd( i, b-1 ) if( L>>i&1 )
  {
    ll cost = ((L^(1<<i))>>i)<<i;

    ps.emplace_back( P( 1, b-i+1 ), cost );
  }

  if( L == (1<<(b-1)) )
  {
    ps.emplace_back( P( 1, b+1 ), L );
  }

  std::cout << b+1 << ' ' << ps.size() << std::endl;

  for( auto p : ps )
    std::cout << p.first.first << ' ' << p.first.second << ' ' << p.second << std::endl;

  return 0;
}

