int main(void){
	int L;
	cin >> L;
	L--;

	int head = 0;
	while(((L + 1) >> head)) head++;
	//cout << head << endl;

	const int n = head;
	rep(i,n-1){
		graph[i].push_back({i+1,0});
		graph[i].push_back({i+1,(1<<i)});
	}

	vector<int> vertex(n,0);
	rep(i,n) vertex[i] = (1 << i) - 1;

	int lft = (1 << (n-1)), rht = L;

	rrep(i,n-1){
		const int val = (1 << i);
		const int len = rht - lft;
		if(len >= vertex[i]){
			graph[i].push_back({n-1,lft});
			lft += vertex[i] + 1;
		}
	}

	int m = 0;
	rep(i,n) m += graph[i].size();
	cout << n << " " << m << endl;
	rep(i,n) for(auto &e:graph[i]) cout << i + 1 << " " << e.to + 1 << " " << e.cost << endl;

	return 0;
}

