struct Edge {
    int from, to, len;
};
int main() {
    int L;
    cin >> L;
    vector<Edge> ans;
    int p = 1;
    for (int i = 0; i <= 16; i++) {
        ans.push_back({i, i + 1, 0});
        ans.push_back({i, i + 1, p});
        p *= 2;
    }
    // ~34本
    ans.push_back({17, 18, 0});
    ans.push_back({17, 18, p});
    ans.push_back({17, 18, 2 * p});
    // ~37本
    p *= 3;
    auto rem = [](int l, int p) -> int { return l % p == 0 ? 0 : l - (l % p);};
    for(int i = 0; i < 2 && L >= p; i++) {
        ans.push_back({18, 19, rem(L, p)});
        L -= p;
    }
    // ~39本
    p /= 3;
    for(int i = 0; i < 2 && L >= p; i++) {
        ans.push_back({17, 19, rem(L, p)});
        L -= p;
    }
    // ~41本
    for(int i = 17; i >= 0; i--) {
        if(L >= p) {
            ans.push_back({i, 19, rem(L, p)});
            L -= p;
        }
        p /= 2;
    }
    // ~59本

    cout << 20 << " " << ans.size() << endl;
    for(auto x : ans) {
        cout << x.from + 1 << " " << x.to + 1 << " " << x.len << endl;
    }
    return 0;
}

