string toBinary(int n)
{
    if (n <= 1) return to_string(n);
    return toBinary(n / 2) + to_string(n % 2);
}

int main()
{
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int L;
    cin >> L;

    L--;

    int x = 0;
    while (L >= (1 << x)) { x++; }

    int n = x + 1,
        m = (x - 1) * 2 + 1;
    for (char d : toBinary(L))
    {
        if (d == '1')
        {
            m++;
        }
    }

    if (L == 1)
    {
        cout << 2 << " " << 2 << endl;
        cout << 1 << " " << 2 << " " << 0 << endl;
        cout << 1 << " " << 2 << " " << 1 << endl;
        return 0;
