    cout << n - 1 << " " << m - 1 << endl;

    // 構築
    for (int u = 2; u + 1 <= n; u++)
    {
        cout << u - 1 << " " << u << " " << "0" << endl;
        cout << u - 1 << " " << u << " " << (1 << (n - (u + 1))) << endl;
    }
    // cout << 1 << " " << 2 << " " << 0 << endl;

    string bin = toBinary(L);
    reverse(bin.begin(), bin.end());

    int sum = 0;
    for (int i = bin.size() - 1; i >= 0; i--)
    {
        if (bin[i] == '0') continue;

        // 最初じゃないときは張る
        if (i != bin.size() - 1)
        {
            cout << 1 << " " << (1 + (bin.size() - 1) - i) << " " << sum << endl;
        }
        sum += (1 << i);
    }

    if (bin.back() == '1')
    {
        cout << 1 << " " << n - 1 << " " << sum << endl;
    }

    return 0;
}

