vector<PP> G[20];
int sub(int N, int i) {
	if (N == 2) {
		G[i].push_back(PP(i + 1, 1));
		G[i].push_back(PP(i + 1, 0));
		return 1;
	}

	if (N == 3) {
		G[i].push_back(PP(i + 1, 2));
		G[i].push_back(PP(i + 1, 1));
		G[i].push_back(PP(i + 1, 0));
		return 1;
	}

	int ret = sub(N / 2, i + 1);
	G[i].push_back(PP(i + 1, N / 2));
	G[i].push_back(PP(i + 1, 0));

	if (N % 2 == 1) {
		G[i].push_back(PP(i + ret + 1, N - 1));
	}
	return ret + 1;
}

