lint binary_search(lint max,function<bool(lint)> func) {
    lint left = -1;
    lint right =max;
    while (right - left > 1) {
        lint mid = left + (right - left) / 2;
        if (func(mid)) right = mid;
        else left = mid;
    }
    return right;
}

