    edges.push_back(mp(pii(i, i + 1), 0));
    edges.push_back(mp(pii(i, i + 1), pow(2, i - 1)));
    m += 2;
  }
  ll now = n - 1;
  while (now >= 1) {
    if (l - pow(2, n - 1) >= pow(2, now - 1)) {
      edges.push_back(mp(pii(now, n), l - pow(2, now - 1)));
      m++;
      l = l - pow(2, now - 1);
    }
    now--;
  }
  cout << n << " " << m << endl;
  rep (i, m) {
    cout << edges[i].first.first << " " << edges[i].first.second << " " << edges[i].second << endl;
  }
}

