            res[N-cur-2].push_back({N-i-1, c});
            ++M;
            c += (1<<i);
        }
    }

    cout << N << ' ' << M << '\n';
    for (int i=0; i<N; ++i) for (auto p : res[i]) cout << i+1 << ' ' << p.first+1 << ' ' << p.second << '\n';
}

