int mlb(int x) {
	if (x & 0xffff0000)
		x &= 0xffff0000;
	if (x & 0xff00ff00)
		x &= 0xff00ff00;
	if (x & 0xf0f0f0f0)
		x &= 0xf0f0f0f0;
	if (x & 0xcccccccc)
		x &= 0xcccccccc;
	if (x & 0xaaaaaaaa)
		x & 0xaaaaaaaa;
	return x;
}
int popc(int x) {
	x = (x & 0x55555555) + ((x >> 1) & 0x55555555);
	x = (x & 0x33333333) + ((x >> 2) & 0x33333333);
	x = (x & 0x0f0f0f0f) + ((x >> 4) & 0x0f0f0f0f);
	x = (x & 0x00ff00ff) + ((x >> 8) & 0x00ff00ff);
	x = (x & 0x0000ffff) + ((x >> 16) & 0x0000ffff);
	return x;
}
int main() {
	int l, n, m;
	scanf("%d", &l);
	if (popc(l) == 1) {
		n = popc(l - 1) + 1;
		m = (n - 1) * 2;
		printf("%d %d\n", n, m);
		for (int i = 2; i <= n; i++) {
			printf("%d %d %d\n", i - 1, i, 0);
			printf("%d %d %d\n", i - 1, i, l >> (i - 1));
		}
	}
	else {
		n = popc((mlb(l) << 1) - 1) + 1;
		m = (n - 2) * 2 + popc(l);
		printf("%d %d\n", n, m);
		for (int i = 3; i <= n; i++) {
			printf("%d %d %d\n", i - 1, i, 0);
