int power(int a, int N){
	if(N == 0){
		return 1;
	}
	else if(N % 2 == 0){
		return power(a * a, N / 2);
	}
	else{
		return a * power(a, N - 1);
	}
}

int rest(int *dig, int K, int s){
	int ans = 0, i;
	for(i = s + 1; i < K; i++){
		ans += dig[i] * power(3, i);
	}
	return ans;
}

