void solve(int L) {
  //L--;

  vector<pii> ps;
  for (int k = 0; k < 22; k++) {
    ps.emplace_back(1 << k, 1 << (k + 1));
  }

  int N;
  for (int k = 0; k < 22; k++) {
    if (ps[k].first <= L && L < ps[k].second) {
      N = k + 1;
      break;
    }
  }

  vector<E> es;
  for (int i = 1; i < N; i++) es.emplace_back(i, i + 1, 0);
  for (int i = 1; i < N; i++) es.emplace_back(i, i + 1, 1 << (i - 1));

  int b = 1 << (N - 1);
  while (b < L) {
    int x = L - b + 1;
    int s = 0;
    while ((1 << (s)) < x) {
      s++;
    }
    es.emplace_back(s, N, b);
    b += (1 << (s - 1));
  }

  assert(N <= 20);
  assert(es.size() <= 60);

  cout << N << " " << es.size() << endl;
  for (const auto& e : es) cout << e << endl;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int L;
  cin >> L;

  solve(L);

  return 0;
}

