    PrintWriter out;
    String INPUT = "";

    // static int mod = 1_000_000_007;
    int mod = 998244353;
    long inf = Long.MAX_VALUE/2;

    void solve(){
        int l = ni();
        int n = -1;
        int m = 0;
        for(int i = 1; i <= 20; i++){
            if((1<<i)>l){
                n = i;
                break;
            }
        }
        ArrayList<int[]>[] edge = new ArrayList[n];
        for(int i = 0; i < n; i++){
            edge[i] = new ArrayList<>();
        }
        edge[0].add(new int[]{1, 1});
        edge[0].add(new int[]{1, 0});
        m = 2;
        for(int i = 1; i < n-1; i++){
            edge[i].add(new int[]{i+1, 1<<i});
            edge[i].add(new int[]{i+1, 0});
            m+=2;
        }
        int dist = 1<<(n-1);
        int res = l - dist;
        for(int i = 20; i >= 0; i--){
            if((res>>i)%2==1){
                edge[i].add(new int[]{n-1, dist});
                m++;
                dist += 1<<i;
            }
        }
        out.println(n+" "+m);
        for(int i = 0; i < n; i++){
            for(int[] j : edge[i]){
                out.println((i+1)+" "+(j[0]+1)+" "+j[1]);
            }
        }
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.*;
import java.util.stream.*;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int l = in.nextInt(), n = 0;
		while(Math.pow(2, n) <= l) n++;
		List<Edge> list = new ArrayList<>();
		for(int i = 1; i < n; i++) {
			list.add(new Edge(i, i + 1, (int)Math.pow(2, i - 1)));
			list.add(new Edge(i, i + 1, 0));
		}
		int cost = (int)Math.pow(2, n - 1);
		int left = l - (int)Math.pow(2, n - 1) + 1;
		while(0 < left) {
			int t = 0;
			while(Math.pow(2, t + 1) <= left) t++;
			list.add(new Edge(t, n, cost));
			cost += (int)Math.pow(2, t);
			left -= (int)Math.pow(2, t);
		}
		System.out.println(n + " " + list.size());
		list.forEach(System.out::println);
	}
}

