public class Main {
	private static void solve() {
		int l = nei();

		int n;
		{
			int l2 = l;
			n = 0;
			while (l2 > 0) {
				l2 = l2 / 2;
				n++;
			}
		}

		ArrayList<int[]> edgs = new ArrayList<int[]>();
		for (int i = 1; i < n; i++) {
			edgs.add(new int[] { i, i + 1, 0 });
			edgs.add(new int[] { i, i + 1, 1 << (n - i - 1) });
		}

		{
			int l2 = l;
			int offset = 0;
			int width = 1 << n - 1;
			l2 -= width;
			offset += width;
			int to = 1;
			while (l2 > 0) {
				if (l2 >= width) {
//					System.out.println(offset + " " + to);
					edgs.add(new int[] { 1, to, offset });
					l2 -= width;
					offset += width;
				}
				width /= 2;
				to++;
			}
		}

		out(n + " " + edgs.size());
		for (int[] e : edgs) {
			out(e[0] + " " + e[1] + " " + e[2]);
		}
	}

	// returns (x, y, d) s.t. ax + by = d
	static long[] exgcd(long a, long b) {
		int sa = a < 0 ? -1 : 1;
		int sb = b < 0 ? -1 : 1;
		a *= sa;
		b *= sb;
		long x = 1;
		long y = 0;
		long z = 0;
		long w = 1;
		while (b > 0) {
			long q = a / b;
			long t = z;
			z = x - q * z;
			x = t;
			t = w;
			w = y - q * w;
			y = t;
			t = b;
			b = a - q * b;
			a = t;
		}
		return new long[] { x * sa, y * sb, a };
	}

