public class Main {


  private static void solve() {
    int l = ni();
    int n = 1;
    for (;(1 << (n + 1)) <= l; n ++);   

    List<int[]> edges = new ArrayList<>();
    for (int i = 0; i < n; i ++) {
      edges.add(new int[] {i + 1, i + 2, 0});
      edges.add(new int[] {i + 1, i + 2, 1 << i});
    }

    int now = 1 << n;
    for (int i = n; i >= 1; i --) {
      if (l - now  >= (1 << (i - 1))) {
        edges.add(new int[] {i + 1, n + 1, now});
        now += (1 << (i - 1));
      }
    }

    System.out.println(n + 1 + " " + edges.size());
    for (int[] e : edges) {
