 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int l = in.nextInt() - 1;

            int n = 20;
            for (int radix = 2; radix < 10; radix++) {
                boolean ng = false;

                char[] digits = Integer.toString(l, radix).toCharArray();
                List<int[]>[] g = new List[n];
                for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

                int idx = n - 1;
                for (int i = 0, v = 1; i < digits.length - 1; i++, v *= radix) {
                    idx--;
                    for (int r = 0; r < radix; r++) {
                        g[idx].add(new int[]{idx + 1, r * v});
                    }
                }

                for (int i = 0, j, k = 0; i < digits.length; i = j, k++) {
                    for (j = i + 1; j < digits.length && digits[j] == '0'; j++) {
                    }

                    if (j == digits.length) {
                        g[k].add(new int[]{n - 1, (digits[i] - '0') * (int) Math.pow(radix, digits.length - 1 - i)});
                    } else {
                        if (k + 1 >= idx) ng = true;
                        g[k].add(new int[]{k + 1, (digits[i] - '0') * (int) Math.pow(radix, digits.length - 1 - i)});
                    }
                    for (int jj = 0; jj < digits[i] - '0'; jj++) {
                        g[k].add(new int[]{idx + i, jj * (int) Math.pow(radix, digits.length - 1 - i)});
                    }
                }

                int edge = 0;
                for (List<int[]> e : g) {
                    edge += e.size();
                }

                if (edge > 60) ng = true;

                if (!ng) {
                    out.println(n + " " + edge);
                    for (int i = 0; i < n; i++) {
                        for (int[] e : g[i]) {
                            out.println((i + 1) + " " + (e[0] + 1) + " " + e[1]);
                        }
                    }
                    return;
                }
//            dump(radix, digits.length, digits, edge);
            }
            throw new RuntimeException();
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

