        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        D solver = new D();
        solver.solve(1, in, out);
        out.close();
    }

    static class D {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            for (int LL = 2; LL <= 16; LL++) {
                List<D.Edge> edges = solve(LL);
                System.err.println("");
                System.err.println("solving L = " + LL);
                for (D.Edge e : edges) {
                    System.err.println(e.x + " " + e.y + " " + e.w);
                }
            }

            int L = in.readInt();
            List<D.Edge> edges = solve(L);
            int n = 0;
            for (D.Edge e : edges) {
                n = Math.max(n, e.x);
                n = Math.max(n, e.y);
            }
            out.printLine(n + " " + edges.size());
            for (D.Edge e : edges) {
                out.printLine(e.x + " " + e.y + " " + e.w);
            }
        }

        private List<D.Edge> solve(int L) {
            int n = getVertCount(L);
            List<D.Edge> edges = new ArrayList<>();
            for (int i = 0; i < n - 1; i++) {
                edges.add(new D.Edge(i + 1, i, 0));
                edges.add(new D.Edge(i + 1, i, 1 << i));
            }
            System.err.println("L = " + L);
            if ((L & (L - 1)) == 0) {
                System.err.println("pow of 2 - 1, return");
                for (D.Edge e : edges) {
                    e.normalize(n);
                }
                return edges;
            }
            if (L == 6) {
                System.err.print("");
            }
            int rem = L - Integer.highestOneBit(L);
            int have = Integer.highestOneBit(L);
            while (rem > 0) { // L is not 2^n-1
                int bit = Integer.numberOfTrailingZeros(Integer.highestOneBit(rem));
                int first = have;
                int last = have + (1 << bit) - 1;
                int pw = 19;
                while (last + (1 << pw) - 1 > L) {
                    pw--;
                }
                System.err.println("rem = " + rem + ", have = " + have + ", first = " + first + ", last = " + last);
                edges.add(new D.Edge(n - 1, pw, have));
                rem -= 1 << bit;
                have += 1 << bit;
            }
            if (n < 1 || n > 20) {
                throw new AssertionError();
            }
            if (edges.size() > 60) {
                throw new AssertionError();
            }
            for (D.Edge e : edges) {
                e.normalize(n);
            }
            return edges;
        }

        private int getVertCount(int L) {
            return Integer.numberOfTrailingZeros(Integer.highestOneBit(L)) + 1;
        }

        static class Edge {
            int x;
            int y;
            int w;

            public Edge(int x, int y, int w) {
                this.x = x;
                this.y = y;
                this.w = w;
            }

            public void normalize(int n) {
                x = n - x;
                y = n - y;
            }

        }

    }

