		int tCnt = 28;
		while(s > 0) {
			s /= 2;
			tCnt--;
			if(rem > s) {
				rem -= s;
				ls.add(new Edge(cnt - tCnt, cnt - tCnt + 1, 1));
			}
		}

		for(int i=0;i<ls.size();i++) {
			Edge e = ls.get(i);
			out.println((e.from + 1) + " " + (e.to + 1) + " " + e.cost);

		}
