        private void Solve() {
            int L = inp.nextInt();
            int n = 0;
            int[] a = new int[30];
            for (int d = L; d > 0; d /= 2) {
                a[++n] = d % 2;
            }
            for (int i = 1; i <= n / 2; ++i) {
                int tmp = a[i];
                a[i] = a[n - i + 1];
                a[n - i + 1] = tmp;
            }

            Edge.n = n;
            List<Edge> ans = new ArrayList<>();
            for (int i = 1; i <= n - 1; ++i) {
                ans.add(new Edge(i, i + 1, 0));
                ans.add(new Edge(i, i + 1, 1 << (n - i - 1)));
            }
            for (int i = 1, t = 0; i <= n; ++i) {
                if (i > 1 && a[i] == 1) {
                    ans.add(new Edge(1, i, t));
                }
                t = t + (a[i] << (n - i));
            }

            out.println(n + " " + ans.size());
            for (Edge e: ans) {
                out.println(e.u + " " + e.v + " " + e.w);
