    static List<Edge> solve() {
        List<Edge> edges = new ArrayList<>();
        int cur = 20;

        while( L > 0 ) {
            if( L % 2 == 0 ) {
                int M = L / 2;
                int next = L == 2 ? 1 : cur-1;
                edges.add(new Edge(next, cur, M));
                edges.add(new Edge(next, cur, 0));
                cur = next;
                L = M;

            } else {
                if( L != 1 ) {
                    edges.add(new Edge(1, cur, L-1));
                }
                L--;
            }
        }
        return edges;
    }

