    static class D {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
//        for (int LL = 2; LL <= 16; LL++) {
//            List<Edge> edges = solve(LL);
//            System.err.println("");
//            System.err.println("solving L = " + LL);
//            for (Edge e : edges) {
