				System.out.println((i + 1) + " " + (i + 2) + " " + (base[i] + boost));
				boost = 0;
			}
			if (jump[i] != null) {
				if (!start) {
					boost = jump[i];
				} else {
					System.out.println((i + 1) + " " + (max + 1) + " " + jump[i]);
