    static void Solve()
    {
        var L = sc.ReadInt();
        var k = 0;
        var now = 1;
        while (now * 2 <= L)
        {
            now *= 2;
            k++;
        }
        var n = k + 1;
        var edges = new List<(int, int, int)>();
        for (int i = 0; i < k; i++)
        {
            edges.Add((i, i + 1, 1 << i));
            edges.Add((i, i + 1, 0));
        }
        for (int i = k; i > 0; i--)
        {
            var t2 = 1 << (i - 1);
            if (L - t2 >= (1 << k))
            {
                edges.Add((i - 1, n - 1, L - t2));
                L -= t2;
            }
        }
        Console.WriteLine(n + " " + edges.Count);
