class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
        //WriteLine(Solve());
    }
    static void Solve()
    {
        var l = Input.num;
        var r = -1;
        while ((1 << ++r) <= l) ;
        r = Min(r, 20);
        var ct = 2 * r-2;
        var ad = new List<string>();
        for(var i=r-1;i>=1;i--)
            if (l >= (1 << (i-1))+(1<<(r-1))) { l -= (1<<(i-1)); ct++;ad.Add($"{i} {r} {l}"); }
        WriteLine($"{r} {ct}");
        for (var i=1;i<r;i++)
        {
            WriteLine($"{i} {i + 1} 0");
            WriteLine($"{i} {i + 1} {1 << (i-1)}");
        }
        if(ad.Count!=0)
        WriteLine(string.Join("\n", ad));
    }
}

