class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int L = re.i();
        int p = 1;
        int e = 0;
        int n = 1;
        List<bool> B = new List<bool>();
        int c = 0;
        while(L != 1){
            if(L % 2 == 0){
                B.Add(true);
                L /= 2;
                c++;
            }
            else{
                B.Add(false);
                L--;
            }
        }
        for(int i=B.Count-1;i>=0;i--){
            if(B[i]){
                c--;
                Write(p,p+1,1 << c);
                Write(p,p+1,0);
                e += 2;
                n *= 2;
                p++;
            }
            else{
                Write(1,p,n << c);
                e++;
                n++;
            }
        }
        Console.WriteLine(p+" "+e);
    }
    void Write(int a,int b,int c){
        sb.Append(a);
        sb.Append(" ");
        sb.Append(b);
        sb.Append(" ");
        sb.Append(c);
        sb.Append("\n");
    }
}
