class P
{
    static void Main()
    {
        long l = long.Parse(Console.ReadLine());
        //if (l <= 60)
        //{
        //    for (int i = 0; i < l; i++)
        //        Console.WriteLine("{0} {1} {2}", 1, 2, i);
        //    return;
        //}
        List<long> ls = new List<long>();
        while (l > 0)
        {
            ls.Add(M(l));
            l -= (long)Math.Pow(2, M(l));
        }
        //foreach (var i in ls)
        //    Console.WriteLine(i);
        int n = (int)ls[0] + 1;
        List<string> answer = new List<string>();
        long m = 0;
        for (int i = 1; i < n; i++)
        {
            answer.Add(String.Format("{0} {1} {2}", i, i + 1, 0));
            answer.Add(String.Format("{0} {1} {2}", i, i + 1, (long)Math.Pow(2, i - 1)));
            m += 2;
        }
        for (int i = 1; ; i++)
        {
            try
            {
                long d = 0;
                for (int k = 0; k < i; k++)
                    d += (long)Math.Pow(2, ls[k]);
                string ans = String.Format("{0} {1} {2}", ls[i] + 1, n, d);
                answer.Add(ans);
                m++;
            }
            catch
            {
                break;
            }
        }
        Console.WriteLine("{0} {1}", n, m);
        foreach (var s in answer)
            Console.WriteLine(s);
        return;
    }
    static long M(long l)
    {
        long c = 0;
        while ((long)Math.Pow(2, c) <= l)
        {
            c++;
        }
        return c - 1;
    }
}

