namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static Tuple<int, int[][]> Solve(int L)
        {
            int N = 0;
            for (int i = L; i > 0; i >>= 1) { ++N; }
            var path = new List<int[]>();
            for (int i = 1; i <= N - 1; ++i)
            {
                path.Add(new[] { i, i + 1, 0 });
                path.Add(new[] { i, i + 1, 1 << (N - i - 1)});
            }
            int sum = 1 << (N - 1);
            for (int i = 0; i < N - 1; ++i)
            {
                if ((L & (1 << i)) != 0)
                {
                    path.Add(new[] { 1, N - i, sum });
                    sum += 1 << i;
                }
            }
            return new Tuple<int, int[][]>(N, path.ToArray());
        }
        static void Main(string[] args)
        {
            var ans = Solve(ReadInt());
            Console.WriteLine("{0} {1}", ans.Item1, ans.Item2.Length);
            foreach (var path in ans.Item2)
            {
                Console.WriteLine(string.Join(" ", path));
            }
        }
    }
}

