            var graph = new LengthGraphBuilder(20);
            for (int i = 0, len = 1; i < count; i++, len *= 2)
            {
                graph.Add(i, i + 1, 0);
                graph.Add(i, i + 1, len);
            }
            L -= p;
            var oldLen = p;
            var oldIndex = count;

            var x = count;
            while (L > 0)
            {
                for (; p > L; p /= 2, x--) { }
                graph.Add(x, count, oldLen);
                L -= p;
                oldLen += p;
            }

            var N = graph.ToArray().Where(ns => ns.Length > 0).ToArray();
            var M = N.SelectMany((c, i) => c.Select(n => $"{i + 1} {n.to + 1} {n.length}")).ToArray();
