			A[ct,0] = ct + 1;
			A[ct,1] = ct + 2;
			A[ct,2] = 0;
			ct += 1;
		}
		long at = 1;
		long ai = 0;
		while(at * 2 <= L){
			A[ct,0] = ai + 1;
