namespace Competitive
{
    internal class Solution
    {
        public int N;
        public List<int> direct;

        public void Run()
        {
            N = Input.ReadInt();

            direct = new List<int>();

            // 最後はN=1かN=2とする
            while (N >= 3)
            {
                int m = N % 3;
                direct.Add(m);
                N /= 3;
            }

            // 作成
            var ret = new List<Tuple<int, int, int>>(); // from, to, len
            int mul = 1;
            int to = 2;

            // 最初の辺
            for (int j = 0; j < N; j++)
            {
                ret.Add(Tuple.Create(to-1, to, j));
            }
            mul *= N;

            // ２個目以降
            for (int i = 0; i < direct.Count; i++)
            {
                int dir = direct[i];
                for (int j = 0; j < 3; j++)
                {
                    ret.Add(Tuple.Create(i + 2, i + 3, mul * j));
                }
                mul *= 3;

                for (int j = 0; j < dir; j++)
                {
                    ret.Add(Tuple.Create(1, i + 3, mul));
                    mul++;
                }
            }

            // Console.Error.WriteLine("-------------" + string.Join(", ", direct) + "-" + N);
            Console.WriteLine("{0} {1}", direct.Count + 2, ret.Count);
            for (int n = 0; n < ret.Count; n++)
            {
                Console.WriteLine("{0} {1} {2}", ret[n].Item1, ret[n].Item2, ret[n].Item3);
            }
        }
    }

