			int q=1,k=0,x=1;
			for(int i=2;i<6;i++){
				while(h3[i]>0&&q*i<=n){
					x++;
					q*=i;
					h3[i]--;
					k=i;
				}
			}
			while(k*q>n){k--;}
			for(int i=1;i<=k;i++){sb.Append(x+" "+p1+" "+(z1+q*(i-1))+"\n");}
			g-=1*k;
			n-=q*k;
			z1+=q*k;
		}
