			h2[d[a]]--;
			if(hs.Contains(q)){return;}
			hs.Add(q);
			m++;
			if(z1<q){
				z1=q;z2=p-1;z3=hn-d[a];
				Array.Copy(h2,h3,6);
			}
			return;
		}
		for(int i = a;i<d.Length;i++) {Fu(q,i,p+1,hn+d[i]);}
		h2[d[a]]--;
	}
