            foreach (var e in ans) g[e[0] - 1].Add(new KeyValuePair<int, int>(e[1] - 1, e[2]));
            var min = Enumerate(n, x => 1 << 22);
            var max = Enumerate(n, x => -1);
            var cnt = new int[n];
