var (
	l int
)

func main() {
	l = ReadInt()

	p := 1
	e := 0
	for p*2 <= l {
		p *= 2
		e++
	}
	PrintDebug("e: %d, p: %d\n", e, p)

	fmt.Println(e+1, e*2)
	for i := 0; i < e; i++ {
		fmt.Println(i+1, i+2, 0)
		fmt.Println(i+1, i+2, PowInt(2, i))
	}
	for i := e; i >= 0; i-- {
		v := PowInt(2, i)
		if l >= p+v {
			fmt.Println(i, e+1, l-v)
			l -= v
		}
	}
}

// PowInt is integer version of math.Pow
// PowInt calculate a power by Binary Power (二分累乗法(O(log e))).
func PowInt(a, e int) int {
	if a < 0 || e < 0 {
		panic(errors.New("[argument error]: PowInt does not accept negative integers"))
	}

	if e == 0 {
		return 1
	}

	if e%2 == 0 {
		halfE := e / 2
		half := PowInt(a, halfE)
		return half * half
	}

	return a * PowInt(a, e-1)
}

