use v6;

sub cut-digit(@ds, $n) {
  my @copy = @ds.clone;
  @copy[^$n] = 0 xx $n;
  +('0b' ~ @copy.reverse.join);
}

my @digits = (+get).base(2).comb.reverse;
my $branch = @digits.grep(1) + +(@digits.head == 0);
my $last = +@digits + 1;

say "{+@digits} {$branch + (+@digits - 1) * 2}";

say "$_ {$_ + 1} {2 ** ($_ - 1)}\n$_ {$_ + 1} 0" for 1 .. (+@digits - 1);

say "{+@digits} $last 0";

say "1 $last {cut-digit(@digits, 0)}" if @digits.head == 0;

for @digits.head(+@digits - 1).kv -> $i, $d {
  next if $d == 0;
  say "{$i + 2} $last {cut-digit(@digits, $i + 1)}";
}

