void main() {
  long L;
  scanln(L);

  long N = 20;
  Vertex[] vs = N.iota.map!(i => new Vertex(i)).array;
  foreach(i; 0..N-1) {
    if ((L>>(N-i-1)) > 0) {
      vs[i].edges ~= Edge(vs[i], vs[i+1], 0L<<(N-i-2));
      vs[i].edges ~= Edge(vs[i], vs[i+1], 1L<<(N-i-2));
    }
  }

  void g(long i, long j, long s) {
    if (s >= L) return;
    if (j >= N) return;
    if ((L-s) >= (1L<<(N-j-1)) && (L-s) < (1L<<(N-j))) {
      vs[i].edges ~= Edge(vs[i], vs[j], s);
    } else {
      g(i, j+1, s);
      g(i, j+1, s+(1L<<(N-j-2)));
    }
  }
  void f(long i, long j) {
    if (j >= N) return;
    if ((L>>(N-j)) == 0) {
      vs[i].edges ~= Edge(vs[i], vs[j], 0);
      f(j, j+1);
    }
    if ((L>>(N-j-1)) == 1) {
      g(i, j, (1L<<(N-j-1)));
    }
  }

  f(0, 1);

  long M = vs.map!(v => v.edges.length).sum;
  if (M > 60) vs[1000];// error
  writeln(N, " ", M);
  foreach(v; vs) {
    foreach(e; v.edges) {
      writeln(e.start.index+1, " ", e.end.index+1, " ", e.value);
    }
  }
}

