            int to = i + 1;
            if (to > N) to = N;
            G[0] ~= tuple(to, tmp);
            tmp += 1 << (N-i-1);
        }
    }

    G[0] ~= tuple(N, tmp);
    G[1] ~= G[0];

    writeln(N, " ", N.iota.map!(i => G[i].length).sum);
    foreach (i; 1..N) {
        foreach (j; G[i]) {
            writeln(i, " ", j[0], " ", j[1]);
