    if (j >= N) return;
    if ((L>>(N-j)) == 0) {
      vs[i].edges ~= Edge(vs[i], vs[j], 0);
      f(j, j+1);
    }
    if ((L>>(N-j-1)) == 1) {
      g(i, j, (1L<<(N-j-1)));
    }
  }

  f(0, 1);

  long M = vs.map!(v => v.edges.length).sum;
  if (M > 60) vs[1000].index.writeln;// error
