void main() {
  long L;
  scanln(L);

  long N = 20;
  Vertex[] vs = N.iota.map!(i => new Vertex(i)).array;
  foreach(i; 0..N-2) {
    vs[i].edges ~= Edge(vs[i], vs[i+1], 0L<<i);
    vs[i].edges ~= Edge(vs[i], vs[i+1], 1L<<i);
  }

  foreach(i; 0..N-1) {
    if (L>>i&1) {
      L -= 1L<<i;
