void main() {
    auto L = readln.chomp.to!int;
    L -= 1;
    int N = L.bsr + 1;
    auto A = new int[](N);
    auto G = new Tuple!(int, int)[][](N);

    if (L <= 10) {
        writeln(2, " ", L+1);
        foreach (i; 0..L+1) {
            writeln(1, " ", 2, " ", i);
        }
        return;
    }

    foreach (i; 1..N) {
        G[i] ~= tuple(i+1, 0);
    }

    foreach (i; 1..N) {
        G[i] ~= tuple(i+1, 1<<(N-i-1));
    }


    int tmp = 1 << (N - 1);

    foreach (i; 1..N) {
        if (A[N-i-1] == 1) {
            int to = i + 1;
            if (to > N) to = N;
            G[0] ~= tuple(to, tmp);
            tmp += 1 << (N-i-1);
        }
    }

    G[0] ~= tuple(N, tmp);
    G[1] ~= G[0];
    G[0] = [];

    writeln(N, " ", N.iota.map!(i => G[i].length).sum);
    foreach (i; 1..N) {
        foreach (j; G[i]) {
            writeln(i, " ", j[0], " ", j[1]);
        }
    }
}

void main(){
  import std.stdio, std.string, std.conv, std.algorithm;

  int k; rd(k);

  int n=1;
  while((1<<n)<=k) n++;
  struct E{int u, v, w;}
  E[] edges;
  int w=0;
  for(int i=1; i<n; i++){
    edges~=E(i, i+1, 0);
    edges~=E(i, i+1, 1<<(i-1));
    w+=(1<<(i-1));
  }

  if(w<(k-1)){
    w=0;
    for(int i=1; i<=n; i++){
      if((k-1)&(1<<(i-1))){
        edges~=E(i-1, n, (1<<(n-1))+w);
        w+=(1<<(i-1));
      }
    }
  }

  writeln(n, " ", edges.length);
  foreach(e; edges){
    writeln(e.u, " ", e.v, " ", e.w);
  }
}

