use std::collections::{BTreeSet, VecDeque};

fn main() {
    input!(l: usize);

    let graph = solve(l);
    validate(&graph, l);

    let num = graph.iter().map(|edges| edges.len()).sum::<usize>();
    println!("{} {}", graph.len(), num);

