        r += 1;
    }

    assert!(1 <= 19);

    let n = r + 1;
    let mut graph = vec![vec![]; n];
    for i in 0..r {
        graph[i].push((i, i + 1, 0));
        graph[i].push((i, i + 1, 1 << i));
    }

    let sum = (1 << r) - 1;
    let mut upper = l;
    for i in (0..(n - 1)).rev() {
        let sub_sum = (1 << i) - 1;
        if upper >= sub_sum + 1 {
            let new_edge = upper - sub_sum - 1;
            graph[i].push((i, n - 1, new_edge));
            upper = new_edge;
        }
    }

    println!("{} {}", n, graph.iter().map(|g| g.len()).sum::<usize>());
    for g in graph.into_iter() {
        for (u, v, w) in g.into_iter() {
            println!("{} {} {}", u + 1, v + 1, w);
        }
    }
}

