fn rec(l: i64, r: i64, a: i64, ret: &mut Vec<(i64, i64, i64)>) {
    if a <= 1 {
        return;
    }

    if a % 2 == 1 {
        ret.push((l, r, a - 1));
        rec(l, r, a - 1, ret);
    } else {
        ret.push((l, l + 1, a / 2));
        ret.push((l, l + 1, 0));
        rec(l + 1, r, a / 2, ret);
    }
}

