fn solve(l: usize) -> (Vec<(usize, usize, usize)>, usize) {
    let mut ans = Vec::new();

    let mut acc = Vec::new();

    for i in 0.. {
        let k = 1 << i;
        if k > l { break }
        if (k & l) > 0 {
            acc.push((i,k));
        }
    }

    let (i, r) = acc.pop().unwrap();

    for j in 1..(i+1) {
        ans.push((j, j+1, 0));
        ans.push((j, j+1, 1 << (j-1)));
    }

    let mut r = r;
    for &(_, k) in acc.iter().rev() {
        ans.push((k, i+1, r));
        r += k;
    }

    (ans, i+1)
}

