        ($format:expr, $($args:expr),+) => (write!(out,$format,$($args),*).unwrap())
    }
    input!{ l: usize }
    let mut pool = Vec::new();
    let mut tmp = l;
    for i in (0 .. 19).rev() {
        if tmp == 1 {
            pool.push((i, i + 1, 0));
            continue;
        }
        pool.push((i, i + 1, tmp / 2));
        pool.push((i, i + 1, 0));
        if tmp % 2 == 1 {
            pool.push((0, i + 1, tmp - 1));
        }
        tmp /= 2;
    }
    puts!("{} {}\n", 20, pool.len());
    for (u, v, w) in pool {
        puts!("{} {} {}\n", u + 1, v + 1, w);
    }
}

