    let mut sc = Scanner { reader: sc.lock() };
    let mut l: usize = sc.read();

    let mut pow2 = vec![1; 30];
    for i in 1..pow2.len() {
        pow2[i] = pow2[i - 1] * 2;
    }

    let mut r = 1;
    while pow2[r + 1] <= l {
        r += 1;
    }
    let r = r as usize;
    let n = r + 1;
    let mut graph = vec![vec![]; n];
    for i in 0..(n - 1) {
        graph[i].push((i + 1, 0));
        graph[i].push((i + 1, pow2[i]));
    }

    for t in (1..n).rev() {
        if l >= pow2[t - 1] + pow2[r] {
            let x = l - pow2[t - 1];
            l -= pow2[t - 1];
            graph[t + 1].push((n - 1, x));
        }
    }

    let mut edges = vec![];
    for from in 0..n {
        for &(to, weight) in graph[from].iter() {
            edges.push((from, to, weight));
        }
    }

    println!("{} {}", n, edges.len());
    for &(from, to, w) in edges.iter() {
        println!("{} {} {}", from + 1, to + 1, w);
    }
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

