        while k <= l {
            l -= k;
            edges.push((i as usize, 19, offset));
            offset += k;
        }
    }
    assert_eq!(l, 0);
    println!("20 {}", edges.len());
    for &(a, b, w) in &edges {
        println!("{} {} {}", a+1, b+1, w);
    }
}

