use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn with_stdout_lock<F: FnOnce(std::io::BufWriter<std::io::StdoutLock>)>(f: F) {
    let out = std::io::stdout();
    let w = std::io::BufWriter::new(out.lock());
    f(w);
}

fn main() {
    let l: i64 = input();

    let mut e = vec![];
    g(l, &mut e);

    with_stdout_lock(|mut w| {
        let n = e.len() + 1;
        let m: usize = e.iter().map(|e| e.len()).sum();
        writeln!(w, "{} {}", n, m).unwrap();
        for u in 0..n - 1 {
            for &(v, d) in &e[u] {
                writeln!(w, "{} {} {}", u + 1, v + 1, d).unwrap();
            }
        }
    });
}

fn g(l: i64, e: &mut Vec<Vec<(usize, i64)>>) {
    if l == 2 {
        e.push(vec![(1, 0), (1, 1)]);
    } else if l % 2 == 0 {
        g(l / 2, e);
        for u in 0..e.len() {
            for v in 0..e[u].len() {
                e[u][v].1 *= 2;
            }
        }
        let n = e.len();
        e.push(vec![(n + 1, 0), (n + 1, 1)]);
    } else {
        g(l - 1, e);
        let n = e.len();
        e[0].push((n, l - 1));
    }
}

