    let mut r: u32 = 1;
    loop {
        if 2i32.pow(r) - 2 >= l {
            break;
        }
        r += 1;
    }
    let r = r - 1;
    let mut edges = Vec::new();

    for i in 1..r + 1 {
        edges.push((i, i + 1, 0));
        edges.push((i, i + 1, 2i32.pow(i - 1)));
    }

    let mut cur_max = 2i32.pow(r) - 1;
    // println!("cur max {:?}", cur_max);
    let mut res = l - cur_max;

    for t in (1..r).rev() {
        // println!("res {:?}", res);
        if res >= 2i32.pow(t - 1) {
            edges.push((t, r, cur_max + 1));
            cur_max += 2i32.pow(t - 1);
            res = l - cur_max;
        }
    }
    println!("{0} {1}", r + 1, edges.len());
    for edge in edges {
        let (s, t, c) = edge;
        println!("{0} {1} {2}", s, t, c);
    }
}

