fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let l: usize = sc.read();

    let n = 20;
    let sink = n - 1;
    let mut graph = vec![vec![]; n];
    for i in 0..(n - 2) {
        graph[i].push((i, i + 1, 0));
        graph[i].push((i, i + 1, 1 << i));
    }

    let mut upper = l;
    for i in (0..(n - 1)).rev() {
        let sum = (1 << i) - 1;
        if upper < sum + 1 {
            continue;
        }
        let new_edge = upper - sum - 1;
        graph[i].push((i, sink, new_edge));
        upper = new_edge;
    }

    let edges = graph.iter().map(|graph| graph.len()).sum::<usize>();

    println!("{} {}", n, edges);
    for graph in graph.into_iter() {
        for (x, y, w) in graph.into_iter() {
            println!("{} {} {}", x + 1, y + 1, w);
        }
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use proconio::input;

fn main() {
    input!(n: usize);
    fn dfs(n: usize) -> (usize, Vec<(usize, usize, usize)>) {
        if n == 1 {
            (1, vec![])
        } else {
            let mut ans = dfs(n / 2);
            ans.1.iter_mut().for_each(|(_, _, w)| *w *= 2);
            ans.0 += 1;
            ans.1.push((ans.0 - 2, ans.0 - 1, 0));
            ans.1.push((ans.0 - 2, ans.0 - 1, 1));
            if n % 2 == 1 {
                ans.1.push((0, ans.0 - 1, n - 1));
            }
            ans
        }
    }
    let (sz, ans) = dfs(n);
    println!("{} {}", sz, ans.len());
    for (u, v, w) in ans {
        println!("{} {} {}", u + 1, v + 1, w);
    }
}

