fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let l = i.read::<usize>();

    let (nodes, g) = solve(l);
    writeln!(o, "{} {}", nodes, g.len()).unwrap();
