pub fn solve(mut l: usize) -> (usize, Vec<(usize, usize, usize)>) {
    let mut g = Vec::new();
    let mut nodes = 1;
    let mut b = 1;
    while b * 2 <= l {
        g.push((nodes, nodes + 1, 0));
        g.push((nodes, nodes + 1, b));
        nodes += 1;
        b *= 2;
    }
    if l != b {
        let mut bn = nodes;
        let mut w = b;
        l -= b;
        loop {
            if l >= b {
                g.push((bn, nodes, w));
                l -= b;
                if l == 0 {
                    break;
                }
                w += b;
            }
            b /= 2;
            bn -= 1;
        }
    }
    (nodes, g)
}

