struct InfiniteLoopDetector(i32);

impl InfiniteLoopDetector {
    fn check(&mut self) {
        #[cfg(debug_assertions)]
        {
            self.0 += 1;
            if self.0 >= 10_000 {
                panic!("infinite loop?")
            }
        }
    }
}

fn main() {
    let mut det = InfiniteLoopDetector(0);

    const R: usize = 4;

    let L = read!(usize);

    let mut es = vec![];

    let mut h = 0;
    let mut p = 1;
    while p * R <= L {
        p *= R;
        h += 1;

        // det.check();
    }
    let N = h + 1;

    let mut q = p;
    for i in 1..N {
        q /= R;

        for k in 0..R {
            es.push((i, i + 1, k * q));
        }
    }

    // s 未満の経路は生成済み
    let mut s = p;

    let mut j = 1;

    while s < L {
        let t = L - s;
        while p > t {
            p /= R;
            h -= 1;
            j += 1;

            // det.check();
        }

        es.push((1, j, s));
        s += p;

        // det.check();
    }

    let M = es.len();

    if N > 20 {
        panic!("too many vertices");
    }

    if M > 60 {
        panic!("too many edges");
    }

    println!("{} {}", N, M);
    for (u, v, w) in es {
        println!("{} {} {}", u, v, w);
    }
}

