    while t > 1 {
        len += 1;
        t /= 2;
    }

    let mut ans = vec![];
    rec(0, len - 1, l, &mut ans);

    println!("{} {}", len, ans.len());
    for &(a, b, c) in ans.iter() {
        println!("{} {} {}", a + 1, b + 1, c);
    }
}

