fn main() {
    let l: i64 = read::<i64>() - 1;
    let mut po = 1;
    let mut n = 1;
    while po * 2 <= l {
        po *= 2;
        n += 1;
    }
    let mut ans: Vec<(i64, i64, i64)> = Vec::new();
    let mut now = 1;
    for i in 1..n {
        ans.push((i, i + 1, 0));
        ans.push((i, i + 1, now));
        now *= 2;
    }
    for i in 1..n {
        now /= 2;
        let j = n - i;
        if l >= po + now - 1 && po > now {
            ans.push((j, n, po));
            po += now;
        }
    }
    println!("{} {}", n, ans.len());
    for i in &ans {
        println!("{} {} {}", i.0, i.1, i.2);
    }
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

