macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

use std::collections::{BTreeSet, VecDeque};

fn main() {
    input!(l: usize);

    let graph = solve(l);
    validate(&graph, l);

    let num = graph.iter().map(|edges| edges.len()).sum::<usize>();
    println!("{} {}", graph.len() + 1, num);

    for from in 0..graph.len() {
        for &(to, cost) in graph[from].iter() {
            println!("{} {} {}", from + 1, to + 1, cost);
        }
    }
}

fn validate(graph: &Vec<Vec<(usize, usize)>>, l: usize) {
    let mut q = VecDeque::new();
    q.push_back((0, 0));
    let goal = graph.len();
    let mut set = BTreeSet::new();
    while let Some((v, dist)) = q.pop_front() {
        if v == goal {
            assert!(!set.contains(&dist));
            assert!(dist < l);
            set.insert(dist);
            continue;
        }
        for &(next, cost) in graph[v].iter() {
            q.push_back((next, cost + dist));
        }
    }
    assert!(set.len() == l)
}

fn solve(l: usize) -> Vec<Vec<(usize, usize)>> {
    let mut graph = vec![];
    for i in 0.. {
        let length = 1 << i;
        let max_dist = (length << 1) - 1;
        if max_dist > l {
            break;
        }
        graph.push(vec![]);
        assert!(graph.len() == i + 1);
        graph[i].push((i + 1, length));
        graph[i].push((i + 1, 0));
    }
    graph.push(vec![]);
    let goal = graph.len();

    let mut l = l;
    for i in (0..graph.len()).rev() {
        let dist = (1 << i) - 1;
        if l >= dist + 1 {
            let x = l - 1 - dist;
            graph[i].push((goal, x));
            l -= dist + 1;
        }
    }
    graph
}

use std::io::{BufRead, BufWriter, Write};

fn main() {
    let stdin = std::io::stdin();
    let stdout = std::io::stdout();
    solve(&mut stdin.lock(), &mut BufWriter::new(stdout.lock()));
}

fn solve<R: BufRead, W: Write>(stdin: &mut R, stdout: &mut BufWriter<W>) {
    let ell = stdin.gets().parse::<usize>().unwrap();
    let mut n = 0;
    while (1 << n) <= ell {
        n += 1;
    }
    let base = (1 << n - 1) - 1;
    let mut edges = Vec::new();
    for i in 0..n - 1 {
        edges.push((i, i + 1, 0));
        edges.push((i, i + 1, 1 << i));
    }
    let mut rem = ell - 1 - base;
    let mut i = 0;
    let mut next = base + 1;
    while rem > 0 {
        if rem % 2 == 1 {
            edges.push((i, n - 1, next));
            next += 1 << i;
        }
        rem /= 2;
        i += 1;
    }
    writeln!(stdout, "{} {}", n, edges.len()).unwrap();
    for (f, t, c) in edges {
        writeln!(stdout, "{} {} {}", f + 1, t + 1, c).unwrap();
    }
}

