fn solve(l: usize) -> (Vec<(usize, usize, usize)>, usize) {
    let mut ans = Vec::new();

    let mut acc = Vec::new();

    for i in 0.. {
        let k = 1 << i;
        if k > l { break }
        if (k & l) > 0 {
            acc.push((i,k));
        }
    }

    let (i, r) = acc.pop().unwrap();

    for j in 1..(i+1) {
        ans.push((j, j+1, 0));
        ans.push((j, j+1, 1 << (j-1)));
    }

    let mut r = r;
    for &(j, k) in acc.iter().rev() {
        ans.push((j+1, i+1, r));
        r += k;
    }

    (ans, i+1)
}

fn main() {
    let l = parse_line!(usize);

    let (s, n) = solve(l);
    println!("{} {}", n, s.len());

    for (a,b,c) in s {
        println!("{} {} {}", a, b, c);
    }
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let l: usize = sc.read();

    let mut r = 0;
    while (1 << (r + 1)) <= l {
        r += 1;
    }

    let sum = (1 << r) - 1;
    let n = r + 1;
    let mut graph = vec![vec![]; n];
    for i in 0..r {
        graph[i].push((i + 1, 1 << i));
        graph[i].push((i + 1, 0));
    }

    let mut l = l;
    for i in (0..(n - 1)).rev() {
        let to_i = (1 << i) - 1;

        if l >= sum + 1 + (to_i + 1) {
            let t = l - (to_i + 1);
            graph[i].push((n - 1, t));
            l = t;
        }
    }

    let mut ans = vec![];
    for i in 0..n {
        for &(next, w) in graph[i].iter() {
            ans.push((i, next, w));
        }
    }

    println!("{} {}", n, ans.len());
    for &(i, next, w) in ans.iter() {
        println!("{} {} {}", i + 1, next + 1, w);
    }
}

