// -----------------------------------------------

fn main() {
    const R: usize = 4;

    let L = read!(usize);

    let mut es = vec![];

    let mut h = 0;
    let mut p = 1;
    while p * R <= L {
        p *= R;
        h += 1;
    }
    let N = h + 1;

    let mut q = p;
    for i in 1..N {
        q /= R;

        for k in 0..R {
            es.push((i, i + 1, k * q));
        }
    }

    // s 未満の経路は生成済み
    let mut s = p;

    // j に到達すると長さ p 以下の経路が列挙される
    let mut j = 1;

    // debug!((p, s, j));

    while s < L {
        let t = L - s;

        while p > t {
            p /= R;
            h -= 1;
            j += 1;
        }

        // debug!((p, s, t, j));

        // t + p 未満の経路が生成される
        es.push((1, j, s));

        s += p;
    }

    let M = es.len();

    if N > 20 {
        panic!("too many vertices");
    }

    if M > 60 {
        panic!("too many edges");
    }

    println!("{} {}", N, M);
    for (u, v, w) in es {
        println!("{} {} {}", u, v, w);
    }
}
